-- GENERATED by `wfj generate` from data/quest/quest-0005.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [5001] = { "Bijou's Belongings", "Bijou's Belongingsを見つけて彼女に返して下さい。頑張って下さい!", "普段は{race}とは取引しないんだけど、どうやらトロールと岩の間に挟まれちまったみたいでね。いいかい、ここでの私の任務はHordeにとって最重要なんだ。でも私が掴んだ情報は、Allianceの安泰にも関わってくる。言っとくけど、私はAlliance寄りなんかじゃない。けど、Blackrockの脅威はただのオークの集まりどころじゃないんだ。\n\n私の持ち物を見つけて助けてくれたら、あんたの仲間の役に立ちそうな情報で助けてやるよ。\n\n取引成立？", "どうだった?", "なんとまあ！いったいどこにあったんだ？？", 0xb62123b7, 0xb905391b, 0x6060e58e, 0x87e6d3ba, 0xb600db21, "....." },
  [5002] = { "Maxwellへの言伝", "Burning Steppesへ向かい、Marshal MaxwellにBijou's Informationを渡して下さい。", "あたしは約束を守るゴブリンだよ、{race}。さあ、よく聞いて。\n\nこのオークたちは主に、黒竜の一族の荷役獣や捨て駒として使われてるんだ!\n\n奴らの本当の指導者は、ほかでもないDeathwingの子、Nefarianさ。それに、城塞のこの区画にいるNefarianの手下たちの居場所も突き止めたよ。\n\nこの地図をBurning SteppesにいるMarshal Maxwellのところへ持って行って。あいつらの居場所に印をつけて、すぐ分かるようにしてあるからね。", "ああ、{name}。久しぶりだな。", "これは我々がすでに知っていたことの多くと一致する。とはいえ、興味深く、そしてやや不運なinformationではある。\n\nこの地図に記された印は、Blackrockの脅威を削ぐのに役立つだろう。", 0xd738e388, 0x9f2ff06a, 0x01a3d183, 0x8dba76de, 0x762d90e6, "....." },
  [5021] = { "遅くともやらないよりはまし", "幽霊の女のとりとめのない話によると、彼女は包みを届けてほしいらしい。包みは彼女の馬のいる場所にあると言っていた。馬がどこにいるのか、包みをどこへ届けるのか――幽霊の話はまったく要領を得ない。", "「荷物を届けなくては……ここに閉じ込められる前に届けなくては！」\n\n取り乱した女性の叫び声が、ささやきのように家の中を漂ってくる。二階の隅に、女性の亡霊がうずくまっている。彼女は周囲の状況をはっきりとは分かっていないようで、あなたの存在にもぼんやりとしか気づいていない。\n\n「私の荷物を届けに来てくださったの？お願い、これ以上ひどくなる前に！馬に乗ってここを出るつもりだったの。荷物はまだ馬のそばにあるはずよ……それとも、もう手遅れなのかしら？」", nil, "他の状況なら見落としていたかもしれない納屋の中の包みが、今は腐敗と荒廃の中で目を引く。これこそJanice Felstoneの幽霊が騒ぎ立てていたものかもしれない……", 0x1d1c5dd8, 0x70391ade, 0x3a27de2c, nil, 0x45c650cb, "...m." },
  [5022] = { "遅くともやらないよりはまし", "Royal Factors of Stormwindに問い合わせて、Emma Felstoneという人物の居場所を調べる。City Hallにはたいてい国勢調査の士官がいる。", "あなたは荷物を拾い上げ、その上に積もった薄いほこりと汚れを拭い取る。宛名は急いだ筆跡で、StormwindのEmma Felstoneという人物に宛てられており、荷物の配達日付は四年以上も前になっている。\n\nEmma Felstoneが生きているかどうかさえ定かではないが、Stormwind City Hallが町の住民の記録を保管していることは広く知られている。それはRoyal Factors of the Stormwind Censusが取り扱っている。", "Stormwind国勢調査局へようこそ。住民に関する情報が必要でしたら、お手伝いいたします。", "Emma Felstone宛ての包みだって？ 最後に分かっている住所はStormwind、4年前？ さて、見てみようか……\n\n分かっている限りでは、4年ほど前、この街にEmma Felstoneという人物がいた。いや、可能性があると言うべきかな。私が参照しているこの住民台帳は5年前のもので、彼女が街を出たという報告は手元にない。だからといって、彼女がまだここにいるとは限らないがね。\n\nちょっと待てよ……この包み、まさかOl' Emma宛てじゃないだろうな？", 0x1d1c5dd8, 0xdcdc7598, 0xf0839606, 0x5991a2dc, 0x06b012f4, "....." },
  [5023] = { "遅れても来ないよりはマシ", "UndercityのRoyal Overseerと相談して、Jeremiah Felstoneの居場所を掴んで下さい。通常、census officerはguild and tabard registrationの近くにあります。", "あなたは小包を拾い上げ、その上に積もっていた薄い埃と汚れを拭い取る。宛先は急いだ筆跡でLordaeronのJeremiah Felstoneという人物になっており、小包の配達日は4年以上も前の日付だ。\n\nJeremiah Felstoneがまだ生きているのかさえ定かではないが、かつてLordaeronとして知られたUndercityが街の住民の記録を保管していることは広く知られている。これはRoyal Overseers of the Undercity Censusが扱っている。", "Undercity国勢調査局の手を借りに来たのか、それとも知り合いが死んでいるかどうか聞きに来ただけか? よく聞かれるんだ。", "Jeremiah Felstoneという者宛ての小包で、最後に判明している住所はLordaeronか……力になれると思う。\n\nJeremiah Felstoneは疫病の前、この街にいた。いや、かつてのJeremiah Felstoneと言うべきだな――Forsakenの中には、以前の面影を捨て去るために姓を変えた者がいる。この件も例外ではない。かつてのJeremiah Felstoneは、今はJeremiah Paysonとして知られている。\n\n待てよ……あいつはゴキブリを売っている商人じゃないか?", 0x1d1c5dd8, 0x19871f59, 0x2f752d9b, 0x8ef887b9, 0x0cd06198, "....." },
  [5041] = { "Crossroadsへの物資", "Crossroads' Supply Cratesを探し出して、BarrensのThorkに届けましょう。", "あの隊商への襲撃で、我々がどうしても必要としていた物資が奪われた。\n\n君はこれまで勇敢にもRazormane族に立ち向かってくれた。もう一度そうしてほしいのだが、今度は、失われた物資にも目を配ってもらえないだろうか。おそらく奴らの野営地のあちこちで見つかるだろう。quilboarどもは卑劣な行いで肥え太っているのだ。\n\nCrossroadsの民は君に恩を感じるだろう。", "suppliesの捜索はどうだ、{name}? quilboarどもなど、お前の力なら容易く倒せるだろう。", "ハハ！ありがとう、{name}！これは大いに助かる。お前はCrossroadsにとっても、Hordeにとっても恵みだ。何か俺にできることがあれば、遠慮なく言ってくれ。", 0x4b2a9bbe, 0x69fcf120, 0x11724923, 0x89163eaf, 0xd476a085, "....." },
  [5042] = { "Agamagganの力", nil, nil, "Agamagganの力を望むなら、blood shardsが4つ必要だ、{race}。\n\nこの祝福を授かれば、敵どもはお前の力の前にすくみ上がるだろう。<鼻を鳴らす>\n\nRazormaneの最も偉大なウォリアーたちは、その力に満たされているのだ!", "Mangletoothが自由の身で、自分を裏切った者どもをお前が討ち滅ぼすのを見られたらよかったのだがな! <鼻を鳴らす>\n\nこのshardsを集めてBristlebackをさらに滅ぼしてくれたことに感謝する。どうか続けてくれ。俺も助力を続けよう。<鼻を鳴らす>", 0x0b63dce6, nil, nil, 0x7cbc8fc6, 0x4c396d41, ".mm.." },
  [5043] = { "Agamagganの敏捷性", nil, nil, "我が部族の最も優れた斥候たちは、その正確さで並ぶ者がないと言われている。戦いでの素早さでは、どんなローグ<鼻を鳴らす>も彼らには及ばん。\n\nblood shardsを4つ持ってこい。そうすれば、生まれながらのどのquilboarよりも身軽にしてやろう。", "お前の狙いが外れることなく、お前の武器の跡が確かであらんことを、{race}。\n\nAgamagganの魂がお前と共にある。望むなら <鼻を鳴らす> また俺のところへ戻ってこい。偉大なるboarの神が俺をふさわしいと認めれば、Mangletoothがまたお前に祝福を与えよう。<鼻を鳴らす>", 0xbfb78098, nil, nil, 0xbf6c88ce, 0x3cf06179, ".mm.." },
  [5044] = { "Agamagganの智恵", nil, nil, "quilboarの部族のシャーマンや地占い師たちは<鼻を鳴らす>、戦いや儀式の助けとしてAgamagganの力を呼び求めるのだ、{race}。\n\nお前も呪文にAgamagganの祝福の力を加えたいなら、blood shardsを4つ持ってこい。そうすればMangletoothが力を貸してやる。<鼻を鳴らす>", "お前の敵は、お前をさらに恐れることになるだろう、{race}。<鼻を鳴らす>\n\n次に会うときは――この世でも、次の世でも――Mangletoothに戦での抜け目なさの話を聞かせてくれ。<鼻を鳴らす>", 0x2493ca20, nil, nil, 0x07bb03e2, 0x30cb7a53, ".mm.." },
  [5045] = { "高揚する魂", nil, nil, "あらゆる種類のウォリアー<鼻を鳴らす>には強い精神が必要だ。すべての望みが失われたとき、それがより大きな偉業へと駆り立てる。<鼻を鳴らす>Razormaneもそれを知らぬわけではない。我らは精神を重んじる部族だ。戦いでの腕前<鼻を鳴らす>よりも、Agamagganとのつながりをこそ誇りにしている。\n\nblood shardsを4つ持ってこい。そうすれば戦いに向けてお前の精神を祝福してやろう。<鼻を鳴らす>", "我らの最も偉大なウォリアーも、最も偉大な <鼻を鳴らす> シャーマンも、お前の意志を羨むだろう、{race}。\n\n奴らにはお前を止められないと知って、Bristlebackをさらに討ち倒すがいい! <鼻を鳴らす>", 0x67558646, nil, nil, 0xb9f5d16c, 0xc40eb9eb, ".mm.." },
  [5046] = { "Razorhide", nil, nil, "戦いに<鼻を鳴らす>赴く者は皆、守りを必要とする。骨は強くなければならん。皮膚は硬くなければならん。<鼻を鳴らす>我が部族もそれをよく知っている。だから針と皮が与えてくれる生まれつきの守りに加えて、<鼻を鳴らす>戦に出る前にはよくAgamagganに災いから守ってくれるよう呼びかけるのだ。\n\nblood shardsを4つ<鼻を鳴らす>持ってこい。そうすればお前にも同じ守りを授けてやろう。", "戦いに行け、{race}。", 0x41b394c0, nil, nil, 0x24679bfc, 0xd6cd4420, ".mm.." },
  [5047] = { "Pip Quickwit、ご用件をどうぞ!", "EverlookのMalyfous Darkhammerに話しかけて下さい。", "Malyfous DarkhammerはEverlookにいるよ、{class}。'Pipはピンピンしてる'、それとスーツは完璧に動くって伝えてくれ。\n\nそれから、これを渡してくれ。\n\n<Pipが光る肉片をあなたに手渡す。>\n\n俺の'休暇'中に、あの獣の腹の中からかっぱらってきたんだ。\n\nMalyfousなら、こんな怪物の部位で何が作れるか、かなり正確に見立ててくれるはずだよ！\n\nおっと、Everlookがどこにあるか知らないんだっけ？ Winterspringへだよ、相棒！", "なんだ?", "生きてる? スーツもちゃんと働いてるって? それで、ここにあるのは何だ?", 0x7e03d8eb, 0x2f591ac4, 0x6063c392, 0x0c079f52, 0x909b86e3, ".....", nil, nil, 0xe0b81e59, nil, nil },
  [5048] = { "気立てのいいEmma", "StormwindでOl' Emmaを見つけ、彼女が本当にEmma Felstoneなのか確かめる。もしそうなら、Janice Felstoneが彼女のために作った包みを喜んで受け取ってくれるかもしれない。", "ちょっとばかり気難しいし、頭がどうかしてるかもしれないが……記録によれば、Ol' EmmaはEmma Felstoneらしき人物の条件にちゃんと当てはまるんだ。\n\n町をうろついてるOl' Emmaを見かけたことがあるかもしれないな。独り言を言ってて、たいていは訳の分からないことをしゃべってる。それでも何かや誰かを傷つけるわけじゃないから、みんなだいたい放っておいてるんだ。\n\nいろいろ考え合わせると、Ol' Emmaは実際にEmma Felstoneだと言っていいだろう。彼女の姓が本当にFelstoneなのか、聞いてみるといい。", "うちの芝生から出ていけと言いたいところだが、見ての通り芝生なんてないんだ。", "私の名前は確かにEmma Felstoneよ。その名前で呼んでくれたのは、何年ぶりかしら。あなた……あなたは誰？\n\n私の……姉妹を知っていたですって？！ あの子はまだ生きているの？ 何を言ってるのかしら、生きているわけがないわ。Lordaeronで疫病が広がったとき、最悪の事態は覚悟していたの。家族の大勢が死んだ……いえ、もっとひどいことになった。そして今の私は、頭のおかしいOl' Emma、ひとりぼっち。あなたは何なの、墓荒らしか何か？ 次の獲物を探しているの？\n\n何ですって……姉妹から私宛ての包みを持っているの？", 0x54e3cb36, 0xcab0ca91, 0x6b6f28a3, 0x8b85f199, 0x6b8bbfec, "....." },
  [5049] = { "Jeremiahの憂鬱", "UndercityにいるJeremiah Paysonを見つけ、本当にJeremiah Felstoneかどうかを調べて下さい。もし彼であれば、Janice Felstoneが彼のために作った小包を欲しがるでしょう。", "私が集められた証拠からすると、あなたの探している人物――そして小包の本来の受取人――は、Undercityのゴキブリ売り、Jeremiah Paysonです。\n\n私は常々、ゴキブリを……売るには特別な才能が要ると考えております。きっとあなたは今、実に壮大な旅の途上にあるのでしょう、偉大なる{class}よ。世界を形作るあなたの偉業のお邪魔はいたしません。ですが、あなたの大作の一端を担わせていただき、お教えしましょう。彼は銀行の近く、通路の一つの下で、いかにも似つかわしく這いつくばっておりますよ。", "誰かがゴキブリを踏むたびに、私は泣いてしまうんだ。どうか私を泣かせないで。", "その名前はもう何年も使っていない……だが、そうだ。人生のある時点で――この輝かしい不死の身になる前は――それが私の姓だった。\n\n私の姉を知っていたと言うのか……いや、最近姉と話したと。\n\nもう死んでいる姉と。\n\n4年も前に。\n\nなあ、私の骨がこれほどもろくなければ、この足をへし折ってでもあんたの尻を蹴り飛ばしてやりたいところだ。あんたはまったく、ハゲタカのような奴だな?\n\n何……姉から私宛ての小包があるだと?", 0xbe8b1cef, 0x0e42b052, 0x05312067, 0xf8f8bac4, 0x3755ef66, "....." },
  [5050] = { "Good Luck Charm", "Western PlaguelandsのJanice FelstoneにGood Luck Half-Charmを返して下さい。", "どうやらあなたのことを誤解していたようだ、{name}。そのことはお詫びしなければ。姉が身の回りの品をいくつも送ってきてね、おかしなことに、その中にはFelstoneの農場の権利書まであった。今のところ、取り戻すのはやめておこうと思う。\n\nもし姉の魂が農場に縛られて安らげずにいるのなら、どうか……これを彼女に返してもらえないだろうか。彼女が持っていた幸運のお守りの片割れで、もう片方は彼女の夫が持っていたんだ。\n\nこれらの品を私が持っていると知れば、彼女の魂もようやく安らげるかもしれない。", "John、あなた……そこにいるの? 急にとても寒くなってきたわ……", "あなたはhalf-charmを亡霊に返す。彼女はそれを見つめ、それからあなたを期待の眼差しで見る。\n\n「あなた、あなたの方のcharmの片割れはどこにやったの? 両方が揃わないと、私たちは一緒にいられないのよ。あなた……私が見えるの?」", 0x5a377e71, 0x9e16a7c6, 0x9652e8b3, 0xf293a279, 0xdb61f9a5, "....." },
  [5051] = { "ふたつをひとつに", "Western PlaguelandsのFelstone Farmのどこかで、Good Luck Charmのもう半分を見つけ、元どおりに組み合わせる。\n\nGood Luck CharmをWestern Plaguelands、Felstone FarmのJanice Felstoneに渡して下さい。", "哀れな幽霊のうわごとは続く。\n\n「とても寒いわ、John。あなたのお守りを持ってきて、そうすれば一緒になれる！ 急いで、John、疫病が来て私たちをおぞましい獣に変えてしまう前に！ あなたが見えないの、John……でも近くにいるのは分かる。そばにいるのを感じるの。」\n\nお守りのもう半分を見つけて元通りに組み合わせれば、それこそがJanice Felstoneの霊が求めているものになるのかもしれない。", "John、ghoulsに捕まらないで……ghoulsに私を捕まえさせないで……忌まわしいghouls……私たちのcharmが守ってくれるわ。", "あなたは組み直したgood luck charmをJanice Felstoneの亡霊に手渡す。彼女がそれを握った途端、ほとんど即座に彼女に変化が現れる。その霊体の姿は揺らめき、彼女は澄んだ、それでいて悲しげな目であなたを見つめる。\n\n「私を解き放ってくれたのね……もうこのcharmは要らないわ。どうか受け取って。私に与えてくれた安らぎを、あなたにも与えてくれるかもしれないから。」", 0xa34e95f1, 0xc71af3bd, 0xf0bffb94, 0xdb1e717d, 0xa724f59a, "....." },
  [5052] = { "AgamagganのBlood Shard", "BarrensのCamp TaurajoにいるMangletoothにBlood Shardを渡して下さい。\n\n彼からAgamaggan's powerを授かりたいのであれば、さらにBlood Shardを集めて下さい。", "棘とともに、「血」は大地に別の形で、フン、影響する。血のように赤い石には別の鉱物が混ざっているんだ。Bristlebackはそのかけらを掘り出して、フン、戦いの力のトーテムや魔法のトーテムとして持ち歩いている。フン。\n\nオレは魔法の秘密を知ってるぜ。\n\nMangletoothにblood shardをひとつ持ってきて、分かってるってことを見せてくれ。Mangletoothにかけらをたくさん持ってきな。そうしたら、quilboarの魔法……Agamagganの魔法をかけてやるよ!フン。", "我らの部族はBarrens中のいばらの地に集まる<鼻を鳴らす>。そこが聖地だからだ。だがRazorfenほど神聖な場所はない。Razorfenのすべては、Agamagganの体でできている。<鼻を鳴らす>中でもDownsは特に守られている。入口が彼の巨大な顎でできているからだ! <鼻を鳴らす>彼に忠誠を誓わぬ者は丸呑みにされ、噛み砕かれた後に体を吐き出されるのだ! <鼻を鳴らす>\n\nAgamagganは我らを守るために自らの体を残し、我らが彼を守れるよう、その魂を分け与えてくれるのだ。<鼻を鳴らす>", "ああ、分かってくれたか。フン。オレの言ったことが耳に届いてたようだな、{race}。Mangletoothは檻の中でも、Agamagganの力を止められる檻なんてありゃしないんだ!\n\nかけらの感触、かけらのこの感じ……久しぶりだ、{race}。\n\nどんな感じか分かるか?　お前は、自分の力と離れ離れにされたことがあるか?\n\nいや、それは別のときに話すことだ。オレは教えると約束した。お前にAgamagganの力を約束した。仲間はMangletoothに背を向けたんだ。今、お前を奴らに解き放ってやる。", 0xb007b4a5, 0x0721e680, 0xcdb0e5ac, 0xb95880b0, 0x95e10b3f, "....." },
  [5054] = { "ShardtoothのUrsius", "EverlookのStorm ShadowhoofはUrsiusを殺すよう求めています。", "北西、Winterspringの雪深い山々で、熟練のハンターが獲物を追っている……shardtooth bearsのUrsius、敏捷で賢い獣のことだ。\n\n今、そなたを彼のもとへ差し向ける。彼はEverlookの北西のなだらかな丘陵をうろついている。そなたの意図に気づかれる前に、見つけ出して狩るのだ。\n\nUrsiusに挑んだ者は皆、たちまち自らが獲物となり、彼こそがハンターとなった。油断するでないぞ。", "さあ行きなさい、{class}。Ursiusを探し出すのです。", "決して容易いことではなかったけれど、君は優れていたのだな。だが、私に感銘を与えたと早合点しないことだ、{name}。", 0x2d87691c, 0x584134b3, 0x37176232, 0xed33f70d, 0x995c5073, "....." },
  [5055] = { "ChillwindのBrumeran", "EverlookのStorm Shadowhoofは、Brumeranを殺すよう求めています。", "素早く賢いBrumeranは、Winterspring南部の雪原を音もなく滑空する。だが、その優雅な姿に騙されて無害だと思ってはならぬ。彼女に立ち向かう者は皆、大きな代償を払い、しばしば自らの命でそれを払うことになる。\n\nchimeraの中からchillwindのBrumeranを探し出せ。彼女を倒し、再び我のもとへ戻るのだ。", "Brumeranがあなたを呼んでいます、{name}。", "そうだ。戻ってきたな。今や私は、そなたが生まれながらの真のハンターだと信じている。そなたは最も獰猛な生き物に立ち向かい、私の期待を超えて戻ってきた。\n\nそなたはもう、私の最後の頼みを受ける支度ができている。", 0x5897dde2, 0x1afc51dd, 0x5a42a2b5, 0xbd73e20c, 0x9c722726, "....." },
  [5056] = { "Shy-Rotam", "EverlookのStorm ShadowhoofはShy-Rotamを倒すよう求めています。", "Winterspringの北部では、大型の猫たちがFrostsaber Rockと呼ばれる大きな目印の周りに集まっている。この猫たちの長はShy-Rotamという名で知られている。frostsabersの女家長を倒せば、同じ{race}の仲間たちから大いに尊敬されるであろう。\n\n再び過酷な荒野へ赴き、そこでfrostsabersから神聖な肉を集めよ。Shy-Rotamの石を見つけ、そこに肉を置くのだ。彼女の同族の肉を捧げれば、Shy-Rotamが怒りとともに現れるであろう。\n\n彼女の怒りに備え、打ち倒すのだ。", "Shy-Rotamは大胆で容赦がありません。彼女は熱烈な勢いで同族を守るでしょう。", "君は力と決断力の両方を証明してみせた。もっと多くの試練が待ち受けているけれども、私が君に示せるものはすでに示してしまったよ。", 0xe75213da, 0x782e1d52, 0x88f9b80b, 0x832ddc24, 0x6e86fee9, "....." },
  [5057] = { "過去の努力", "Thunder BluffのMelor StonehoofにStorm Shadowhoof's Markerを渡して下さい。", "そなたが我に話しかける前から、{name}、そなたの功績は耳にしていた……自らを証明しようという揺るぎない意志を持ち、{class}として並外れた能力を持っているとな。そして今、それが真実であると知った。\n\nそなたのように秀でた者は称えられるに値する。この証をThunder BluffにいるMelor Stonehoofという我が友に届けるのだ。彼はきっとそなたのことを、そしてそなたが遠い昔に成し遂げたことを覚えているであろう。最近の勝利について彼に語り、今日成し遂げたことを決して忘れるでないぞ。", nil, "人は人生の経験から学ぶものだ、{name}。そなたもまた、自らの経験ゆえに強く、賢くなったに違いない。初めて言葉を交わした時から、そなたは大きく成長した。\n\n{race}の{class}として成し遂げた困難な務めの記念に、これを受け取るがよい。そして、そなたには常に我が敬意と称賛があることを知っておくのだ。", 0x223a5993, 0xbde5b62f, 0xfff4bf10, nil, 0xcac05ca4, "...m." },
  [5058] = { "Mrs. Dalsonの日記", nil, nil, nil, "黄ばんだページの日記が、最後の書き込みのところで開かれている。\n\n「Haroldが変わり果ててしまった今、これからどうなるのか分からない。彼をしっかり閉じ込めておける唯一の場所に引きずり込むのに、力を使い果たした。鍵は私が隠し持っている。うまくいくように祈るばかりだ……\n\nここから逃げ出したいけれど、それにはお金が要る。私たちの持ち物は全部あの戸棚の中だと思う……そういえば、その鍵はHaroldが持っているんじゃなかったか？\n\n少し休んで考えよう。もう死ぬほど疲れた。」", 0x79b50b15, nil, nil, nil, 0x04f8236d, ".mmm." },
  [5060] = { "閉じ込められて", nil, nil, "目の前には極めて頑丈な戸棚があり、備え付けの錠でしっかりと閉ざされている。戸棚の前面には深い引っかき傷や痕が刻まれている。戸棚が今は人目から隠している秘密を暴こうとして、何度も乱暴に試みては失敗した跡だと推測できる。\n\nこの戸棚を開けるつもりなら、鍵を見つける必要がある。", "Farmer Dalsonのghoulと化した亡骸から取った鍵は、錠にぴったりと合う。戸棚の扉が開き、無傷のまま残った、かなり価値がありそうな品がいくつか現れる。", 0x41d8cf5e, nil, nil, 0x65ca593a, 0xc4ba31d6, ".mm.." },
  [5061] = { "Aquatic Form", "Darnassusへ戻り、Mathrengyl BearwalkerにPendant of the Sea Lionを見せて下さい。", "駆け出しのドルイドが水生動物の姿を身につける前に教わるべき修行は、すべて終わった。さあ、DarnassusのMathrengyl Bearwalkerのところへ戻りなさい。彼にそのペンダントを見せ、教わるべきものを習得する準備ができていると示すのだ。習得が済めば、水と一体となることができよう。\n\nさらば、若きドルイドよ。再び語り合おう。", "あなたがDarnassusへ戻ることは知らされていました。ですが、水棲形態を教える前に、Moongladeで学んだことの証が必要です。\n\nPendant of the Sea Lionは持っていますか?", "大変見事です、{name}。aquatic formを習得する準備ができていますね。これを伝えることができて、私も嬉しいですよ。\n\nまた、二つの試練の功績を認め、この品を差し上げましょう。自然の庇護者、均衡の番人としての装備に加えれば、きっと喜んでいただけると思います。", 0xb41f2b6a, 0x8aa8f24e, 0x489ae05e, 0x5ac3a51a, 0xd9b19ec7, "....." },
  [5062] = { "神聖な炎", "10ブッシェルのIncendia Agaveを集め、ThunderbluffのElder RiseにいるMagatha Grimtotemに相談して下さい。", "Arikaraは迅速に対処せねばならない恐ろしい生き物だ。蛇を追い詰めるには、Arikaraを召喚する命の炎を灯さねばならんだろう。\n\n今すぐに、Incendia agaveという珍しい植物を刈り取ってきてくれ。agaveをたくさん集めたら、Thunder BluffのElder RiseにいるMagatha Grimtotemに助言を求めるんだ。彼女は、agaveに魔法をかけて命の炎を灯す粉を作ることのできる、強力な呪術師だ。\n\n北東のBoiling Poolへ行ってIncendia Agaveを集めてきてくれ。", "では、Motega FiremainがArikaraの知らせを寄こしたのだな……それは重大な知らせだ。\n\n<Magathaが辺りを見回す。>\n\nArikaraは、凶悪な行いをした者たちに復讐することだけを求めて生まれた、恐ろしい生き物だ。\n\n<Magathaが微笑む。>", "いいでしょう。必要な量のIncendia agaveを集めてきたのですね。Thousand Needlesにしかないこの貴重な薬草は、眠っている命の炎を灯すのを助けてくれることでしょう。\n\n<MagathaはIncendia agaveに魔法をかけ始めた。>", 0x9dc5fce0, 0x70d40b13, 0x0a6138b7, 0x33505e7f, 0xf61de319, "....." },
  [5064] = { "Grimtotem族への密偵活動", "Darkcloud PinnacleでSecret Note3枚を探し、入手して下さい。", "{name}、君は私たちをよく助けてくれたから、重要な任務を任せる。Grimtotem族は何か秘密を隠そうとしている。最近数週間にわたって、出所不明の3人の工作員がGrimtotem族を訪れているのが目撃されているんだ。我々は、Darkcloud Pinnacleにある別々の箱に手紙が保管されていることをつかんだ。\n\n{name}、この危険な任務を成功させたら、それ相応の報酬を渡そう。", "Grimtotemが何を企んでいるか、突き止めたか?", "偉大なる精霊のトーテムよ! これはまったくひどい知らせだ。どんな物がやって来てもいいように、計画を立て始めなくては。\n\n{name}、約束した通り、勇敢な奉仕に対する報酬だよ。", 0x1d41db0b, 0xb48b2b0b, 0xe2051aef, 0xeadd4ac5, 0x5057c83b, "....." },
  [5065] = { "Mosh'aruの失われし石板", "TanarisのProspector Ironbootに、Third Mosh'aru TabletとFourth Mosh'aru Tabletを渡して下さい。", "君が話したトロールは真実を語らなかった。彼のために手に入れた2枚の石板にはHakkarの精髄を封じることが記されていたが、その伝説には続きがある。私は長く研究し、Tablets of Mosh'aruは2枚ではなく6枚あることを突き止めた！ 6枚だ！\n\nそして、残りの石板がどんな秘密を秘めているのか、それを知るのが恐ろしい……\n\nMosh'aruの三枚目と四枚目の石板を見つけてくれ。それらはEastern Plaguelandsにあり、mossflayerのトロールたちが持っている。見つけ出し、私のところへ持ってきてくれ。", "tabletsは持っていますか? その文面が、私たちの世界への大きな脅威を明らかにするのではないかと恐れています。", "見つけたのか! 素晴らしい!\n\nありがとう、{name}。この文書をじっくり読んで、その意味を解き明かそう。\n\nだが、君にはもう一つ務めがある……", 0xe77103e4, 0xdbd88b64, 0xfd9f868d, 0xfb0acacc, 0x5da12bd6, "....." },
  [5066] = { "召集令：Plaguelands！", "Commander Ashlam Valorfistを探し出して下さい。彼の拠点はAlterac Mountainsの北にあるChillwind Campだ。", "聞け、聞け！すべての英雄よ、この言葉に耳を傾けよ！\n\nKingdom of Stormwindより召集令が発せられた！戦える者は皆、Eastern Kingdomsの北方の地でScourgeの暗き脅威に対して武器を取るよう求められている！Plaguelandsの廃墟から新たな脅威が生まれているとの噂が飛び交っているのだ！\n\n王国の英雄たちよ――Alterac Mountainsの北、Chillwind Campに本陣を構えたCommander Ashlam Valorfistのもとを訪ねよ！", nil, "Plaguelandsへようこそ、英雄よ。ここはAzerothで最も危険な辺境の1つだ。特に、北と北東にはScourgeの脅威が迫っている。義務と大義への奉仕を告げる呼び声が、君の耳に届かなかったわけではないと聞いて嬉しいぞ！\n\n手を汚す覚悟があるなら、このPlaguelandsの境には、意欲と力のある英雄がやるべきことがいくらでもある。", 0x7b917538, 0x754a0fb2, 0xc77e27ed, nil, 0xb7a1f1f9, "...m." },
  [5081] = { "Maxwellの任務", "Blackrock Spireへ行き、War Master Voone、Highlord Omokk、Overlord Wyrmthalakを倒してください。仕事が終わったらMarshal Maxwellのところへ戻ってください。", "この情報で、Blackrock Spireに関する我々の申し分ない情報網の穴が埋まった。\n\n攻撃は決定的なものでなければならん、{name}。\n\nまず奴らの戦闘指揮官、トロールのVooneを倒さねばならん。奴の作戦がなければ、Blackrockのオークどもは混乱に陥るだろう。\n\n次にogreのHighlord、Omokkを始末しろ。Blackrockの臆病なogreどもは、奴の統率がなければ無力だ。\n\n最後に城塞の支配者、Wyrmthalakだ。Wyrmthalakが死ねば、奴らの中枢司令部は指揮系統を失う。", "状況は?", "素晴らしい働きだ、{name}。少なくとも、君は猶予をもたらしてくれたんだ……貴重な、貴重な猶予を。", 0xc1d7f82a, 0x1da97ed4, 0x4be46f5e, 0x443e5ca0, 0x59df8873, "....." },
  [5082] = { "Winterfall族の脅威", "WinterspringのDonova Snowdenは、Winterfall Pathfinder・Winterfall Den Watcher・Winterfall Totemicをそれぞれ8頭ずつ殺すよう求めています。", "私はFrostfire Hot Springsを調査するためにWinterspringへ来ました。水には……奇妙な性質があるようなのです。まだその源を突き止められておらず、正直に言うと、最近はWinterfallのfurbolgのせいで苦労しています。\n\n彼らも私と同じように泉に引き寄せられているようです。水をひどく守るようになって、ここから北にある大きな2つの泉に私を近づけさせてくれません。\n\n研究を続けたいのです。手伝ってもらえませんか？", "助けてくれて感謝するよ!", "本当にありがとう、{name}! これでここでの仕事に戻れます。\n\nWinterfallの野営地で何か興味深いものは見つかりましたか?", 0x4fbdaff6, 0x80980e27, 0x39dd244f, 0xc3066c72, 0xe6b3e78a, "....." },
  [5083] = { "Winterfall Firewater", "WinterspringのDonova SnowdenにEmpty Firewater Flaskを渡して下さい。", "Winterfallのfurbolgから拾ったこの小瓶は空だが、中に奇妙な緑色の液体が数滴残っているのが分かる。ほのかに光っているようだ。\n\n何か重要なものだろうか？\n\nDonova Snowdenならもっと詳しく教えてくれるだろう。彼女はしばらく前からWinterspringの温泉のそばで野営している。", "何を見つけたのですか?", "あなたこれをWinterfall族から手に入れたの?", 0x15a9986b, 0x0434cdb1, 0xb596a84a, 0xd0ef59f6, 0xcb26aece, "....." },
  [5084] = { "腐敗への堕落", "手がかりを見つけるため、Felwood北部のDeadwood族furbolgのキャンプを探索して下さい。", "この緑がかった液体……Felwoodを旅した時に見たヘドロを少し思い出させます。それに、Winterfall RunnersがTimbermawへ入っていくのを何度か見かけました……もしかすると、あなたが見つけた瓶と関係があるのかもしれません、{name}。\n\nFelwoodのTimbermaw Holdのすぐ先に、furbolgの大きな集団がいます。Deadwood族と呼ばれ、邪悪な魔力によって堕落し、狂わされてしまいました。そのあたりを調べて、WinterfallとDeadwoodの間に取引があった証拠が見つからないか確かめてもらえませんか？", nil, "鍋の中は、ひどい腐臭を放つ物体で泡立っている……。", 0x3b25fa7e, 0xabd4571f, 0x98d89400, nil, 0xe72eed6e, "...m." },
  [5085] = { "謎のどろどろ", "発見した物をDonova Snowdenに報告して下さい。", "大釜の中の緑がかった物質は、瓶の中で見つけたものと似ているようだ。この奇妙などろどろしたものは、それを作ったfurbolgと同じくらい堕落しているのかもしれない……\n\nWinterfallのfurbolgがこれを使っているなら、彼らもじきにDeadwood族と同じくらい堕落してしまうということだろうか？\n\n発見したことを、大釜の液体のサンプルと一緒にDonovaに報告するのが一番だろう。", "何か見つかっているといいのですが、{name}。Winterfallはますます凶暴になっています!", "あなた本当に優秀ね、{name}。Winterfall族furbolgはDeadwood族のキャンプへ行ったことがあると思う?", 0x231688a0, 0x30444789, 0xd6bbb6f1, 0x0f8de502, 0xbc19bf3d, "....." },
  [5086] = { "毒の恐怖", "WinterspringのDonova SnowdenのためにToxic Horror Droplet 3つを集めて下さい。", "持ち帰ってくれたサンプルを調べました。確かなことは言えませんが、有毒な成分の痕跡が含まれていると思います。ただ、確かめる唯一の方法は、比較のためにその成分をいくらか集めることです。\n\nDeadwoodのfurbolgは、Felwoodにいる他の堕落した生き物からこの成分を集めているのではないかと思います。特に、Irontree Woodsに棲むtoxic horrorsと呼ばれるエレメンタルからです。\n\n比較用のサンプルをいくつか集めてきてください。でも気をつけて――あそこはとても危険です！", "ここで何が起きているのか、明らかになり始めたように思います、{name}。", "あなたが鍋から見つけた物体と比較しなきゃね。そうすればもっと詳しく分かるはず。", 0x26ee22fb, 0x501b4707, 0x001b66ba, 0x09b0df92, 0x0cbe58e7, "....." },
  [5087] = { "Winterfall Runner", "Winterfall Runnerを見つけ、Winterfall Villageへの荷物配達を阻止して下さい。", "とても興味深いですね、{name}……\n\nこの有毒物質を温泉の水と混ぜると毒性が失われ、摂取した者に一時的に作用する力だけが残るのです。だからWinterfallはあれほど熱心に温泉を守っているのでしょう――火酒を浄化するのに温泉が必要なのです。\n\nこれを止めなければなりません――WinterfallとDeadwoodの接触を断つのです。運び屋の一団が、彼らの村とFelwoodの間を行き来しています。彼らを見つけて倒し、積荷を奪ってください。", "火酒が手に入らなくなったらWinterfallがどうなるか、見ものだな!", "<Donovaが木箱の中身を調べる。>\n\nこの物質を摂取することで、furbolgはより攻撃的になるのでしょうか。確かにずっと大きくなっているようですし……", 0x2f0113a6, 0x230d59b0, 0xfd258e1b, 0x1014a9a4, 0x0a41afec, "....." },
  [5088] = { "Arikara", "Arikaraを討ち取って下さい。その証拠として、Arikaraの骸とIncendia powderをWhitereach PostのMotega Firemaneに渡して下さい。", "清められて純化したIncendia powderをThousand Needlesへ持っていき、神聖な命の炎へまいて下さい。炎はDarkcloud Pinnacleにひとつだけ離れて立つ、死者を埋葬した針山にあります。\n\n{name}、このIncendia powderに織り込んだ魔法で、あなたの元へArikaraを召喚することができるでしょう。\n\n私は、あの蛇がCairne Bloodhoofを付け狙っているのではないかと危ぶんでいます。多くのTaurenの伝承が変わってしまいました。そのことがArikaraを怒らせたのではないかと思うのです。{class}、すべてが失われる前に、迅速に行動して下さい!", "凶暴な大蛇Arikaraを倒したか、{name}?", "さっぱり分からんなあ。なんでArikaraがCairne Bloodhoofをつけ回さなきゃならない? Magathaが間違ってるはずはない、彼女は我々の最も強力な呪術師なんだから。\n\n<Motegaは首を振った。>\n\nとにかく、君のHordeへの偉大な行いは注目されぬはずがない。さあ、お礼にこの中からひとつ選んでおくれ。", 0x23d8ed72, 0x3cd465fe, 0x86f0cae7, 0x593eac54, 0x685290fb, "....." },
  [5089] = { "General Drakkisath's Command", "Burning SteppesのMarshal MaxwellにGeneral Drakkisath's Commandを渡して下さい。", "倒した大蛇の死体から、重要そうな書き付けが見つかった。上官であるGeneral Drakkisathからの、規定に関する手紙だ。\n\nこれはMarshal Maxwellのところへ持っていくべきだと直感が告げている。", "何を持ってきたんだ、{name}?", "話がややこしくなってきたな……。", 0xf8941430, 0x20e21738, 0x0981eb66, 0x421c38bd, 0x84ca30b3, "....." },
  [5090] = { "召集令：Plaguelands！", "Commander Ashlam Valorfistを探し出して下さい。彼の拠点はAlterac Mountainsの北にあるChillwind Campだ。", "聞け、聞け！すべての英雄よ、この言葉に耳を傾けよ！\n\nKingdom of Stormwindより召集令が発せられた！戦える者は皆、Eastern Kingdomsの北方の地でScourgeの暗き脅威に対して武器を取るよう求められている！Plaguelandsの廃墟から新たな脅威が生まれているとの噂が飛び交っているのだ！\n\n王国の英雄たちよ――Alterac Mountainsの北、Chillwind Campに本陣を構えたCommander Ashlam Valorfistのもとを訪ねよ！", nil, "Plaguelandsへようこそ、英雄よ。ここはAzerothで最も危険な辺境の1つだ。特に、北と北東にはScourgeの脅威が迫っている。義務と大義への奉仕を告げる呼び声が、君の耳に届かなかったわけではないと聞いて嬉しいぞ！\n\n手を汚す覚悟があるなら、このPlaguelandsの境には、意欲と力のある英雄がやるべきことがいくらでもある。", 0x7b917538, 0x754a0fb2, 0xc77e27ed, nil, 0xe8509ad0, "...m." },
  [5091] = { "召集令：Plaguelands！", "Commander Ashlam Valorfistを探し出して下さい。彼の拠点はAlterac Mountainsの北にあるChillwind Campだ。", "聞け、聞け！すべての英雄よ、この言葉に耳を傾けよ！\n\nKingdom of Stormwindより召集令が発せられた！戦える者は皆、Eastern Kingdomsの北方の地でScourgeの暗き脅威に対して武器を取るよう求められている！Plaguelandsの廃墟から新たな脅威が生まれているとの噂が飛び交っているのだ！\n\n王国の英雄たちよ――Alterac Mountainsの北、Chillwind Campに本陣を構えたCommander Ashlam Valorfistのもとを訪ねよ！", nil, "Plaguelandsへようこそ、英雄よ。ここはAzerothで最も危険な辺境の1つだ。特に、北と北東にはScourgeの脅威が迫っている。義務と大義への奉仕を告げる呼び声が、君の耳に届かなかったわけではないと聞いて嬉しいぞ！\n\n手を汚す覚悟があるなら、このPlaguelandsの境には、意欲と力のある英雄がやるべきことがいくらでもある。", 0x7b917538, 0x754a0fb2, 0xc77e27ed, nil, 0xe8509ad0, "...m." },
  [5092] = { "道を切り開け", "Sorrow HillでSkeletal Flayersを$N1体、Slavering Ghoulsを$N2体倒す。\n\nWestern PlaguelandsのChillwind CampにいるCommander Ashlam Valorfistのところへ戻って下さい。", "Andorhalへ通じる西と北の道は堅く守られているため、守りの手薄な東の道から攻めようと考えている。Scourgeは第一の防衛線として、Sorrow Hillにはびこるアンデッドの緩衝地帯に頼っている。Andorhalへ進軍するなら、Sorrow Hillを抜けて行かねばならん。\n\n君の最初の任務は、Sorrow Hillを抜ける道を切り開くことだ。その一帯に出没する骸骨とghoulの数を減らせ。それが済んだら私に報告しに戻ってこい！", "最悪の事態に備えてくれ、{name}。力を振り絞るんだ。我々の前にある任務は容易ではない。いずれScourgeに打って出るためにここで戦力を結集する中で、君は奴らに戦いを仕掛ける先遣部隊の一員となる! Sorrow Hillでの君の任務が、我々の勝利への道の始まりとなるのだ!", "任務完了だ、{name}！ 見事、実に見事だ。\n\nこれまでの働きに対し、Stormwindの金庫から褒賞金を与えよう。次の任務に役立つ物資に使うことを勧める……次はAndorhalの廃墟そのものに向かってもらうことになる。\n\n備えておけ！ 油断するな！", 0xd2c451f5, 0x33b600b3, 0xbbefaa38, 0x89451a7b, 0x40d0f72b, "....." },
  [5093] = { "出撃命令: The Plaguelands!", "High Executor Derringtonを探してください。彼のベースキャンプはUndercityとTirisfal Gladeの東にあるBulwarkに位置しています。", "国の英雄よ、聞いてくれ。Hordeは迅速な行動を求めている!\n\n武器を取りScourgeと戦う屈強な者全員に対して、出撃命令が下された!　Eastern Kingdomsの廃墟から新たな脅威が立ち上がったという噂が広まっている。奴らは今Plaguelandsとして知られている地の北方から、Undercityの東に迫っている!\n\n英雄よ、High Executor Derringtonを探せ。彼はTirisfal Gladeの東、Bulwarkにベースキャンプを設立した!", nil, "Plaguelandsへようこそ、英雄。まだだいぶ東の方ではあるがScourgeの脅威が迫っていて、Azerothの中でも最も危険な国境のうちのひとつだ。Hordeの兵役招集の呼びかけに耳を傾けてくれたこと、嬉しく思っているぞ!\n\n手を汚す覚悟ができているのなら、やる気のある有能な英雄がやることは、このPlaguelandsの辺境にごまんとある。", 0x7b917538, 0x1bad0a2f, 0x9504b319, nil, 0x00c7d144, "...m." },
  [5094] = { "出撃命令：Plaguelandsへ！", "High Executor Derringtonを捜し出してください。彼のベースキャンプはUndercityより東、Tirisfal Glade東部のBulwarkにあるでしょう。", "我らの英雄よ、聞くのだ。Hordeはすばやい行動をあなたに求めている！\n\nScourgeと戦うためにすべての強靭なるものたちに召集命令が発せられた！Eastern Kingdomsの廃墟から新たなる脅威が湧き起こっているとの噂が飛び交っている。奴らはUndercityの東、今はPlaguelandsとして知られている北の大地から迫ってきている！\n\n我らの英雄よ。Tirisfal Glade東部のBulwarkにベースキャンプをおくHigh Executor Derringtonを捜し出すのだ！", nil, "Plaguelandsへようこそ、英雄よ。ここはAzerothで最も危険な辺境の一つだ。東にはScourgeの脅威が迫っている。しかもそれは、そこからさらに東へと続いているのだ。Hordeへの義務と奉仕の呼びかけを、お前が聞き流さなかったと聞いて、うれしく思うぞ！\n\n手を汚す覚悟ができているなら、このPlaguelandsの境目には、意欲と力のある英雄がやるべきことがいくらでもある。", 0x7b917538, 0x1bad0a2f, 0x9504b319, nil, 0x00c7d144, "...m." },
  [5095] = { "出撃命令: The Plaguelands!", "High Executor Derringtonを探してください。彼のベースキャンプはUndercityとTirisfal Gladesの東にあるBulwarkに位置しています。", "国の英雄よ、聞くがいい。Hordeは迅速な行動を求めている!\n\n武器を取りScourgeと戦う屈強な者全員に対して、出撃命令が下された!　Eastern Kingdomsの廃墟から新たな脅威が立ち上がったという噂が広まっている。奴らは今Plaguelandsとして知られている地の北方から、Undercityの東に迫っている!\n\n英雄よ、High Executor Derringtonを探せ。彼はTirisfal Gladesの東、Bulwarkにベースキャンプを設立した!", nil, "Plaguelandsへようこそ、英雄。まだだいぶ東の方ではあるがScourgeの脅威が迫っていて、Azerothの中でも最も危険な国境のうちのひとつだ。Hordeの兵役招集の呼びかけに耳を傾けてくれたこと、嬉しく思っているぞ!\n\n手を汚す覚悟ができているのなら、やる気のある有能な英雄がやることは、このPlaguelandsの辺境にごまんとある。", 0x7b917538, 0x3496d17e, 0x4167d15e, nil, 0x00c7d144, "...m." },
  [5096] = { "Scarletの陽動", "Felstone FieldとDalson's Tearsの間にあるScarlet Crusade's base campへ進み、指揮所を破壊して下さい。\n\nそこにScourge bannerを立て、Western PlaguelandsのBulwarkにいるHigh Executor Derringtonのところへ戻って下さい。", "Andorhalの前に、Hearthglenから進軍しているScarlet Crusadeの脅威に立ち向かわなければならない。奴らはFelstone FieldとDalson's Tearsの間にキャンプを設営しており、我々は一度にScourgeとCrusadeの両方に対して危険を冒さざるを得なくなっている。\n\n私の計画は、お前を寄越して指揮所を破壊し、奴らを互いに争わせようというものだ。発火火薬の箱からFlame in a Bottleを持って行け。いったん破壊したら、テントにこのScourge bannerを立てるのだ。うまくいけば奴らは我々を無視し、復讐のためScourgeに戦力を向けるだろう。", "Scarlet Crusadeの手薄な前線拠点に奇襲をかければ、Andorhalへ進軍するための時間の猶予ができる。成功の報告に来たのだろうな!\n\nこれがうまくいったら、我々は着実かつ迅速に動かねばならない。奴らが我々のささやかな策略に乗らなければ、ScourgeとScarlet Crusadeの両方と同時に戦うだけの物資も人員もないのだ。", "見事な遂行だったぞ、{name}。Scarlet Crusadeへの攻撃のおかげで、時間が稼げるだろう。キャンプを監視し、足場を固め始めたCrusadeの軍が餌に食いつくのを確実にするため、既に偵察を出している。\n\n我々への圧力が少なくなれば、最終的にはAndorhalそのものへ侵入する作戦を実行することもできるはず。それも重要な作戦をな。これまでの成功に基づいて、お前がまた同じように任務を遂行してくれるのならば、是非とも頼みたい。", 0xbdf948db, 0x3fc3d507, 0xbe79ad52, 0x3b96be5f, 0xe0fffe3e, "....." },
  [5097] = { "見張り塔に沿って", "Beacon Torchを使って、Andorhalの塔それぞれに印をつける。印をつけるには塔の戸口に立つ必要がある。\n\n四つの塔すべてに印をつけたら、Western PlaguelandsのChillwind CampにいるCommander Ashlam ValorfistのところへBeacon Torchを返して下さい。", "beacon torchとして知られる魔法の装置を使えば、我々の選んだ標的に印をつけ、今後の部隊の行動に役立てることができる。そのために言っておくと、我々はScourgeがAndorhalの見張り塔を部隊の移動を統制する手段として使っていると考えている。\n\n君の任務：Andorhalの防衛を突破し、四つの見張り塔すべてにビーコンを設置すること。ビーコンを設置するには各塔の入口に立つ必要がある。そうすればビーコンが塔に印をつけてくれる。beacon torchの使用回数は五回分しかない。慎重に使ってくれ！", "塔に印をつければ、それらはAndorhal攻撃の最優先目標となる。塔を無力化すれば、Andorhalの本当の脅威が姿を現すだろう。そこからは、都市の支配をかけた真っ向勝負だ!\n\n成功の報告に戻ってきたのだな? beacon torchも忘れるなよ。物資の管理は怠れないからな。", "我がプリーストたちの報告によれば、ビーコン追跡装置が4つの塔すべてから極めて強い信号を捉えているそうだ！ あえて言おう、君はまたしても完全無欠の成功で任務を果たしてくれた！ またもや見事だ、{name}！\n\n塔に印がつけられ、攻撃の準備は整った。Scourgeに戦いを挑む時が来たのだ！", 0x7d392ded, 0x803d6c0b, 0x6158171c, 0x1bebd1b4, 0xfee8a424, "....." },
  [5098] = { "見張り塔に沿って", "Beacon Torchを使って、Andorhalの塔それぞれに印をつける。印をつけるには塔の戸口に立つ必要がある。\n\n四つの塔すべてに印をつけたら、Western PlaguelandsのBulwarkにいるHigh Executor DerringtonのところへBeacon Torchを返して下さい。", "beacon torchとして知られる魔法の装置を使えば、我々の選んだ標的に印をつけ、今後の部隊の行動に役立てることができる。そのために言っておくと、我々はScourgeがAndorhalの見張り塔を部隊の移動を統制する手段として使っていると考えている。\n\n君の任務：Andorhalの防衛を突破し、四つの見張り塔すべてにビーコンを設置すること。ビーコンを設置するには各塔の入口に立つ必要がある。そうすればビーコンが塔に印をつけてくれる。beacon torchの使用回数は五回分しかない。慎重に使ってくれ！", "塔に印をつければ、それらはAndorhal攻撃の最優先目標となる。塔を無力化すれば、Andorhalの本当の脅威が姿を現すだろう。そこからは、都市の支配をかけた真っ向勝負だ!\n\n成功の報告に戻ってきたのだな? beacon torchも忘れるなよ。物資の管理は怠れないからな。", "我がウォーロックたちの報告によれば、ビーコン追跡装置が4つの塔すべてから極めて強い信号を捉えているそうだ！ 君は熟練の古参兵のような技量と正確さで我が命令を果たした。Hordeへの君の奉仕は、改めてしかと記録しておくぞ、{name}！\n\n塔に印がつけられ、攻撃の準備は整った。Scourgeに戦いを挑む時が来たのだ！", 0x7d392ded, 0xd0c3eb85, 0x6158171c, 0x1bebd1b4, 0x40e0bbc0, "....." },
  [5101] = { "Leeの究極テストクエスト……破滅の！", "Bennyのために羊を6匹倒し、それから全力で逃げる！\n\n冗談だよ……逃げるところはね。", "ふん！ これを何だと思ってやがる、Test Questか何かか？ 誤字まであるに違いねえ！\n\n俺のクエストが楽勝だと思ってんなら、大間違いだぜ！\n\n羊を10匹（1933）倒してこい。倒すまで戻ってくるんじゃねえぞ！", nil, nil, 0xbc8fc11e, 0x2265a0a6, 0x9d3537f4, nil, nil, "...mm" },
  [5102] = { "General Drakkisathの死", "Blackrock Spireへ行き、General Drakkisathを倒してください。仕事が終わったらMarshal Maxwellのところへ戻ってください。", "我々は2つの戦線でこの獣どもと戦っている。首都Stormwindでは内側から奴らと戦い、ここBurning Steppesでは奴らの玄関先に戦いを仕掛けている。警戒を怠るな、{name}。奴らが我々の家や家族を襲った時、我らの仲間は誰一人として容赦されなかった。ならば奴らの誰一人として、我々の怒りから逃してはならん。\n\nこのGeneral Drakkisathを見つけ出し、倒すのだ！\n\n決して簡単な任務ではないだろうが、報酬は破格のものとなる。", "終わったか?", "確実に、次は竜の支配者どもを攻撃することになるだろうな。よくやったぞ、Allianceの勇敢な戦士よ! よくやった、本当に。", 0xda93b846, 0x12dc4302, 0x505fe600, 0xcd001c89, 0x72a4103b, "....." },
  [5103] = { "灼熱の死", "この小手をどうすればよいかは、この世界の誰かが知っているでしょう。健闘を祈ります!", "この人間の遺したものは、焼け焦げた骨だけだ。彼は求めていたもの――unfired plate gauntlets――に手が届くところで死んだようだ。\n\ngauntletsを手に取って、火の中から出たほうがいいのでは？", nil, "これは……", 0x8ca51a7a, 0xafc08c96, 0x7b24a4a8, nil, 0xeef4b8c1, "...m." },
  [5121] = { "High Chief Winterfall", "WinterspringのDonova SnowdenはHigh Chief Winterfallを倒すよう求めています。", "furbolgがなぜこの奇妙な物質を摂取しているのかはまだほとんど分かっていませんが、手に負えなくなる前に止めるのが最善だと思います。\n\nWinterfallのfurbolgは普段は攻撃的な部族ではありません。この行動の変化から、族長の命令を受けているに違いないと思うのです。すでに受けた被害を元に戻すことはおそらくできないでしょうが、彼らの指導者が討たれれば、これ以上悪くなることはないと思います。\n\n東のWinterfall Villageへ向かってください。", "Winterfall Villageに行けば、もっと何か分かるかもしれません、{name}。", "本当にありがとう、{name}。待ち伏せされるんじゃないかって心配をせず、研究に戻ることができるわ。お礼にこれを受け取ってちょうだい。", 0x59ba9908, 0x9c90284c, 0x285ff1e1, 0x3e30620a, 0x0f79db1a, "....." },
  [5123] = { "最後のピース", "WinterspringのDonova SnowdenにCrudely-written Logを渡して下さい。", "首長から見つけた記録はかなりの分量があるようだが、数ページ目を通してみると、文字が読めないことに気づく。記号はあまりに粗雑で形も崩れており、誰かに読めるのかどうかも分からない。\n\nだが、Donovaなら何と書いてあるか教えてくれるかもしれない……", "さて、これは何だ、{name}?", "これ何て意味なのかしら……さっぱり分からないわ……。", 0x28d3ab49, 0x996aba1d, 0xef97d132, 0x57559a46, 0xe7bd7f23, "....." },
  [5124] = { "Fiery Plate Gauntlets", "Enchanted Thorium Bar 6本・Essence of Fire 2つ・Star Rubies 4つをMalyfous Darkhammerに渡して下さい。なお、Unfired Plate Gauntletsも渡す必要があります。", "Thaurissanの髭にかけて！\n\nどこでそれを見つけたんだ？\n\nそれより、それを手放す気はあるか？ もちろん、そんな気高い心遣いには礼をするぞ。\n\nこうしよう、{name}。そのunfired gauntletsを譲ってくれたら、お前さん自身の一式を作る方法を教えてやる。正確なレシピを絞り込めるように、材料を集めてきてくれるだけでいい。\n\n取引成立か？？\n\n必要なもののリストはこれだ。お前さんがgauntletsを提供してくれるんだから、エンチャントされていないthoriumはわしが自腹で用意しよう。", "時は金なりだ、{name}。そして俺にはどっちもあまりないんだ。", "約束通り、{name}、これがレシピだ! あんたがこなしたきつい仕事全部と熱心さの代わりに、ちょっとしたおまけもつけてやろう。この小手を俺にどうしろっていうんだよ???", 0x4cbb6a5e, 0x87725cc6, 0xccc5a0a0, 0x4f1bc461, 0xda449a9a, "....." },
  [5125] = { "Auriusの報い", nil, nil, nil, "{name}、私はもう駄目だ……でも、魂は救われた。言葉に尽くせぬほど感謝しているよ。どうか、これを受け取ってくれ……戦い続けるんだ、勇敢な{class}よ!", 0xca17361a, nil, nil, nil, 0x26926d49, ".mmm." },
  [5126] = { "Loraxの話", "Loraxと話して下さい。彼の言い分を聞いて下さい。", "Satyrはあたりを行ったり来たりし、独り言を言っている。問いかけますか?", "……", "<Loraxは笑った。>", 0x290b6d8d, 0xbdcfbb0e, 0x7dffec5d, 0x000c2356, 0xa9fb4adc, "....." },
  [5127] = { "悪魔の鍛冶屋", "Blackrock Spireへ行き、Goraluk Anvilcrackを見つける。彼を倒し、その死体にBlood Stained Pikeを使う。魂が吸い取られると、槍はSoul Stainedとなる。\n\nUnforged Rune Covered Breastplateも見つけなければならない。\n\nSoul Stained PikeとUnforged Rune Covered Breastplateの両方をWinterspringのLoraxのところへ持ち帰って下さい。", "Loraxは取引を持ちかける側だ。取るに足らぬ定命の者から持ちかけられた取引など受けはせぬ。\n\nだが、お前とは取引をしてやろう……この槍を持っていけ。強力なFelのエネルギーが込められている。Goraluk Anvilcrackを見つけたら、奴を殺し、息絶えようとする心臓にこの槍を突き立てよ。奴は魂を売り渡した。その魂は我がいただく。槍を持ち帰り、あの盗人が盗んだ胸当ても持ち帰れば、奴が学ぶはずだったことを教えてやろう。", "誘惑するな……", "契約をお前は破らなかった。魂は手に入った。報酬をやろう。", 0x04505c04, 0xeee70ecd, 0x08cf14df, 0xabcd5b4a, 0x34e0a0e5, "....." },
  [5128] = { "Words of the High Chief", "Felwood南部のKelek SkykeeperにCrudely-written Logを渡して下さい。", "Winterfallはもう私にとって脅威ではありません。でも、何がfurbolgにこの奇妙な火酒を作らせ、飲ませていたのかまだ知りたいなら、Kelek Skykeeperを訪ねるといいと思います。\n\n彼はEmerald Circleと呼ばれる集団の一員です。Felwoodでの務めに身を捧げ、堕落からこの地を癒しているドルイドたちです。\n\nKelekはFelwoodのfurbolgsについて豊富な経験があるので、記録についてもっと詳しく教えてくれるかもしれません。\n\n改めてありがとう、{name}。", "Emerald Circleは誰にでも友好的です、{race}。何かご用ですか?", "ええ、しばらくこれを調べさせてもらえれば、あなたのために翻訳できるかもしれません。\n\n<Kelekがページをめくる。>\n\nすべて目を通せたら、あなたに知らせを送ります。\n\nこれを見せてくれてありがとう、{name}。Winterfall furbolgについて分かっていることはごくわずかなのです。", 0x87959bae, 0x4374f442, 0xd7d7c1e5, 0x9a2ba698, 0x3af9ca76, "....." },
  [5141] = { "Dragonscale Leatherworking", "Tough Scorpid Breastplatesを$N1個、Tough Scorpid Glovesを$N2個、Worn Dragonscalesを$N3個、AzsharaのPeter Galenのところへ持って行って下さい。\n\nこのクエストを完了すると、Dragonscale Leatherworkingの技を学べるようになります。\n\nこのクエストを完了すると、Elemental LeatherworkingとTribal Leatherworkingは学べなくなります。進む前に、これが本当に自分の選びたい道なのか確かめて下さい。", "Dragonscaleの革細工は簡単じゃないが、その分、見返りは大きい。この上等なメイル防具の作り方を教えてやろう。ただし、いくつかの条件に同意するならだ。\n\nこの道を選ぶなら、elementalやtribalの革細工は決して学ばないと同意してもらう。技の頂点には3つのうち1つの居場所しかないんだ。さらに、scorpid防具を使ったお前の最高の作品の見本がいくつか必要だ。最後に、この商売の必需品、dragonkinの鱗を手に入れられる腕の証が要る。", "dragonscale leatherworkerになるという取り返しのつかない決断をする覚悟ができているなら、弟子として迎え入れる準備はできている。頼んだものを持ってきてくれれば、修業を始めよう。", "大したものだ――今そなたが下したような、取り消せぬ決断をするには強い意志が要る。dragonscale leatherworkingは、そなたが進む道として実り多く、報われるものとなると保証しよう。\n\n今後この技を修めるには、私に話しかけてくれるだけでいい。そなたがまだ我がものとしていない知識を、いつでも授けよう。", 0x2bc93035, 0xd255b890, 0x7a9a3232, 0x250fb4b6, 0x4027ea2b, "....." },
  [5142] = { "小さなPamela", "Pamela Redpathを見つける。", "Darrowshireの戦いで、私たちの多くが死にました。本当に多くが死んだのです……そして、もっとひどいことになった者も。\n\n戦いが始まった時、私は姪のPamelaを隠したのですが、あの子がどうなったのかは分かりません。私はさまよう霊にすぎませんが、心は今もPamelaの運命を知りたいと願っているのです。\n\nお願いです、善き{class}よ。Darrowshireへ行って、あの子を探してくれませんか？ここから東、Gahrron's Witheringの向こうにあります。", nil, "こんにちは。私はPamela、あなたのお名前は？", 0xbf5c69cb, 0x652ecebd, 0x91cf2076, nil, 0x278965d4, "...m." },
  [5143] = { "Tribal Leatherworking", "Wild Leather VestとWild Leather HelmetをFeralasのCaryssia Moonhunterのところへ持って行って下さい。\n\nこのクエストを完了すると、Tribal Leatherworkingの技を学べるようになります。\n\nこのクエストを完了すると、Dragonscale LeatherworkingとElemental Leatherworkingは学べなくなります。進む前に、これが本当に自分の選びたい道なのか確かめて下さい。", "tribalの革細工を学ぶには、自然がいかに原初的なものかを理解することが求められる。お前がすでにwild leather armorの作り方を極めたことは知っている。お前の訓練を仕上げてやろう。\n\n心しておけ、{class}。この道を選ぶなら、dragonscaleやelementalの革細工は決して学ばないと同意してもらう。3つの技のうち1つしか修めることはできないのだ。さらに、お前のwild leather armorの最も優れた見本を持ってこい。そこから、お前の熟達が始まる。", "自然とは、その意志を革の衣服に織り込む術を学ぼうと望む前に、まず鎮めねばならない力だ。この力への捧げ物を持ってくれば、お前の声が届くようにしてやろう。", "そなたは最上の捧げ物を差し出した。じきに自然は、その意のままに自らを曲げることを許すだろう。私の教えが終われば、そなたの作る品はそれ自体が自然の力となる。\n\n今後この技を修めるには、私に話しかけてくれるだけでいい。そなたがまだ我がものとしていない知識を、いつでも授けよう。", 0x6f10746f, 0xed791b97, 0xeb474bee, 0xb22401c2, 0x4cce757a, "....." },
  [5144] = { "Elemental Leatherworking", "Heart of Fireを$N1個、Globe of Waterを$N2個、Core of Earthを$N3個、Breath of Windを$N4個、Searing GorgeのSarah Tannerのところへ持って行って下さい。\n\nこのクエストを完了すると、Elemental Leatherworkingの技を学べるようになります。\n\nこのクエストを完了すると、Dragonscale LeatherworkingとTribal Leatherworkingは学べなくなります。進む前に、これが本当に自分の選びたい道なのか確かめて下さい。", "Elementalの革細工こそが私の知るものだ。物質のより大いなる力に心を開くつもりがあるなら、学ぶべきことすべてを教えよう。\n\n心しておけ、{class}。この道を選ぶなら、dragonscaleやtribalの革細工は決して学ばないと同意してもらう。3つの技のうち1つしか修めることはできない。さらに、お前が自然の元素と調和している確かな証が必要だ。そのために、火、水、土、風の最も純粋なエッセンスを持ってきてくれ。", "この種の革の防具を作るには、忍耐と献身が必要だ。ひとたびエレメントと運命を共にすると決めたら、背を向けることはできない。ふさわしい者である証を持ってくれば、始めるとしよう。", "そなたは賽を投げ、元素はそなたを受け入れた。私の教えが終われば、そなたは最上の革の衣を作る意志を振るえるようになる。\n\n今後この技を修めるには、私に話しかけてくれるだけでいい。そなたがまだ我がものとしていない知識を、いつでも授けよう。", 0x9503323d, 0x370e9a1c, 0xd87a1461, 0xae7f88b1, 0xe07be135, "....." },
  [5145] = { "Dragonscale Leatherworking", "Tough Scorpid Breastplatesを$N1個、Tough Scorpid Glovesを$N2個、Worn Dragonscalesを$N3個、BadlandsのThorkaf Dragoneyeのところへ持って行って下さい。\n\nこのクエストを完了すると、Dragonscale Leatherworkingの技を学べるようになります。\n\nこのクエストを完了すると、Elemental LeatherworkingとTribal Leatherworkingは学べなくなります。進む前に、これが本当に自分の選びたい道なのか確かめて下さい。", "Dragonscaleの革細工は簡単じゃないが、その分、見返りは大きい。この上等なメイル防具の作り方を教えてやろう。ただし、いくつかの条件に同意するならだ。\n\nこの道を選ぶなら、elementalやtribalの革細工は決して学ばないと同意してもらう。技の頂点には3つのうち1つの居場所しかないんだ。さらに、scorpid防具を使ったお前の最高の作品の見本がいくつか必要だ。最後に、この商売の必需品、dragonkinの鱗を手に入れられる腕の証が要る。", "dragonscale leatherworkerになるという取り返しのつかない決断をする覚悟ができているなら、弟子として迎え入れる準備はできている。頼んだものを持ってきてくれれば、修業を始めよう。", "大したものだ――今そなたが下したような、取り消せぬ決断をするには強い意志が要る。dragonscale leatherworkingは、そなたが進む道として実り多く、報われるものとなると保証しよう。\n\n今後この技を修めるには、私に話しかけてくれるだけでいい。そなたがまだ我がものとしていない知識を、いつでも授けよう。", 0x2bc93035, 0xba8b2e9b, 0x7a9a3232, 0x250fb4b6, 0x4027ea2b, "....." },
  [5146] = { "Elemental Leatherworking", "Heart of Fireを$N1個、Globe of Waterを$N2個、Core of Earthを$N3個、Breath of Windを$N4個、Arathi MountainsのBrumn Winterhoofのところへ持って行って下さい。\n\nこのクエストを完了すると、Elemental Leatherworkingの技を学べるようになります。\n\nこのクエストを完了すると、Dragonscale LeatherworkingとTribal Leatherworkingは学べなくなります。進む前に、これが本当に自分の選びたい道なのか確かめて下さい。", "Elementalの革細工こそが私の知るものだ。物質のより大いなる力に心を開くつもりがあるなら、学ぶべきことすべてを教えよう。\n\n心しておけ、{class}。この道を選ぶなら、dragonscaleやtribalの革細工は決して学ばないと同意してもらう。3つの技のうち1つしか修めることはできない。さらに、お前が自然の元素と調和している確かな証が必要だ。そのために、火、水、土、風の最も純粋なエッセンスを持ってきてくれ。", "この種の革の防具を作るには、忍耐と献身が必要だ。ひとたびエレメントと運命を共にすると決めたら、背を向けることはできない。ふさわしい者である証を持ってくれば、始めるとしよう。", "そなたは賽を投げ、元素はそなたを受け入れた。私の教えが終われば、そなたは最上の革の衣を作る意志を振るえるようになる。\n\n今後この技を修めるには、私に話しかけてくれるだけでいい。そなたがまだ我がものとしていない知識を、いつでも授けよう。", 0x9503323d, 0x14c75abb, 0xd87a1461, 0xae7f88b1, 0xe07be135, "....." },
  [5147] = { "お尋ね者Arnak Grimtotem", "Arnak Grimtotemを討伐し、その証拠をFreewind PostのCliffwatcher Longhornに渡して下さい。", "お尋ね者　Arnak Grimtotem    追放者Arnakを凶悪な殺人罪及び誘拐の罪で指名手配中。この犯罪者に裁きを受けさせた勇敢な者には、相当の報酬を与える。\n\nArnakが最後に目撃されたのは、Darkcloud Pinnacle近くの崖の上。報酬を要求するには、Freewind PostのCliffwatcher Longhornに証拠を見せること。", "あの人殺しのArnak Grimtotemについて、何か知らせはあるか?", "ハ! や、これはいい知らせだ! 奴に裁きを受けさせられないんじゃないかと思い始めていたところだ!\n\n{name}、さあこれを……そして、ありがとう。Arnakの卑劣な行いを聞いて頭にきてたんだ!", 0x4f73fc84, 0x910d7242, 0x50ebc814, 0x12fd03ba, 0xf92279b7, "....." },
  [5148] = { "Tribal Leatherworking", "Wild Leather VestとWild Leather HelmetをStranglethorn ValeのSe'Jibのところへ持って行って下さい。\n\nこのクエストを完了すると、Tribal Leatherworkingの技を学べるようになります。\n\nこのクエストを完了すると、Dragonscale LeatherworkingとElemental Leatherworkingは学べなくなります。進む前に、これが本当に自分の選びたい道なのか確かめて下さい。", "tribalの革細工を学ぶには、自然がいかに原初的なものかを理解することが求められる。お前がすでにwild leather armorの作り方を極めたことは知っている。お前の訓練を仕上げてやろう。\n\n心しておけ、{class}。この道を選ぶなら、dragonscaleやelementalの革細工は決して学ばないと同意してもらう。3つの技のうち1つしか修めることはできないのだ。さらに、お前のwild leather armorの最も優れた見本を持ってこい。そこから、お前の熟達が始まる。", "自然とは、その意志を革の衣服に織り込む術を学ぼうと望む前に、まず鎮めねばならない力だ。この力への捧げ物を持ってくれば、お前の声が届くようにしてやろう。", "そなたは最上の捧げ物を差し出した。じきに自然は、その意のままに自らを曲げることを許すだろう。私の教えが終われば、そなたの作る品はそれ自体が自然の力となる。\n\n今後この技を修めるには、私に話しかけてくれるだけでいい。そなたがまだ我がものとしていない知識を、いつでも授けよう。", 0x6f10746f, 0x3cd2784c, 0xeb474bee, 0xb22401c2, 0x4cce757a, "....." },
  [5149] = { "Pamela's Doll", "Pamelaの人形を見つける。", "Marleneおばちゃんが、お父さんは戦いに行かなきゃいけないから  おうちにいるように言ったの。お父さんは全世界でいちばん勇敢なのよ!\n\nでも、ずっとここで待ってるのに迎えに来てくれないの。\n\n時々、悪い人たちが来て私にささやくから追い払ってほしいのに、お父さんはここにいないわ！\n\nそれで、時々暗くなってくるとお人形で遊びたくなるのに、町で無くしちゃったから遊ぶことができないの。\n\nお人形を見つけてもらえないかな？", "わたしのお人形、見つけてくれた?", "見つけてくれたのね！お人形見つけてくれたのね！ありがとう！", 0xc2bf6af3, 0x7119b829, 0xde335067, 0x1cbf400c, 0x7bcdc282, "....." },
  [5151] = { "Hypercapacitor Gizmo", "豹を退治し、Hypercapacitor GizmoとPanther Cage KeyをWizlo Bearingshinerに返して下さい。", "centaurに襲われた俺たちの隊商で、生き残ったのは俺だけだ！珍しいが強大な豹が、俺の一番の装置を守ってやがる。そいつの首にかかってるんだ。はっ！centaurでさえ、この獰猛な獣の前じゃ震え上がるのさ！\n\nこれが檻の鍵だ。奴らはそこから何もかも持っていったが、あいつだけは放っておいた。この獣を倒して、俺のhypercapacitorを取り返してくれたら、報酬をやろう。\n\n壊れた隊商はここのすぐ北だ。", "俺のhypercapacitorは持ってきたか?", "オレのhypercapacitor! これが何をするのか理解するまで、しばらく忙しくなるぞ……", 0x0f8bf73d, 0x8b6a9674, 0xdeb68b59, 0xaf2e4c2b, 0xa40857a1, "....." },
  [5152] = { "Auntie Marlene", "Ruins of Andorhalの南にいるMarleneと話して下さい。", "ああ、すごく寂しいよ！私の家族はどこ？Auntie Marleneはここにいなさいって言ったのに、どこかへ行ったきり戻ってこないの！それにパパも……パパを見なかった？\n\nAuntie Marleneならパパの居場所を知ってるかも。おばさんはAndorhalの近くの、南にある家に住んでるの。丘の上だったと思う……丘の上だって言ってたもん。\n\nお願い、{name}。あなたは私の新しい友達でしょ！私の代わりにおばさんと話してくれる？", nil, "Pamelaを見たのか？ あの子はどうしている？ 生きているのか？？ ああ、そんな！ かわいそうなPamela！ まだあんなに幼くて、あんなに幸せな子だったのに……\n\nあの子は父親に何があったのか知らないんだろう？ 私の兄弟、Josephに？\n\nいや……あの子にはJosephに何が起きたかなんて理解できないだろう。たとえ理解できたとしても、私にはあの子に伝える勇気がない……", 0xbf32e4a8, 0x02c7f350, 0x681a5775, nil, 0x73074fb9, "...m." },
  [5153] = { "奇妙な歴史家", "Joseph's Wedding RingをChromieのところへ持って行って下さい。", "Josephがもう一度娘と一緒にいられたらと願うけれど、それは叶わないの。彼の魂はScourgeにねじ曲げられ、彼は怪物になってしまった。ああ、彼は破滅の運命にあるのよ！\n\nでも、彼の運命を変えられるかもしれないわ。\n\n外の墓の中からJosephの墓碑を探してちょうだい。彼の遺体はそこにはないの。何年も前に踏みにじられて壊されてしまったから。でも墓碑の下に彼の結婚指輪があるわ。その指輪をChromieのところへ持って行って……とても不思議な力を持った、不思議なノームよ。\n\nChromieはAndorhalの北西の角にある、廃墟になった宿屋に滞在しているわ。", "あなたの訪問は妙に時宜を得ていますね。まさか未来から来たわけではないですよね?", "これは何ですか？ wedding ring？ 見せてください……\n\nああ！ このringはかつて偉大な男の手にありました。でも、その男の過去には大きな悲劇があるのです。\n\n彼を助けるために来たのですか？ 今の彼にはもう手遅れです……でも、過去の彼なら助けられるかもしれません！", 0xcb8b9956, 0xe21c496d, 0x436bc567, 0x382329e8, 0x490fbfd0, "....." },
  [5154] = { "Annals of Darrowshire", "Annals of DarrowshireをAndorhalにいるChromieのところへ持って行って下さい。", "Joseph Redpathを救うには、まず彼の過去を知らなければならないわ。それはAndorhalの町役場に保管されている本、Annals of Darrowshireで知ることができるの。\n\nその本を持ってきて。そうすればJosephの運命を知ることができるし、運が良ければ……それを変えられるわ！", "本は見つかったかい、{name}?", "よくやりました、見つけたのですね！\n\n読みましたか？ Joseph Redpathのことは書かれていましたか？ もし書かれているなら、彼を救えるかもしれません！\n\nああ。Annals of Darrowshireには、とても不穏な話が記されています。戦いの最中、Joseph Redpathは堕落してScourgeの軍勢に加わったというのです！ そして彼はDarrowshireの守り手たちを裏切りました。\n\nそれは不吉な運命です。できることなら、その運命を変えるべきだと思いませんか？", 0xe83edb2f, 0x08fe7e5b, 0xed3cf36e, 0xfe172e90, 0x64d242ef, "....." },
  [5155] = { "Jaedenarの軍隊", "Jaedenarに入って、Jaedenar Hounds 4匹、Jaedenar Guardsmen 4人、Jaedenar Adepts 6人、および、Jaedenar Cultists 6人を倒し、FelwoodのGreta Mosshoofの元に戻りなさい。", "今回の問題でお前を信頼するためには、まずお前自身が証明しなければならない。\n\nお前が Shadow Council -- そこかしこの多くの災いの原因となるもの -- の敵であることを、私に分からせてくれ。\n\nFelwoodのより奥地へ向かえ。西へ向かう、Jaedenarに通じる道を見つけられる。CouncilがBurning Legionの陰謀を企てているのはそこだ。\n\n奴らが棲む邪悪なBarrow Densの一つ、その奥深くに進入し、連中を倒して来い。終わったら戻って来い。そうすれば、本当に我々を手助けしようとしていることを信じてやろう。", "戦いはどうだ、{name}? 名誉の証として血を流すことを忌まわしく思う者もいるのは知っている。だが、それには2つの目的があることを理解してほしい。奴らの数を減らすことで私の仕事が楽になり、そして互いに敬意を抱くことで、この先ますます強くなれるのだ。\n\n分かってくれるといいのだが。", "よくやった、{name}!奴らが数の上で弱まって、我々はさらに圧力をかけ易くなった。\n\n奴らの戦力の第一印象はどんなものだ？奴らは思っていた程度の実力だったか？それとももっと強かったか？あるいは、恐らくそうだろうが、お前には役不足だったかな？\n\nお前の功績については、あとで考えてやる。我々には、いま、やらなければならないことがあるんでな。", 0x8fc92571, 0x42e95290, 0x5050219c, 0x35903617, 0x70ed3eba, "....." },
  [5156] = { "汚染の確認", "Shatter Scar Valeを探索しながら、Entropic Beastsを$N1体とEntropic Horrorsを$N2体探し出して倒す。そこのクレーターがまだ汚れたfelの水で満たされているかを確かめたら、FelwoodのTaronn Redfeatherのところへ戻って下さい。", "北へ、道の東側に沿って進んだShatter Scar Valeと呼ばれる場所に、先の大戦でinfernalが呼び降ろされた一帯があるのです――クレーターは今も大地に傷跡を残しており、infernal自身も同じように残っています。\n\n気になっていることが二つあります。まず一つ目、あの一帯にはまだentropic elementalがうろついているのでしょうか？そして二つ目、クレーターには今も、何年も前にたまった腐敗した悪臭のする水が満ちているのでしょうか？確かめるのを手伝ってもらえませんか、{name}？でも気をつけてください、infernalは行く手にあるものを何でも破壊しますから。", "捜索がうまくいくことを願っているよ、{name}。私はまだそんなに北のほうまで行き始めてはいないが、正直に言うと、どこかでinfernalに出くわすと考えると少し怖いんだ。あの生き物は知性こそないが、それでもかなり恐ろしいからね。", "生きていてよかったです、{name}。でも、その水がまだ存在しているのは残念です。ここFelwoodで、少なくとも1つは清らかな水源を見つけたいと思っていたのですが。どうやら私の探索は失敗に終わったようです。その水があれば、大地を癒す過程はずっと楽になったでしょうに。\n\n私は、救える限りの森の生き物を救いつつ、あまりにひどく堕落して、自らだけでなく、かつて雄大だったこの森を旅する者たちをも危険にさらすようになった者たちを倒すことに専念しなければなりません。", 0x707d2810, 0x8bce46c5, 0xa6862cb5, 0x78297b9e, 0xbbd1d03a, "....." },
  [5157] = { "汚れた水の採取", "Empty CanteenをJaedenarの中心にあるMoon Wellへ持って行って水を汲み、FelwoodのGreta Mosshoofのところへ戻って下さい。", "Jaedenarの奥深くにはShadow Holdがあります――彼らの腐敗と悪の中心となる要塞です。\n\nShadow Councilは、火鉢という形で自分たちの隠れ家を守る呪文を張り巡らせています。水晶占いで敵についてこれ以上の情報を得るには、あの火鉢を消さなければなりません。そうすれば評議会を探り、誰が彼らを率いているのかを突き止められるはずです。\n\nもしできるなら、この水筒を持って行って、Jaedenarの中心にあるMoon Wellで水を満たしてください。その後、私のところへ戻ってきてください。", "Moon Wellの水を手に入れたら、それを清めて、Shadow Hold内の守護の火鉢を消すのに使います。そうすれば、さらに奥の部屋を見通して、この……教団を実際に率いているのが誰なのかを見極める時間が十分に得られるはずです。\n\nEarthmotherが私たちと共にあらんことを。", "これで十分です、{name}。\n\nあとは、水を火鉢に注ぐ以外にやるべきことは、それを浄化してもらうことだけです。難しくはないはずです。少し旅をするだけで済むでしょう。\n\nすぐに済ませられるといいのですが。", 0x72751fe0, 0xd3f452ab, 0xf7284a6b, 0x73064c54, 0xb56d1812, "....." },
  [5158] = { "霊の助けを求めて", "Corrupt Moon Well WaterをBarrensのIslen Waterseerのところへ持って行って下さい。", "その腐敗した水をBarrensへ持って行ってください、{name}。Ratchetの南、海岸沿いに隠れるようにして、私の古い友人がいます。Islen Waterseerというシャーマンです。彼女は力のあるシャーマンで、きっと私たちを助けてくれるでしょう。彼女と水の精霊との結びつきは、昔から強いのです。私たちの務めが崇高なものであることが、彼女と水の精霊たちにこの務めを手伝ってもらう十分な説得になるはずです。\n\n彼女は水辺のすぐそばにある小さなキャンプにいるはずです。それから、{name}、海賊は相手にしないでください……ただの厄介者で、あなたにとって脅威ではありませんから。", "あなたはRatchetへの道を探しているただの旅人ではないようですね。さあ、私たちの野営地で座って休んでください。準備ができたら声をかけてください。", "ああ、このMoon Wellの水を清めてほしいのですね。Felwoodのこの悪意の力を止めるのは十分に気高いことに思えますが、水を浄化するかどうかを決めるのは私ではありません。水の精霊たちに尋ねてみます。その大義が正しいかどうかを決めるのは彼らです。\n\n少し待ってください、あなたの願いを彼らに伝えます。彼らも私と同じように、あなたの大義に共感してくれるといいのですが。", 0xe9c94673, 0x8c1ae134, 0x8c67b7e1, 0xeaaeba42, 0x805dd0cc, "....." },
  [5159] = { "浄化された水をFelwoodへ", "Purified Moon Well WaterをFelwoodのGreta Mosshoofのところへ持って行って下さい。", "精霊たちに感謝を、{name}。あなたを助けに来たのは彼らであって、私ではありません。\n\nこの清められた水を今あなたに渡しましょう。どうかGretaによろしく、そして私からの心からの祈りを伝えてください。彼女は私たちの多くが手に負えないほど大きなものに立ち向かっています……きっと彼女もすぐに気づくことでしょうが。\n\nShadow Councilは侮ってよい勢力ではありません、{name}。それを覚えておいてください。\n\nさあ、行きなさい。水を持ってGretaのもとへ戻るのです。", "ああ、戻ったか、{name}。よし。BarrensでIslenは見つかったか? それとも目的を果たすために別の方法を探さねばならないか?", "私たちの目的には、これで十分すぎるほどの水です。\n\nIslenが助けてくれたと聞いて嬉しく思います。水の精霊たちと通じる彼女の力は、昔から強いものでした。彼女は賢くもあり、精霊たちが彼女の意図に同意しないことはめったにありません。その双方が私たちの務めを祝福してくれたという事実は、私たちが正しい道を歩んでいるという希望を与えてくれます。", 0x51c0ce90, 0xf96df8a9, 0x913e20cc, 0xecbf45be, 0xe41510cb, "....." },
  [5160] = { "幼竜の庇護者", "Winterspringへ行ってHalehを見つけ、彼女にAwbee's scaleを渡して下さい。", "Kalimdorへ向かうのだ、{race}よ。我らの一族は、Winterspringの凍てつく地に住処を構えている。Winterspringに着いたら、Mazthorilの洞窟を探せ。\n\nMazthorilの氷の床の上に、コバルト色のルーンがある。我が鱗を一枚持ってルーンの上に立てば、我らの女家長にして守護者、Halehのもとへ運ばれるであろう。\n\n彼女に鱗を渡すのだ。この滅びゆく地で我が見て感じたものを、彼女が占えるように。", "会えて嬉しいよ、{name}。", "定命の者たちの問題に立ち入るなと、偉大なる五竜は強く主張していた。しかしこの世界では、それも常に可能ではない……特に、我々自身の中の一部がそういった命令を侮蔑し軽視している時には。", 0xc391bb7b, 0xa5a91318, 0x9355b076, 0x4cfaa283, 0x8f52e29c, "....." },
  [5161] = { "青き竜の怒り", "話を続けたいのであれば、Halehと話して下さい。", "Deathwingの呪われた子らが何をしようとしているのか、我らは理解しており、それを許すわけにはいかぬことも分かっている。\n\nBlackrockの山がNefarianに与えている庇護のために、我らが介入することはますます困難になっている。\n\nだが、定命の者よ、我らはそなたに力を授けることはできる――そなたが望むならばな。\n\nそなたの前にある道は危険に満ちている。我らの助けを受け入れるかどうか、決めねばならぬ。よく考え、決断がついたら再び我と話すがよい。", nil, "それでは……", 0x26fdd8bc, 0xf97c753c, 0x6f38ba43, nil, 0x85bcef4f, "...m." },
  [5162] = { "青き竜の怒り", "PlaguelandsのJezibaと話して下さい。彼はAndorhalに住んでいます。", "我が操るのは秘術の力であり、そなたを次の目的地へ送るのもまた秘術の力だ。\n\n準備ができたら旅が始まる。Plaguelandsへそなたは赴き、Jezibaとそなたは語らうのだ。\n\n彼は古の者たちのように賢く、動かざる大地のように辛抱強い定命の者だ。Andorhalで彼を見つけよ。", nil, "私はJeziba。彫刻家としてよく知られている。だが、私が彫り上げるものは彫刻ではなく、英雄なのだよ。", 0x26fdd8bc, 0x635a993b, 0x620414b2, nil, 0xc438fdd0, "...m." },
  [5163] = { "イエティ、いるの?", "Umi's Mechanical Yetiを持って行き、Umiの友達を驚かせて下さい。\n\nEverlook（Winterspring）のLegacki\n\nGadgetzan（Tanaris）のSprinkle\n\nMarshal's Refuge（Un'Goro Crater）のQuixxil\n\n終わったら、Mechanical YetiをUmiのところへ持ち帰って下さい。", "準備万端だよ、{name}！\n\nもう友達みんなに、サプライズがあるって手紙を送ってあるんだ。ここであんたの出番さ！\n\n私のmechanical yetiを渡すから、友達一人ひとりを訪ねて、yetiのスイッチを入れて向かわせて、みんなをびっくりさせてほしいんだ。\n\nEverlookのLegacki、GadgetzanのSprinkle、Marshal's RefugeのQuixxilに見せたら、戻ってきて何があったか教えてね！\n\nそれと、その時にはyetiを返してね。", "友達がどんな反応をするか、待ちきれないよ!\n\nみんな、きっと夢にも思わないだろうね!", "ハッ! これでまた私の思いつきを馬鹿にする前に、連中も考え直すでしょうね!\n\n手伝ってくれてありがとう、{name}。あなたがいなければ、こんなに楽しめなかったわ!", 0xf5c82ef5, 0x5e7ceae9, 0xf9385400, 0x20cadf74, 0xe542ccd4, "....." },
  [5164] = { "Catalogue of the Wayward", "Catalogue of the Waywardを読んで下さい。", "これ以上の正義の道具を、Halehは選べなかったであろう。道を外れし者たちの目録を読み、悟りを得るがよい。\n\nそなたがやり遂げるならば……求められたことを果たすならば……生き延びるならば……そなたは英雄となるであろう。", nil, "要領を得ない文章や記号で満ちあふれた膨大なページがこの本の大半を構成している。", 0xed554449, 0x2a99d9b1, 0x5299594c, nil, 0x7082f4ba, "...m." },
  [5165] = { "守護の炎を消す", "Purified Moon Well Waterを使って、FelwoodのShadow Holdの中にある四つの守護の火鉢の炎を消し、Emerald SanctuaryのGreta Mosshoofのところへ戻って下さい。", "さあ、Jaedenarへ戻らなくてはなりません。火鉢はおそらくShadow Holdのあちこちに置かれているでしょう。そのすべての炎を消せば、評議会が張った守りは少なくともしばらくの間は崩れるはずです。私はその時を待っています。その時が来たら、Holdの奥深くを覗き込み、この獣の頭が誰なのかを突き止めてみます。そうして初めて、彼らを直接攻撃することを考えられるのです。", "はるかに大きな戦いに備えられる望みを少しでも持つなら、火鉢を消さなければなりません。何の知識もなく竜の巣に踏み込むのは愚か者のすることです。そしてこれは竜よりもずっと悪いものです。Shadow Councilこそが、数多くの罪と残虐行為の元凶なのです。彼らを止めるなら、急いで動かねばなりません。", "最後の火鉢の炎が消えた途端、呪文であなたの姿が見えるようになりました。よくやりました、{name}。\n\nShadow Councilのウォーロックたちが呪文をかけ直す前に、いくつかのことを知ることができました。これで十分だといいのですが。\n\n今は休んでください。知ったことは、少ししたらお話しします。", 0x060d8cde, 0x01b6e1bb, 0x34b77fa3, 0x0ddbd317, 0xb0dbc7d6, "....." },
  [5166] = { "Breastplate of the Chromatic Flight", "Breastplate of the Chromatic Flightを鍛えるには、次の品をJeziba the 'Sculptor'のところへ持って行く必要があります。\n\nChromatic Carapace $N1個。\n\nBrilliant Chromatic Scales $N2個。\n\nBlood of Heroes $N3個。\n\nFrayed Abomination Stitchings $N4個。", "chromaticの一族の容赦ない攻撃から身を守る強力な胸当ての鍛造は、皮肉の上に成り立つものだ。\n\n我らが戦うまさにその獣たちの鱗を、chromaticの古きドレイクかドラゴンの無垢な甲殻に縫い付けねばならぬ。今のところそのような存在は知られておらず、決して存在しないことを願うべきであろう。\n\n最後に、おそらく最も手に入れがたい素材、英雄たちの血だ。\n\n最終的にこれを鍛え上げるのはSculptorでなければならぬ。", "賢明な選択だ、{race}。", "まだ分からぬのか? 旅そのものが目的地だったのだ。戦いの傷跡を感じられぬか? そなたが耐えた痛みを?\n\n試練を生き延びたことで、そなたはより強大な存在となった。はるかに強大に。このbreastplateは、そなた自身に備わった力の映しに過ぎぬ。", 0xa124a904, 0xa879302f, 0xb7d99786, 0x1fc489bf, 0xa4e224c5, "....." },
  [5167] = { "Legplates of the Chromatic Defier", "Legplates of the Chromatic Defierを鍛えるには、次の品をJeziba the 'Sculptor'のところへ持って行く必要があります。\n\nChromatic Carapace $N1個。\n\nBrilliant Chromatic Scales $N2個。\n\nBlood of Heroes $N3個。\n\nSkin of Shadow $N4個。", "脚鎧の土台を形作るには、mature chromatic drakeの甲羅が必要とされる。Brilliant chromatic scaleは針金の枠に重ねられ、英雄たちの血で魔力をこめられる。最後に、しなやかな影の皮が脛当て内部に貼り付けられねばならない。", "こんな品が作られたことなど、一度もないぞ!", "君が奴らの広間に入れば、奴らは同族の匂いを嗅ぎつけるだろう、{name}。奴ら自身の恐怖で奴らを叩き潰せ！", 0x616f9739, 0xfbfa34e3, 0x5608021e, 0x59f95cf3, 0x8e19a64b, "....." },
  [5168] = { "Darrowshireの英雄たち", "Davil's LibramとRedpath's ShieldをCarlin Redpathのところへ持って行って下さい。", "Darrowshireの英雄たちは私の心の中に特別な場所を占めています。そしてあなたが持ってきてくれた本、Annals of Darrowshireには、彼らの物語が記されています。\n\nそこには、パラディンのDavil Lightfireのこと、そしてCrusadeが彼の聖典をHearthglenの町役場へ持ち去ったことが書かれています。\n\nその文章は、私の兄、Captain Redpathのことも語っています。彼の裏切りの後、彼の盾はひび割れて捨てられ、今では最も思いがけない場所――Gahrron's Witheringの納屋のそば――に転がっているのです。\n\nこれらの遺品を集めてきてください、{name}。運命と悲劇がそれらを取り巻いているのです。", "聖遺物は持ってきましたか、{name}?", "libramとshieldを手に入れたのですね！\n\nそれらの歴史はDarrowshireの歴史と絡み合っています。そしてなぜか、運命がそれらを再び巡り合わせると分かるのです。", 0xb9a8852f, 0x624d91d0, 0x720e7acf, 0x8fc0ba94, 0xa04658d6, "....." },
  [5181] = { "Darrowshireの悪党たち", "Skull of HorgusとShattered Sword of MardukをLight's Hope ChapelのCarlin Redpathのところへ持って行って下さい。", "Annals of Darrowshireには、あの戦いの悪党たちのことが記されています。ghoulの王、Horgus the RavagerがあのいくさでAllianceの軍勢に倒されたことが書かれているのです。彼の体はCorin's Crossingの北西にある湖に投げ込まれ、その頭蓋骨は今もそこにあります。\n\nMarduk the Blackは倒されることはありませんでしたが、名高い彼の剣は砕かれ、失われました。それはCorin's Crossingの西にある峡谷の底に眠っています。\n\nこれらの品を取り戻してきてください、{name}。なぜかは分かりませんが、それらの運命はあなたと共にあると確信しているのです。", "skullとswordは見つけたか、{name}?", "見つけたのですね！ よくやりました、{name}！ これらの遺物には、私にも完全には理解できない力が宿っています。いつの日か、あなたが使いこなすことになる力です。\n\nそれらは私の心に暗い記憶も呼び起こします。死と裏切りの記憶、そしてDarrowshireの最後の夜の記憶を……", 0xee997fcd, 0xe2e47744, 0x3c5af42a, 0x85a8ad4c, 0xd32ff9c9, "....." },
  [5202] = { "奇妙な赤い鍵", "Jaedenarを探索し、Blood Red Keyが何に使われるのかを突き止める。", "その小さな赤い鍵は、何かの骨でできているようだ。手に持つと重いが、とても壊れやすそうに見える。なぜShadow Councilの一員がこんなものを持っていたのだろう？もしかすると、Jaedenarの中にこの奇妙な鍵で開く何かがあるのかもしれない。", "この檻から出られる日が来るのか、分からなくなってきた。\n\n奴らが崇める悪魔か何かに、私が生贄にされるのも時間の問題だ。化け物どもめ!", "keyを見つけてくれたんだな！ お願いだ、それを渡してくれ。そうすればやっと逃げ出せる！", 0x991b63d4, 0x45dab60d, 0x9b7ac879, 0x4cef28eb, 0xd6c7cd3e, "....." },
  [5203] = { "Jaedenarからの救出", "Arko'narinを、Lightforgeと彼女の装備が捕らわれている場所まで護衛し、Shadow Holdから脱出する間、彼女を守る。その後、FelwoodのJessir Moonbowを探し出し、彼女の友人たちに何が起きたかを知らせて下さい。", "でも、つらいけれど、まずやらなければならないことが一つあるの。Treyの剣Lightforgeを見つけて、Shadow Holdから脱出し、ここで何が起きているかを上官に伝えなければならないのよ。手伝ってくれる、{name}？\n\n私たちの装備はここからそう遠くないし、あなたはもう頂上までの道を生き延びられることを証明してくれたわ。\n\n脱出したら、あなたがAshenvaleとの境の近くにいる私の友人Jessirを見つけてくれるなら、私はDarnassusへ向かうわ。彼女はその近くにあるEmerald Circleのキャンプで私たちと落ち合うことになっていたの。\n\nどうかしら、{name}？もう一度手伝ってくれる？", "息が切れているようだな、{name}。大丈夫か、それとも何かあったのか?", "Arkoの脱出を助けてくれたのはあなたですか？ 私を見つけてくれて本当に嬉しいです。彼女は少し前に、Darnassusへ向かう途中でここを通りました。Lightforgeを連れていて、治療のためにドルイドたちと話す時間さえ取ろうとしませんでした。あまりにも急を要するのだと言っていました。\n\nでも、Treyの霊と遭遇したことは話してくれました。Knight of the Silver Handにとって、何と恐ろしい運命でしょう。彼女は顔には出しませんでしたが、最も親しい友の1人を失うと思うと、心が引き裂かれているのは分かります。", 0x21b3f3ee, 0xee60e3b9, 0xb7e1dfa0, 0x12c1ee3b, 0x018e6027, "....." },
  [5204] = { "光の報復", "Jaedenarへ戻り、succubusのRakaiahを倒してからRemains of Trey Lightforgeを見つける。", "彼女は平気なふりをしたいのよ。自分はこのすべてに一人で向き合えるほど強いんだと私に思わせたいの。でも、私にはそうじゃないと分かってる。Treyの死と、彼が受けた拷問の話を聞いたことは、この先ずっと彼女を苦しめるでしょうし、それを止めるために私たちにできることは何もないわ。でも、彼女に安らぎを与えることならできる！\n\n{name}、Shadow Holdに戻って、Treyを拷問した者を倒し、彼の遺骸を見つけてきて。Arko'narinが彼女なりのやり方で喪に服している間に、こうした心残りをすべて片付けられない理由はないわ。", "遺体を調べると、それがKnight of the Silver HandであるTrey Lightforgeのremainsであることは疑いようもない。一瞬、Arko'narinのことが頭に浮かび、つい先日Shadow Holdからの脱出を手助けしたあの捕虜のナイトエルフにとってこの男がそうだったほど、自分にとって大切な人が人生にいただろうかと自問する。\n\nもう少し時間をかけて考えをまとめると、まず彼を拷問した者を倒さなければ、パラディンのremainsをJessirのもとへ持ち帰ることはできないと分かる。", "できる限り慎重にパラディンのremainsを集めながら、少なくとも彼の魂は、無理やり負わされたかもしれない痛みや苦しみから解き放たれたのだと思い起こす。", 0xc22d8991, 0x11a66fd0, 0xcb462280, 0x05b3f9be, 0x7b290b2e, "....." },
  [5206] = { "DarrowshireのMarauders", "Resonating Skullsを$N1個とMystic CrystalをEastern PlaguelandsのCarlin Redpathのところへ持って行って下さい。", "Chromieが言うには、あなたが集めた遺品は強力な呪文の触媒で、あともう一つ必要なものがあるそうよ。Darrowshireの戦いに加わったscourgeの頭蓋骨なの。\n\nこのクリスタルを持って、scourge championを狩り、その頭蓋骨を手に入れてきて。クリスタルには魔法がかけられているわ。championがあの戦いに加わっていたなら、その頭蓋骨の上にクリスタルをかざすと共鳴するの。その共鳴する頭蓋骨を持ってきてちょうだい。\n\n行って、{name}。scourge championは北のNoxious Gladeと西のFungal Valeにいるわ。", "skullsは持ってきたか? Chromieが言うには、それが彼女の呪文に欠かせないそうだ。その呪文があれば、Darrowshireを救う機会が得られる。", "見つけたのですね！ 素晴らしい！\n\nそれらがどう私たちの助けになるのか完全には理解できませんが、その力を感じますし、私の故郷の村Darrowshireとつながっていることは骨身に染みて分かります。", 0xc0850ae0, 0xd13d6e76, 0x888b808d, 0x58454114, 0x745f946d, "....." },
  [5210] = { "Brother Carlin", "Extended Annals of DarrowshireをEastern PlaguelandsのCarlin Redpathのところへ持って行って下さい。", "Annals of Darrowshireは、私の魔法によって巻末にページが増え、今ではその歴史が戦いの後にまで及んでいるの。追加された一節には、もう一人のRedpath、Josephの裏切りを生き延びたCarlinのことが書かれているわ。Carlinは今、東のPlaguelandsにある、Light's Hope Chapelにいるの。\n\nその本を持って行って、彼と話してちょうだい。", "西から来たのか? Lordaeronのほかの地はどうなっている? Andorhalが陥ちたことは知っているが、Scourgeは美しいTirisfalにまで達したのか?", "この本は何だ？ Annals of Darrowshire？ そこは戦争の前の私の故郷だ……それを滅ぼした戦いの前の！ なぜこの本を私に持ってきた？\n\nだが見てくれ！ 最後に、戦いの後の日々の物語を記したページがある！ ここに私についての一節が！ そして兄弟のJosephについても！ この本は本当なのか？\n\n真実を突き止めなければ！", 0xaef5197d, 0x4f2113e1, 0xe662d317, 0x1c11302d, 0x2938b896, "....." },
  [5211] = { "Darrowshireの守り手たち", "Darrowshire Spiritsを$N1体解放し、Carlin Redpathのところへ戻って下さい。", "Darrowshireの戦いで、多くの守り手が倒れました。そして多くの者が、Scourgeのおぞましい僕として再びさまよっているのです！その哀れな魂たちを見つけ、苦しみを終わらせてください！\n\ncannibal ghoul、gibbering ghoul、そしてdiseased flayerを狩るのです。この悪鬼どもの多くは、かつてはDarrowshireの善良な住民でした。今その姿を滅ぼせば、彼らの魂は解き放たれるでしょう。\n\n奴らはPlaguewoodとCorin's Crossing、そしてEastern Plaguelandsの他のScourgeの拠点にいます。", "Darrowshireの哀れな守り手たちが、夢の中で私に叫ぶのです、{name}。彼らを解放してあげてください!", "我が同胞たちの苦しめられた魂を見つけ、解放してくれたと聞いて嬉しい。Darrowshireの守り手たちの少なくとも一部が、もはやScourgeへの忌まわしい隷属にもがいていないと知れば、私の心の涙も少しは減るだろう。", 0xa05a685e, 0x6163d07b, 0x5d3c4ea2, 0x2c1c9b22, 0x2bcd7686, "....." },
  [5212] = { "肉体は嘘をつかない", "StratholmeからPlagued Flesh Samplesを$N1個回収し、Betina Bigglezinkのところへ持ち帰って下さい。Stratholmeにいる生き物ならどれでも、その肉のサンプルを持っていそうだ。", "この世界で科学を修めた者は、Forsakenの薬剤師だけではない。\n\n私は何年も疫病を研究してきたんだ、{race}。疫病の効力は衰えつつあると以前は考えていたが、ここPlaguelandsで発見したことは驚くべきものだった。疫病は力を増しているようなんだ！\n\nもっと検査をしなければならない！ 疫病の最も強力な源は、最も新しく感染した者の穢れた肉だ。Stratholmeへ行って、サンプルを持ってきてくれ、{name}。", "心配しすぎだと言う者もいる。そういう連中にはこう言ってやるんだ、「お前たちは心配が足りない!」とね。", "伝染病の活性物質の化学構造に何らかの変異が起きたんだわ。もっとデータが必要ね。", 0x4f72055c, 0xaa8c3df4, 0x542ecc95, 0x698b30e4, 0x1aca3b74, "....." },
  [5213] = { "活性物質", "Stratholmeへ向かい、ジッグラトを探索して下さい。新たなScourge Dataを見つけ、Betina Bigglezinkに渡して下さい。", "Stratholmeのさらに奥深くへ踏み込んでもらうことになる、{name}。\n\n最初の門を越えると、zigguratsがある。Scourgeはこの建造物から大きな力を引き出していることが分かっている。Zigguratsを捜索し、見つけた情報を何でも持ち帰ってくれ。", "この新たな活性疫病因子の正体が、もうすぐ突き止められそうだ!", "驚くべきことだ! これを解剖し分析するには何か月もかかるだろう。Argent Dawnは君の尽力に感謝する、{name}。\n\n我々の祝福とともに、このSeal of the DawnかこのRune of the Dawnのどちらかを選ぶがいい。どちらも通常のArgent Dawn Commissionの代わりに使って、我々のためにscourgestoneを集めることができる。失くしたときは私に言ってくれ。代わりを用意しよう。", 0x12b4da0e, 0xfd49cf32, 0xa118cb82, 0x30423f48, 0xb7f5f20c, "....." },
  [5214] = { "偉大なるEzra Grimm", "StratholmeでEzra Grimmの煙草店を見つけ、Grimm's Premium Tobaccoの箱を取り戻して下さい。それを終えたらSmokey LaRueのところへ戻って下さい。", "ひどい話さ……Ezraに起きたことは。いいかい、町が略奪された時、Ezraは大事な品を置いていきたがらなかった。あいつが最後に言ったのはこうだ。'奴らの汚らわしい手に渡すくらいなら、葉っぱ一枚残らず燃やしてやる！'\n\n俺は上等な葉巻には目がないが、馬鹿じゃない。あの日、俺はEzraとあいつの素敵な店を置いて逃げた。あいつは炎の中で死んだんだろうが、あいつの有名な煙草が1箱でも無事に残ってる可能性があるなら……\n\nどうだい、{name}？ このSmokeyじいさんのためにひと箱見つけてくれないか？", "もう耐えられないよ、{name}! 助けてくれ! 死にそうなんだ!", "おお愛しの愛しの葉巻よ、お前に会えなくてどれほど寂しかったことか……", 0x946173e2, 0x4d00c606, 0x6ce4681e, 0x4c662689, 0xb1152024, "....." },
  [5215] = { "Scourgeの大釜", "Western PlaguelandsのChillwind PointにいるHigh Priestess MacDonnellと話して下さい。", "かつてのLordaeronの地には、八つの大釜がある――ここ西に四つ、そして東にさらに四つが据えられている。これらの大釜は毒を空中に吐き出し、Scourgeのために疫病を大地じゅうに広めているのだ。\n\nKel'Thuzadの死霊術の力はあまりに強く、これらの大釜を正面から止めることはできない。だが、我々に有利なように大釜を逆用する方法があるかもしれないと考えている。私の副官、High Priestess MacDonnellがこの任務での君の窓口となる。ここからの説明は彼女が引き継ぐ。", nil, "この暗き時代に、光の力があなたを照らしますように、{class}。Scourgeの大釜を妨害する私たちの計画で、あなたの調整役を務められることを嬉しく思います。\n\n私たちの目標は、大釜が生み出す疫病の成分を、Scourgeに悪影響を与えるものへと変えることです。この変化をもたらすには、Western Plaguelandsにある4つの大釜それぞれへの侵入経路を確保する必要があります。\n\n備えてください、英雄よ。邪悪なScourgeとの栄光ある戦いがあなたを待っています！", 0xa319eb04, 0x9a36e545, 0xce7d7f7e, nil, 0x6d217a47, "...m." },
  [5216] = { "標的：Felstone Field", "Western PlaguelandsのFelstone Fieldへ行き、そこにいるCauldron Lordを見つけて倒す。大釜に入るための鍵を持っているかもしれない。大釜の中で使われている毒のサンプルを確保するには、Empty Felstone Field Bottleを持っている必要がある。", "ここ西にある四つの大釜のうち、Felstone Fieldにあるものが最も近づきやすいかもしれません。Scourgeはそこには比較的未熟な兵を配置していますが、侮ってはいけません。\n\nAndorhalの北西にあるFelstone Fieldへ行き、そこのcauldron lordと戦ってください。それが大釜を開ける鍵を持っていると私たちは考えています。開いたら、このボトルを使って大釜の中の毒のサンプルを採ってきてください。解毒剤を開発する研究のために必要なのです。", "大釜の点検口はしっかりと閉ざされたままだ。開けるには、鍵を見つける必要がある。", "Cauldron Lord Bilemawから奪った鍵は、点検口の錠にぴったりと合う。開いた点検口から悪臭が漂い、大釜の中では濃縮された未知の物質が渦を巻いている。\n\nbottleがちょうど収まる小さな注ぎ口があり、Chillwind PointにいるHigh Priestess MacDonnellのためにサンプルを採取できる。", 0x92061966, 0x1dcb8d00, 0x7e63a5ca, 0x19857230, 0x6349babe, "....." },
  [5217] = { "Chillwind Campへ戻る", "Filled Felstone Field BottleをWestern PlaguelandsのChillwind CampにいるHigh Priestess MacDonnellのところへ持って行って下さい。", "あなたは大釜の有毒な調合物をボトルに満たした。研究に十分なサンプルの量だ。\n\n毒を手に入れた今、Chillwind CampのHigh Priestess MacDonnellのもとへ戻り、任務を完了する時だ。", "おかえり、{name}。ここChillwind Campなら比較的安全だ。大釜の件で、報告できる進展はあるか?", "よくやりました、{name}。Alchemist Arbingtonなら、これを分析して大釜に投入する対抗剤を考案するのに時間はかからないでしょう。十分な量を空気中に送り出せれば、ここにいるScourgeすべてを弱らせられるかもしれません。\n\nこれが長く続く苦難になるのは間違いありません。大釜を繰り返し襲撃し、その混合物に私たちの試薬を投入し続ける必要があります。それでも、これを続けられれば、戦いの時が来たとき、Scourgeに対して大きな優位に立てるでしょう！", 0xb5ee8811, 0xf055d521, 0x1dc2b280, 0xa5d00fba, 0x9b944f2c, "....." },
  [5219] = { "標的：Dalson's Tears", "Western PlaguelandsのDalson's Tearsへ行き、そこにいるCauldron Lordを見つけて倒し、その鍵を使って大釜に入る。大釜の中で使われている毒のサンプルを確保するには、Empty Dalson's Tears Bottleを持っている必要がある。", "疫病の大釜の一つは、今ではDalson's Tearsと呼ばれている、かつての農家の畑にあります。まあ、今日私たちが涙を流すことはないでしょう。Scourgeの企みを阻み、奴ら自身の毒気でむせ返らせてやるのですから！\n\nAndorhalのほぼ真北にあるDalson's Tearsへ行き、そこのcauldron lordを倒してください。前のものと同じように、大釜に入るための鍵を持っているはずです。このボトルを使って大釜の中からサンプルを採ってきてください。大釜にはそれぞれ独自の毒の調合があるのです。", "大釜の点検口はしっかりと閉ざされたままだ。開けるには、鍵を見つける必要がある。", "大釜の主から見つけた不気味な鍵は、鍵穴にすんなりと差し込まれて消え、以後いつでも開けられるようになった。大釜の土台の中では、ねじれた管を通ってどろりとした粘液が脈打っている。\n\nbottleがちょうど収まる小さな注ぎ口があり、Chillwind PointにいるHigh Priestess MacDonnellのためにサンプルを採取できる。", 0xd56b9979, 0x0f3a6108, 0xf7c7dc48, 0x19857230, 0x868a59fa, "....." },
  [5220] = { "Chillwind Campへ戻る", "Filled Dalson's Tears BottleをWestern PlaguelandsのChillwind CampにいるHigh Priestess MacDonnellのところへ持って行って下さい。", "あなたは慎重に、十分な大きさのサンプルと思えるだけの大釜の膿汁をボトルに満たした。\n\n毒を手に入れた今、Chillwind CampのHigh Priestess MacDonnellのもとへ戻り、任務を完了する時だ。", "各大釜は、疫病を引き起こす毒素を作るのにそれぞれ異なる試薬の配合を使っていることが分かっている。同様に、大釜ごとに固有の対抗薬を開発しなければならないことも分かっている。君がDalson's Tearsから採ってきたサンプルが、あの大釜に特有の試薬の組み合わせを突き止める鍵になるだろう。", "ああ、研究するものがたっぷりありますね。よくやりました、{name}！\n\n今のところ、次の段階は私たちの手にかかっています。大釜の中にすでにあるものと混ぜ合わせたときに対抗剤として働く、試薬のリストを作らなければなりません。\n\nこれを投入する唯一の方法は、試薬を直接大釜に入れることです。それについてはAlchemist Arbingtonが詳しいので、都合がつき次第、必ず彼と話してください。", 0xb5ee8811, 0x7a8719c4, 0x2df77e31, 0xdcb81fc2, 0x99b957f3, "....." },
  [5222] = { "標的：Writhing Haunt", "Western PlaguelandsのWrithing Hauntへ行き、そこにいるCauldron Lordを見つけて倒し、その鍵を使って大釜に入る。大釜の中で使われている毒のサンプルを確保するには、Empty Writhing Haunt Bottleを持っている必要がある。", "二つの大釜を開けることに成功しました。そちらにはいつでも入れますが、まだ残りの二つも開けたいのです。そうすれば、私たち皆にとって解毒剤を投入する選択肢が増えるのです！\n\n今度は、Writhing Hauntの大釜を攻めてもらいます。Andorhalのほぼ真東、崩れた町の城壁から比較的近いところにあります。今回も、そこにいるcauldron lordを倒して鍵を手に入れてください。このボトルを使って大釜からサンプルを採ってきてください。\n\n幸運を祈ります、{name}！", "大釜の点検口はしっかりと閉ざされたままだ。開けるには、鍵を見つける必要がある。", "大釜の主の鍵はこの大釜の点検口を開け、そして消えた。これまでに片付けた2つの大釜の鍵と同じように。腐ったような臭いの物質が、大釜の台座の下で激しく渦巻いている。\n\nbottleがちょうど収まる小さな注ぎ口があり、Chillwind PointにいるHigh Priestess MacDonnellのためにサンプルを採取できる。", 0x6f80571e, 0x1fc4daf4, 0x49ce8443, 0x19857230, 0x92049294, "....." },
  [5223] = { "Chillwind Campへ戻る", "Filled Writhing Haunt BottleをWestern PlaguelandsのChillwind CampにいるHigh Priestess MacDonnellのところへ持って行って下さい。", "あなたは空のボトルを慎重に満たした。大釜の足場の下で渦巻いていた汚らわしい物質のサンプルが、壊れやすいガラスの容器の中で今は前後にどろりと揺れている。\n\n毒を手に入れた今、Chillwind CampのHigh Priestess MacDonnellのもとへ戻り、任務を完了する時だ。", "Writhing Hauntの大釜から採ったサンプルの分析に成功すれば、Scourgeに壊滅的な対抗薬を浴びせる三つ目の手段が手に入る!", "またしても見事な任務遂行です、{name}！ これでScourgeに逆らわせることのできる大釜が3つになりました。この地に対するKel'Thuzadの死霊術による支配が今ほど強くなければ、あなたは大釜を完全に停止させていたと言ってもいいくらいです！\n\nAlchemist Arbingtonが、この大釜と、これまでに乗っ取った他の大釜に、疫病への対抗剤を送り込むために何が必要かを報告してくれるでしょう。さあ、西の最後の大釜を私たちの支配下に置く時が来ました！", 0xb5ee8811, 0xc03ccc2f, 0xe333822c, 0xf24f8119, 0x7d43aa3d, "....." },
  [5225] = { "標的：Gahrron's Withering", "Western PlaguelandsのGahrron's Witheringへ行き、そこにいるCauldron Lordを見つけて倒し、その鍵を使って大釜に入る。大釜の中で使われている毒のサンプルを確保するには、Empty Gahrron's Withering Bottleを持っている必要がある。", "残っている最後の大釜は、今ではGahrron's Witheringと呼ばれる農場にあります。そこはScourgeの手強い手下ども――具体的にはレイスと幽霊――に守られています。侮ってはいけませんよ、{name}。\n\nGahrron's Witheringはここから真北東、Eastern Plaguelandsが始まるあたりの近くにあります。今回も、そこにいるcauldron lordを倒して鍵を手に入れてください。これが空のサンプルボトルです。満たして持ってきてください。この危険な任務で光があなたを守りますように、{class}よ。", "大釜の点検口はしっかりと閉ざされたままだ。開けるには、鍵を見つける必要がある。", "Cauldron Lord Soulwrathの鍵は、大釜の台座の基部にある点検口の錠に触れた途端、崩れ去った。中からかすかにガチャリという音が聞こえ、点検口が開くと、大釜の骨組みの中にさらに粘ついた毒物が見える。\n\nbottleがちょうど収まる小さな注ぎ口があり、Chillwind PointにいるHigh Priestess MacDonnellのためにサンプルを採取できる。", 0xbd246940, 0x48ca8f98, 0xfd678d22, 0x19857230, 0xb16092b0, "....." },
  [5226] = { "Chillwind Campへ戻る", "Filled Gahrron's Withering BottleをWestern PlaguelandsのChillwind CampにいるHigh Priestess MacDonnellのところへ持って行って下さい。", "あなたは制御盤の栓を慎重に閉め、大釜の腐った膿汁が空のボトルに滴り落ちるのを見守った。\n\n毒を手に入れた今、Chillwind CampのHigh Priestess MacDonnellのもとへ戻り、任務を完了する時だ。", "Gahrron's Witheringには、ここ西部で我々が近づかなければならない最後の大釜がある。そこから噴き出す疫病のサンプルが手に入れば、4つの別々の器を通して我々の試薬を周囲に行き渡らせることができる! たとえKel'Thuzadの力が後ろ盾にあろうと、Scourgeが4つすべてから我々を締め出すのは難しいだろう。", "おめでとうございます、{name}。最後の大釜を私たちのために開けてくれましたね！ 混合物にどんな試薬が必要か、Alchemist Arbingtonがすぐに突き止めてくれるでしょう。\n\nあなたについては、Commander Valorfistがきっと、私たちに与えてくれた助力について直接お礼を言いたがるはずです。あなたがいなければ、Scourgeとの戦いはほとんど乗り越えられないものになっていたでしょう。ありがとう、英雄よ！", 0xb5ee8811, 0x8eb15622, 0x04933e62, 0xfc41e6cc, 0x23611b6c, "....." },
  [5228] = { "Scourgeの大釜", "Western PlaguelandsのBulwarkにいるShadow Priestess Vandisと話して下さい。", "かつてのLordaeronの地には、八つの大釜がある――西に四つ、そして東にさらに四つが陣取っている。これらの大釜は毒を空中に吐き出し、Scourgeのために疫病を大地じゅうに広めているのだ。\n\nKel'Thuzadの死霊術の力はあまりに強く、これらの大釜を正面から止めることはできない。だが、我々に有利なように大釜を逆用する方法があるかもしれないと考えている。私の副官、Shadow Priestess Vandisがこの任務でのお前の窓口となる。ここからの説明は彼女が引き継ぐ。", nil, "影の中より挨拶を送ろう、同胞たる{race}よ。Scourgeの大釜を妨害する我々の計画で、お前の調整役を務めることになった。\n\n我々の目標は、大釜が生み出す疫病の成分を、Scourgeに悪影響を与えるものへと変えることだ。この変化をもたらすには、ここWestern Plaguelandsにある4つの大釜それぞれへの侵入経路を確保する必要がある。\n\nScourgeへの突撃を率いる時が来たぞ、英雄よ。", 0xa319eb04, 0xd8bc2aad, 0xc83fd89e, nil, 0xbd4a0dd4, "...m.", nil, nil, nil, nil, 0xaf72b061 },
  [5229] = { "標的：Felstone Field", "Western PlaguelandsのFelstone Fieldへ行き、そこにいるCauldron Lordを見つけて倒す。大釜に入るための鍵を持っているかもしれない。大釜の中で使われている毒のサンプルを確保するには、Empty Felstone Field Bottleを持っている必要がある。", "Western Plaguelandsにある四つの大釜のうち、Felstone Fieldのものが最も入り込みやすいだろう。Scourgeはそこには比較的未熟な兵を配置しているが、侮ってはならない。\n\nここから真東、Andorhalの北西にあるFelstone Fieldへ行き、そこのcauldron lordと戦え。そいつが大釜を開ける鍵を持っている。開いたら、このボトルを使って大釜の毒のサンプルを採ってこい。解毒剤を開発する研究のために必要なのだ。", "大釜の点検口はしっかりと閉ざされたままだ。開けるには、鍵を見つける必要がある。", "Cauldron Lord Bilemawから奪った鍵は点検口の錠にぴったりと合ったが、使うと消えてしまった。それでも、これからは鍵なしで点検口を開けられそうだ。開いた点検口から悪臭が漂い、大釜の中では濃縮された未知の物質が渦を巻いている。\n\nbottleがちょうど収まる小さな注ぎ口があり、BulwarkにいるShadow Priestess Vandisのためにサンプルを採取できる。", 0x92061966, 0x1dcb8d00, 0x96d41740, 0x19857230, 0xee093d43, "....." },
  [5230] = { "Bulwarkへ戻る", "Filled Felstone Field BottleをWestern PlaguelandsのBulwarkにいるShadow Priestess Vandisのところへ持って行って下さい。", "あなたは大釜の有毒な調合物をボトルに満たした。研究に十分なサンプルの量だ。\n\n毒を手に入れた今、BulwarkのShadow Priestess Vandisのもとへ戻り、任務を完了する時だ。", "おかえり、{name}。ここBulwarkなら比較的安全だ。大釜の件で、報告できる進展はあるか?", "よくやった、{name}。Apothecary Dithersなら、これを分析して大釜に投入する対抗剤を考案するのに時間はかからないだろう。十分な量を空気中に送り出せれば、ここにいるScourgeすべてを弱らせられるかもしれん。\n\nこれが長く続く苦難になるのは間違いない。大釜を繰り返し襲撃し、その混合物に我々の試薬を投入し続ける必要がある。それでも、これを続けられれば、戦いの時が来たとき、Scourgeに対して大きな優位に立てるだろう！", 0x45c54db8, 0x1aa51cd7, 0xfdfaed2b, 0x4c0d32d7, 0xa1c30348, "....." },
  [5231] = { "標的：Dalson's Tears", "Western PlaguelandsのDalson's Tearsへ行き、そこにいるCauldron Lordを見つけて倒し、その鍵を使って大釜に入る。大釜の中で使われている毒のサンプルを確保するには、Empty Dalson's Tears Bottleを持っている必要がある。", "疫病の大釜の一つは、今ではDalson's Tearsと呼ばれている、かつての農家の畑にある。今日は涙を流すことはないぞ、{class}。この大釜を攻め、中に入り込まねばならん！\n\nAndorhalのほぼ真北にあるDalson's Tearsへ行き、そこのcauldron lordを倒せ。前のものと同じように、大釜の内部へ入るための鍵を持っているはずだ。このボトルを使って大釜の中からサンプルを採ってこい。大釜にはそれぞれ独自の毒の調合があるのだ。", "大釜の点検口はしっかりと閉ざされたままだ。開けるには、鍵を見つける必要がある。", "大釜の主から見つけた骸骨の鍵は、鍵穴にすんなりと差し込まれて消え、以後いつでも開けられるようになった。大釜の土台の中では、ねじれた管を通ってどろりとした粘液が脈打っている。\n\nbottleがちょうど収まる小さな注ぎ口があり、BulwarkにいるShadow Priestess Vandisのためにサンプルを採取できる。", 0xd56b9979, 0x0f3a6108, 0x13261da4, 0x19857230, 0x1c2a06c6, "....." },
  [5232] = { "Bulwarkへ戻る", "Filled Dalson's Tears BottleをWestern PlaguelandsのBulwarkにいるShadow Priestess Vandisのところへ持って行って下さい。", "あなたは慎重に、十分な大きさのサンプルと思えるだけの大釜の膿汁をボトルに満たした。\n\n毒を手に入れた今、BulwarkのShadow Priestess Vandisのもとへ戻り、任務を完了する時だ。", "各大釜は、疫病を引き起こす毒素を作るのにそれぞれ異なる試薬の配合を使っていることが分かっている。同様に、大釜ごとに固有の対抗薬を開発しなければならないことも分かっている。君がDalson's Tearsから採ってきたサンプルが、あの大釜に特有の試薬の組み合わせを突き止める鍵になるだろう。", "ああ、研究するものがたっぷりあるな。よくやった、{name}！\n\n今のところ、次の段階は我々の手にかかっている。大釜の中にすでにあるものと混ぜ合わせたときに対抗剤として働く、試薬のリストを作らねばならん。\n\nこれを投入する唯一の方法は、試薬を直接大釜に入れることだ。それについてはApothecary Dithersが詳しいから、できるだけ早く彼と話してくれ。", 0x45c54db8, 0xf93a1fff, 0x5d6b63ef, 0xdcb81fc2, 0xab0cf46a, "....." },
  [5233] = { "標的：Writhing Haunt", "Western PlaguelandsのWrithing Hauntへ行き、そこにいるCauldron Lordを見つけて倒し、その鍵を使って大釜に入る。大釜の中で使われている毒のサンプルを確保するには、Empty Writhing Haunt Bottleを持っている必要がある。", "二つの大釜を開けることに成功した。そちらにはいつでも入れるが、残りの二つもまだ開けたい。そうすれば、我々皆にとって解毒剤を投入する選択肢が増えるのだ！\n\n今度は、Writhing Hauntの大釜を攻めてもらう。Andorhalのほぼ真東、崩れた町の城壁から比較的近いところにある。今回も、そこにいるcauldron lordを倒して鍵を手に入れろ。このボトルを使って大釜からサンプルを採ってこい。\n\n幸運を祈る、{name}！", "大釜の点検口はしっかりと閉ざされたままだ。開けるには、鍵を見つける必要がある。", "大釜の主の鍵はこの大釜の点検口を開け、そして消えた。これまでに片付けた大釜の鍵と同じように。腐ったような臭いの物質が、大釜の台座の下で激しく渦巻いている。\n\nbottleがちょうど収まる小さな注ぎ口があり、BulwarkにいるShadow Priestess Vandisのためにサンプルを採取できる。", 0x6f80571e, 0x1fc4daf4, 0xb8c56557, 0x19857230, 0x4cff0616, "....." },
  [5234] = { "Bulwarkへ戻る", "Filled Writhing Haunt BottleをWestern PlaguelandsのThe BulwarkにいるShadow Priestess Vandisのところへ持って行って下さい。", "あなたは空のボトルを慎重に満たした。大釜の足場の下で渦巻いていた汚らわしい物質のサンプルが、壊れやすいガラスの容器の中で今は前後にどろりと揺れている。\n\n毒を手に入れた今、BulwarkのShadow Priestess Vandisのもとへ戻り、任務を完了する時だ。", "Writhing Hauntの大釜から採ったサンプルの分析に成功すれば、Scourgeに対して壊滅的な対抗薬を届ける三つ目の手段が手に入る!", "またしても見事な任務遂行だ、{name}！ これでScourgeに逆らわせることのできる大釜が3つになった。この地に対するKel'Thuzadの死霊術による支配が今ほど強くなければ、お前は大釜を完全に停止させていたと言ってもいいくらいだ！\n\nApothecary Dithersが、この大釜と、これまでに乗っ取った他の大釜に、疫病への対抗剤を送り込むために何が必要かを報告するだろう。さあ、西の最後の大釜を我々の支配下に置く時が来たぞ！", 0x45c54db8, 0x7e17ab7e, 0x691909b9, 0x463535af, 0xe45f216f, "....." },
  [5235] = { "標的：Gahrron's Withering", "Western PlaguelandsのGahrron's Witheringへ行き、そこにいるCauldron Lordを見つけて倒し、その鍵を使って大釜に入る。大釜の中で使われている毒のサンプルを確保するには、Empty Gahrron's Withering Bottleを持っている必要がある。", "残っている最後の大釜は、今ではGahrron's Witheringと呼ばれる農場にある。そこはScourgeの手強い手下ども――具体的にはレイスと幽霊――に守られている。侮ってはならんぞ、{name}。\n\nGahrron's WitheringはBulwarkからはるか東、Eastern Plaguelandsが始まるあたりの近くにある。今回も、そこにいるcauldron lordを倒して鍵を手に入れろ。これが空のサンプルボトルだ。満たして持ってこい。この危険な任務で影がお前を安全に包み隠さんことを、{class}よ。", "大釜の点検口はしっかりと閉ざされたままだ。開けるには、鍵を見つける必要がある。", "Cauldron Lord Soulwrathの鍵は、大釜の台座の基部にある点検口の錠に触れた途端、崩れ去った。中からかすかにガチャリという音が聞こえ、点検口が開くと、大釜の骨組みの中にさらに粘ついた毒物が見える。\n\nbottleがちょうど収まる小さな注ぎ口があり、BulwarkにいるShadow Priestess Vandisのためにサンプルを採取できる。", 0xbd246940, 0x48ca8f98, 0x159fedea, 0x19857230, 0xe47b642b, "....." },
  [5236] = { "Bulwarkへ戻る", "Filled Gahrron's Withering BottleをWestern PlaguelandsのBulwarkにいるShadow Priestess Vandisのところへ持って行って下さい。", "あなたは制御盤の栓を慎重に閉め、大釜の腐った膿汁が空のボトルに滴り落ちるのを見守った。\n\n毒を手に入れた今、BulwarkのShadow Priestess Vandisのもとへ戻り、任務を完了する時だ。", "Gahrron's Witheringには、ここ西部で我々が近づく手段を得なければならない最後の大釜がある。その大釜から疫病のサンプルが手に入れば、4つの別々の器を通して我々の試薬を周囲に行き渡らせることができる! たとえKel'Thuzadの力が後ろ盾にあろうと、Scourgeが4つすべてから我々を締め出すのは難しいだろう。", "おめでとう、{name}。最後の大釜を我々のために開けてくれたな！ 混合物にどんな試薬が必要か、Apothecary Dithersがすぐに突き止めるだろう。\n\nお前については、High Executor Derringtonがきっと、我々に与えてくれた助力について直接礼を言いたがるはずだ。お前がいなければ、Scourgeとの戦いはほとんど乗り越えられないものになっていただろう。感謝するぞ、力強き{class}よ。", 0x45c54db8, 0x8394b611, 0x740b59b6, 0xb5a5a86c, 0x484e1603, "....." },
  [5237] = { "任務完了！", nil, nil, nil, "{name}、君による大釜の改造の成功は、我々にとって途方もない勝利だ！\n\n<司令官は咳払いをすると、大声で叫び始めた。>\n\n我が前にいる者すべて、聞くがよい。Kingdom of StormwindとAllianceへの、義務の要求をはるかに超えた奉仕に対し──圧倒的に不利な状況と信じがたい危険の中で、と付け加えておこう──我は{name}にこれを授け、Allianceの真の英雄として、我らの不滅の感謝を捧げる。乾杯だ！", 0x48e07c4f, nil, nil, nil, 0x3f13bcd4, ".mmm.", nil, nil, nil, nil, 0x4417209a },
  [5238] = { "任務完了！", nil, nil, nil, "{name}、お前による大釜の改造の成功は、我々にとって途方もない勝利だ！\n\n<高位執行官は咳払いをすると、大声で叫び始めた。>\n\n我が前にいる者すべて、聞くがよい。Forsaken、そしてHorde全体への、期待をはるかに超えた奉仕に対し──圧倒的に不利な状況と信じがたい危険の中で、と付け加えておこう──我は{name}にこれを授け、Hordeの真の英雄として、我らの不滅の感謝を捧げる。万歳！", 0x48e07c4f, nil, nil, nil, 0x39fafac6, ".mmm.", nil, nil, nil, nil, 0xc5dc7c2f },
  [5241] = { "Uncle Carlin", "Carlin Redpathを見つける。", "ときどき、夜になると、Uncle Carlinが泣いてるのが聞こえるの。遠くの、東の方から聞こえるみたい。\n\n私のために泣いてるんじゃないといいな！{name}、おじさんを見つけて、私は大丈夫だよって伝えてくれる？\n\nおじさんを見つけたら、私が待ってるって伝えて。それから、前によく話してくれたお話が聞きたいって……ウサギとベリージャムのお話！あのお話、すっごく面白いんだから！", nil, "Pamelaに会ったのか？ あの子は生きているのか？\n\n死んでいる？ そんな！ ああ、Pamela！ なぜお前の魂はまだこの世で苦しんでいるのだ。なぜお前は死に、運命は私を生かし続けるのだ？ 叶うものなら今すぐお前と入れ替わり、死せるDarrowshireを、ひとりぼっちの幽霊としてさまよおうものを！\n\nだが、この知らせで運命が変わるわけではない。ありがとう、{name}。今や私の務め、復讐という務めが、これまで以上に熱く燃えている。", 0xb32159b5, 0x6db66850, 0xdaa2b5cb, nil, 0xaa9535cb, "...m." },
  [5242] = { "最後の一撃", "MooraとSaliaを倒し、Shadow Lord Fel'dan's HeadをFelwoodのGreta Mosshoofのところへ持って行って下さい。", "残念ながら、Felwoodへのこの脅威を止める唯一の方法は正面攻撃しかないようです。Shadow Holdへ入る道は他になく、あなたを中へテレポートさせる手段も私にはありません。底へまっすぐ下りていく道だけが唯一の方法です……そして、あなたが誰を探すべきかも分かっています。その名はFel'dan……Shadow Lord Fel'danです。彼が下で権力を握る定命の者……蛇の頭なのです。彼と、その二人のsuccubusの従者を倒して、私のもとへ戻ってきてください。Legionと契約を結んでいるのはFel'danです。彼を止めなければなりません。", "Fel'danがいなくなれば、Shadow Councilは統率を失い、内輪揉めを始めるだろう。奴らは主導権を巡って互いに争い、今後の計画のために資産を溜め込むはずだ。そのときこそ、奴らとその悪魔の奴隷どもを叩き潰す好機だ。", "Earthmotherに讃えあれ、{name}！ ありがとう！ 実に素晴らしい日だ！\n\nこの打撃で指導者層を失ったShadow Councilは、かつて持っていたのと同じ力を取り戻すのに苦労するだろう。君は今日、偉大なことを成し遂げたのだ！", 0x715aa831, 0xe88b2237, 0x279f369a, 0xe2ec25f5, 0x8ad810c1, "....." },
  [5243] = { "神の家", "北のStratholmeへ向かって下さい。町に散乱している木箱を探し、Stratholme Holy Water 5つを取り戻して下さい。祝福された水を集め終えたらLeonid Barthalomew the Reveredのところへ戻って下さい。", "私は自分の不死を病だと考えています、{race}。治療を要するだけの病です。しかし、それはArgent Dawnにとって大いなる恵みでもあるのです。Scourgeの異教徒どもを討つのに、アンデッド以上にふさわしい器があるでしょうか？\n\n私は払ってきた犠牲ゆえに同胞から敬われていますが、称賛など私には何の意味もありません。\n\nArgent Dawnに力を貸すことに興味があるなら、お任せできる仕事があります。\n\nStratholmeへ赴き、我々の余剰の聖水を回収してきてください。補給箱を探してください。", "気をつけろ、都市が壊滅したとき、補給箱がすべて無事だったとは限らない。Scourgeは水に手を出そうとしないが、聖水が害虫の侵入まで防いでくれるわけではないだろう。", "よくやった、{race}。お前は他者に寛大でありながら、Kel'Thuzadの手下を殺すためなら何でもすると証明してみせたのだ。", 0x7afa4fb5, 0xcc65272a, 0xe916eb65, 0x964cf564, 0x32cba1e6, "....." },
  [5244] = { "Kel'Therilの遺跡", "Starfall VillageにいるJaron Stoneshaperと話して下さい。", "Kel'Therilにまつわる物語は、呪われた種族の物語です。彼らは不幸な儀式を試みたその場所に縛りつけられているのです……\n\nそこで出会うhighborneは、かつて聖なる遺物を盗み出しました。その力を自分たちのものとして吸い上げ、さらに強大になれると信じていたのです。その試みの中で遺物は大爆発とともに砕け散り、その破片は湖の氷の下へと沈んでしまいました……\n\nもっと知りたければ、Jaron Stoneshaperと話してください。彼は最近その一帯を訪れていて、もっと詳しく教えてくれるでしょう。", nil, "ああ、いいとも、Kel'Therilについてもっと話してやろう。言っておくが、わしは歴史家じゃない。だが、あそこで見たものについてなら話してやれるぞ……", 0x72a68b2c, 0x30581a76, 0x8305ca6f, nil, 0xb7174f8c, "...m." },
  [5245] = { "Kel'Therilのさまよう霊", "Jaron's Pickを使って四つのHighborne Relic Fragmentsを見つける。それをEastern PlaguelandsのAurora Skycallerのところへ持って行って下さい。", "highborneの霊ってのは、まったく哀れな連中だよ。奴らは今も、自分たちをKel'Therilに永遠に縛りつけた、まさにその呪いの元――盗まれた遺物――の破片を探し続けてるんだ。\n\nそんなに興味があるなら、俺のつるはしを持って南の湖へ行って、氷の中からその破片を集められるか試してみな。\n\nさて、見つけたものについて俺は何一つ教えてやれないが、分かりそうな奴なら知ってる……Aurora Skycallerだ。彼女はEastern Plaguelandsの北部、Northpass Towerの近くに住んでる。", "なぜここへ来た?", "high elvesの過去については話したくないのです、{name}。どうか……起きたことすべてを思うと胸が痛みます……そして、それを正す方法がないことも。", 0x59488fa1, 0x2d763bfa, 0xc5c65ece, 0x485a68cd, 0x24475225, "....." },
  [5246] = { "過去の欠片", "AzsharaのTemple of Zin-MalorでSacred Highborne Writingsを見つけ、Eastern PlaguelandsのNorthpass Tower近くにいるAurora Skycallerのところへ持って行って下さい。", "知らなかったのです……心ない言葉をお許しください、{class}よ。\n\n先祖の過ちは、私が思い悩みたいことではありません。ですが、あなたの願いが本当に心からのものなら、お力になりましょう。\n\n<Auroraは破片を調べる。>\n\nこれはCrystal of Zin-Malorだと思います。強い秘術の力を封じ込め、制御することのできる遺物です。善のために使うこともできたはずですが、盗んだ者たちの邪悪な意図のせいで砕けてしまったのです。\n\nAzsharaのTemple of Zin-Malorへ行ってください。あの本がまだそこにあることを祈るばかりです。", "そなたの力になれるかどうかを見極められるのは、聖なる書物のページの中だけだ……", "これらのページは、何年も何年も誰にも触れられていない……", 0x27ceb4bb, 0x7f781651, 0x8b4619f9, 0x1e46fcd2, 0x1017a873, "....." },
  [5247] = { "過去の欠片", "Enchanted Thorium Bar、Crystal Restoreを$N1個、Vial of Dire WaterをEastern PlaguelandsのNorthpass Tower近くにいるAurora Skycallerのところへ持って行って下さい。", "遺物を作り直すことが本当にあなたの望みなら、お手伝いできるでしょう。\n\n破片を再び一つに封じるには、強い魔力を持つ品が必要です。enchanted thorium barと、crystal restoreを五つ……それから、思いもよらないような場所から水を汲んできてもらわなければなりません……FeralasのDire Maul、Eldreth Row沿いにある淀んだ池を見つけて、この小瓶を満たしてきてください。\n\nあなたが出かけている間に、私はこのページから、遺物が受けた損傷を修復するのに必要な知識を読み取ってみます。", "その聖遺物は、最も信頼に足る者の手にのみ託されねばならぬ。二度と盗まれてはならぬのだ……", "これらの素材を使えば、欠片を融合させられる……願わくは、元の姿に。", 0x27ceb4bb, 0x4f666a1d, 0x4e3bcc04, 0xaf7eee29, 0xb2bf6926, "....." },
  [5248] = { "過去に苛まれて", "Crystal of Zin-MalorをWinterspringのLake Kel'Therilへ持って行き、話をしてくれるhighborneの霊を見つける。", "{name}、私は過去に起きたことを思って涙を流しています。このクリスタルのように、エルフもまた一つの種族として砕けてしまいました。その破片が再び一つになる日が来るのかは分かりませんが、あなたのこのささやかな務めを手伝えたことで、私の悲しみは和らぎました。\n\n過去を忘れてはなりません、{name}……\n\nCrystal of Zin-MalorをLake Kel'Therilへ持ち帰ってください。遠い昔に犯された過ちに気づいているhighborneの霊を見つけなければなりません。私たちが物事を再び正したことを、その霊に示してください。", "呪わぁぁぁれし……永遠にぃぃぃ……", "お願いぃ……放っておいてぇぇぇ……", 0xa94fcf42, 0x50bb5fb9, 0xce237f63, 0x80ad8577, 0xabfe6023, "....." },
  [5249] = { "Winterspringへ！", "WinterspringのStarfall Villageを見つけ、Wynd Nightchaserと話して下さい。", "ここから北のWinterspringには、古代のエルフの遺跡がたくさんあります。厳しい土地ですが、多くの秘密と探索できる場所を秘めているのです。\n\nここFelwoodでの仕事が山ほどあるので、私はWinterspringへ行く機会がありませんでした。でも、あなたが行ってはいけない理由はありませんよ！\n\n向こうに着いたら、Wynd Nightchaserを探してください。彼はたいていStarfall Villageにいて、あの一帯のことをよく知っています。", nil, "Ivy Leafrunnerの友達？ はじめまして、{name}。", 0x21f29268, 0xb58824fe, 0x1884e677, nil, 0xf988d04b, "...m." },
  [5250] = { "Starfall", "WinterspringのStarfallを見つけ、Wynd Nightchaserと話して下さい。", "Felwoodの北のWinterspringには、古代のエルフの遺跡がたくさんあります。厳しい土地ですが、多くの秘密と探索できる場所を秘めているのです。\n\nここでの研究でとても忙しく、しばらくWinterspringへ行く機会がありませんでした。でも、あなたがそこへ行って遺跡を研究してはいけない理由はありません。\n\n向こうに着いたら、Wynd Nightchaserを探してください。彼はたいていStarfallにいて、あの一帯のことをよく知っています。\n\n私の教え子だと彼に伝えてください……", nil, "Daryn Lightwindの弟子？ はじめまして、{name}。", 0xc6c6cea4, 0x9b1efe0a, 0xaff8bd19, nil, 0x4a9ac80d, "...m." },
  [5251] = { "公文書管理人", "Stratholmeへ向かいScarlet CrusadeのArchivist Galfordを探し出して下さい。彼を倒し、Scarlet Archiveを焼き払って下さい。", "何事も極端に走れば、この世界にとって危険なものとなるのだ、{name}。たとえばScarlet Crusadeだ。奴らの盲目的な狂信が、より大きな善に役立っていると思うか？ 光の名のもとに、奴らはどれほどの罪なき者を殺してきた？\n\n冒涜者どもめ、一人残らず！\n\nだが、特に気になる者が一人いる。StratholmeのArchivist Galford――Crusadeの最も貴重な文書を管理している男だ。奴を倒し、その書庫を焼き払え！ 成功したら、私のもとへ戻って報酬を受け取るがいい。", "忘れないでください、{name}。私たちは寛容でありながら、信念においては揺るぎなくあらねばならないのです!", "素晴らしい、{name}! 長年にわたる知識は失われた! Scarlet Crusadeは確実にこれから数週間は痛手を被るに違いない。", 0x7ba79c30, 0x8207dc1a, 0x58e34892, 0x2a558b5c, 0x6aa5a518, "....." },
  [5252] = { "Remorseful Highborne", "Starfall VillageのWynd Nightchaserと話し、Crystal of Zin-Malorを置くのにふさわしい場所について尋ねて下さい。", "その……そのクリスタル……\n\nここのhighborneは、自らの苦しみぃぃに曇らされている……\n\n我は悲しいぃぃぃ……だが、遠い昔に起きたことの過ちぃぃを悟った。過去を変える方法はなぁぁいが、そなたがZin-Malorのクリスタルを取り戻したと知り、今は安らかぁぁぁな心でいる……\n\nそなたはそれを返さねばならぬぅぅ……\n\nそれは返されねばならぁぁぁぬ。", "そなたが発ってからしばらく経つな、{name}。首尾はどうであった?", "それは……私が思っているものか？", 0x9dd30815, 0xb93b2362, 0x45f52999, 0xf5d97136, 0xbed1d8bc, "....." },
  [5253] = { "Crystal of Zin-Malor", "Crystal of Zin-MalorをDarnassusのArch Druid Fandral Staghelmに届けて下さい。", "実に見事だ、{name}。\n\ncrystal of Zin-Malorは、そなたも知っての通り廃墟と化した神殿へ戻すことは決してできぬ。だが、過去の悪を正そうとしたそなたの努力が報われぬままであってはならぬと思う。\n\nDarnassusのArch Druid Fandral Staghelmを訪ね、そのクリスタルを彼に届けるのだ、{name}。それは、その力を悪用せぬ者の手にあるべきだ。見たところ、このような力を制御できるのは、ほんの一握りの最も強い魔法の使い手だけであろう。", "何だ、{race}?", "Crystal of Zin-Malorのことは聞いたことがあります。crystalを使う者は信じがたいほどの秘術の力を得られますが、それは真にふさわしい者である場合だけです。あなたがcrystalを取り戻しただけでなく、自らの限界をわきまえ、自分で使おうとしなかったことに感服しました。\n\n私のもとへ持ってきてくれてありがとう、{name}。私たちが安全に保管します。そして、砕けたcrystalをかつて守っていた呪われた霊たちが、ようやく安らげますように。", 0xf4d24de4, 0x0d193f8b, 0xc6214ed0, 0x98b629a5, 0xc4680ce0, "....." },
  [5261] = { "Eagan Peltskinner", "Eagan Peltskinnerに話しかける。", "Eagan Peltskinnerが、オオカミを狩ってくれる人を探している。\n\n近頃は、Northshire Valleyでオオカミが増えすぎていてな。オオカミ狩りは、ぜひやってもらいたいのだ。\n\nもし興味があるなら、Eaganの話を聞いてみるといい。彼ならその修道院の左に回ったところにいるはずだ。", nil, "オオカミ狩りをしてくれる人を探してたんだよ！君、もちろんやるよね？", 0x798f9e22, 0x1419ddfe, 0x80800b5d, nil, 0x8ef5cba7, "...m." },
  [5262] = { "真実の崩壊", "Eastern PlaguelandsのDuke Nicholas ZverenhoffにHead of Balnazzarを渡して下さい。", "部屋に舞う埃が落ち着く中、あなたは考えをまとめようとする。今起きた出来事を思い返すが、事態の重大さをいまだに理解できない。\n\nScarlet Crusadeの大十字軍長が悪魔だったとは？ それもただの悪魔ではなく、Undercityの大君主Varimathrasの兄弟だとは？\n\nあなたは切り落とされたdreadlordの首を慎重に荷物にしまい込む。証拠がなければ、あなたが語る話を信じる者など誰もいないだろう。\n\nDuke Nicholas Zverenhoffにすぐに知らせなければ！", "何を持ってきたんだ、{name}?", "Scarlet Crusadeにとってはどういうことを意味するんだ? 彼らはこの悪魔に操られていたとも考えられるのか? 知らず知らず巨大な邪悪の手先として働いていたのか?", 0xdf0dc93f, 0xc0a29039, 0x72ee28db, 0x421c38bd, 0x6b42c078, "....." },
  [5263] = { "予想以上", "Stratholmeへ侵入しBaron Rivendareを倒して下さい。彼の首を手に入れ、Duke Nicholas Zverenhoffのところへ戻って下さい。", "お前には破壊への天賦の才があり、しかも命令に従う。この2つが共存するのは稀なことだ。お前は神の正義を担う優れた器になるやもしれぬと思い始めている。\n\n<Zverenhoffが顔の前で両手を組み合わせる。>\n\nKel'Thuzadの使い走りがStratholmeを支配している。お前が勇者であることを――我が勇者であることを証明してみせよ。Baron Rivendareを倒し、その首を持って戻ってくるのだ。", "Baronが殺してきた人の数は、お前が生涯で目にしてきた人の数よりも、おそらく多いだろう。", "我々の軍に戦士を迎え入れるのは久しぶりだ。君はこの何年かでLord Maxwellとの会見を認められる初めての者だ。", 0xac2caf3c, 0xb6da1920, 0x268218ec, 0x44c81fad, 0xf37aa225, "....." },
  [5264] = { "Lord Maxwell Tyrosus", "Lord Maxwell Tyrosusと話して下さい。彼は教会の中にいる。", "あなたに大きな栄誉を授けようとしているところだ、{name}。\n\nLord Maxwellが、Argent Dawnへのあなたの奉仕に報いたいと望んでおられる！\n\nMaxwellが部外者に謁見を許すのは、何年ぶりのことだろうか。", nil, "そなたは頼もしき盟友だ、{name}。その揺るぎない献身の報酬を受け取るがよい。", 0x1364f0fb, 0x99ff2cfe, 0x5a4af27e, nil, 0xa162c931, "...m." },
  [5265] = { "Argent Hold", "Argent Holdを開けて報酬を受け取る。", "長年にわたり、Argent Holdは閉ざされたままだった。その中に手を伸ばし、Argent Dawnの力を手にするにふさわしい者は一人もいなかった――今日までは。\n\nArgent Holdは今、あなたに開かれた、{name}。", nil, "うわぁ……", 0xd610942f, 0xfe201250, 0xc61acfd7, nil, 0x3ff71786, "...m." },
  [5281] = { "安らぎを見出せぬ魂", "Eganを探し出して下さい。彼が最後に目撃されたのはStratholmeの周りだったということだけが分かっています。", "Stratholmeの陥落で悲劇的な死を遂げた者たちがいる。多くの者が、Scourgeの一員になるよりはと、くすぶる街の無数の炎の中へ身を投げ、自ら命を絶った。\n\n彼らは今、安らげぬ魂としてStratholmeの通りをさまよっている。\n\n我々は彼らを救わなければならない、{name}！\n\n私にはEganという仲間がいて、幽霊や魂について驚くべき研究をしている。彼を探してくれ。彼はStratholmeの近く、Plaguelandsの東部を歩き回って、自分の発明を試している。", nil, "Alenはようやく勇敢な者を見つけたのかね?", 0xc6ed1aa3, 0x2da086ce, 0x5c19473a, nil, 0x60ee9488, "...m." },
  [5282] = { "安らぎを見出せぬ魂", "Stratholmeの亡霊や幽霊の市民たちにEgan's Blasterを使う。さまよう魂が亡霊の殻から抜け出したら、もう一度ブラスターを使えば、彼らは自由になる!\n\nRestless Soulsを$N1体解放し、Eganのところへ戻って下さい。", "私は力を――生き、呼吸し続ける意志を――Scourgeとその所業に対する抑えきれぬ憎しみから得ている。だが、私は狂信者ではない。Scarlet Crusadeのように、罪なきアンデッドにほんのわずかな慈悲をかけるくらいなら滅ぼしてしまおうという者たちもいる。\n\nそこでこれだ。私のブラスター。これがStratholmeから苦しむ魂たちを解き放つ。\n\n荒らされた通りに取り憑く幽霊たちに使ってくれ。彼らの魂を解放するのだ。", "思いやりこそが、我々と獣とを分かつものだ、{name}。それを覚えておくといい……", "<Eganが目から涙を拭う。>\n\n母に会ったのか、{name}? 母を解き放ってくれたのか?\n\n君は良心の輝かしい手本だ。手間をかけた礼に……", 0xc6ed1aa3, 0x055018ae, 0x0700bb9e, 0x4b975f5c, 0x940134a9, "....." },
  [5283] = { "鎧鍛冶の技", "Armorsmithになるには、以下のアイテムを作りGrumnusに渡さなければなりません：Ornate Mithril Helm 4つ、Ornate Mithril Boots 2つ、Ornate Mithril Breastplate 1つ。", "じゃあ、賢い選択をしたってわけだな。\n\nわしとIronusの爺さんの間にゃ、愛情なんてもんはこれっぽっちもねえ。あの役立たずのおもちゃ職人め、ここらで本物の職人が誰かくらい分かってやがる。\n\n本当に偉大な戦は、優れた守りで勝つもんだ。いざって時に、攻めなんざ何の役にも立ちゃしねえ。\n\nよし、仕事に取りかかるぞ。お前さんはただ、生まれ持った才能があるってことをわしに見せりゃいい。そしたら、お前さんに残ってる不純物を引っこ抜いて、防具鍛冶に鍛え上げてやる。ornate mithrilの作り方は知ってるよな？", "ああ、炉で焼けた肌ほどいいもんはねえ。本当にいい焼け具合の奴は、前掛けの跡を見りゃ分かるってもんよ。", "これで決まりだ、{name}。この後はもう後戻りはできん。今ならまだ玩具職人、いや、武器鍛冶になるのに遅くはないぞ。\n\nお前さんが正しい決断をすると信じておる。", 0xc822f11d, 0x0ba86dff, 0x0d0704a7, 0x8f8d67b9, 0x7c6f74a3, "....." },
  [5284] = { "武器職人の道", "Weaponsmithになるには、以下のアイテムを作りIronusに渡さなければなりません：Moonsteel Broadsword 4つ、Massive Iron Axe 4つ、Heavy Mithril Axe 2つ、Big Black Mace 2つ。", "武器鍛冶になれば、たいていは英雄や冒険者たちが装備を求めてやって来ることになる。仕事量が耐えられないほどになる時もあるが、腰の痛みや灰で痛めた肺を補って余りあるほどの儲けがあるんだ。\n\nそうとも、{name}、金をたんまり持ってるのは武器鍛冶なんだよ！\n\n仲間入りしたいなら、俺に銀貨を2枚かそこら稼がせてくれるってことを見せてもらわないと――いや、つまり、みんなが最高品質の武器を必要とした時に頼られる人物になれる素質があるってことを見せてくれ。さあ仕事にかかれ！", "<Ironusは金貨をきちんと小さな山に積み上げるのに忙しい。>", "やっとかい! 客が待ってんだ。\n\nそいつをこっちへ寄越して、よく聞きな。お前は武器鍛冶としての第一歩を踏み出すんだ。", 0x7b932606, 0x9df7d17f, 0xf74bbea6, 0xc129794c, 0xe8985a2b, ".....", nil, nil, 0xe475450f, nil, nil },
  [5301] = { "鎧鍛冶の技", "Armorsmithになるには、以下のアイテムを作りOkothosに渡さなければなりません：Ornate Mithril Helm 4つ、Ornate Mithril Boots 2つ、Ornate Mithril Breastplate 1つ。", "満足感。それこそが、私が槌と金床から得るものだ。誇り高きHordeのウォリアーが私の鋼に守られているのを見ると、生きるとはどういうことかを思い出す。決してやめる気にはなれぬ中毒だ、{name}。\n\n私がお前にこの満足感を与えることはできぬ。ただ道を示すのみだ。人生のあらゆる営みと同じく、防具鍛冶の道もまた旅なのだ。\n\n選ばれし少数の一人になりたいなら、頼みさえすれば鍛えてやろう。だが、まずは果たさねばならぬ務めがある。", "この息が絶えるその時まで、鋼を打ち続けよう。", "{name}、これは鎧鍛冶としての新たな経歴に踏み出す前の最終段階だ。取りやめたいのなら、これが最後のチャンスだ。そうでないなら、栄光の一生の支度をしな。", 0xc822f11d, 0x03793938, 0xbb62d1b9, 0x989da10a, 0x94984e4c, "....." },
  [5302] = { "武器職人の道", "Weaponsmithになるには、以下のアイテムを作りBorgoshに渡さなければなりません：Moonsteel Broadsword 4つ、Massive Iron Axe 4つ、Heavy Mithril Axe 2つ、Big Black Mace 2つ。", "いつの日か、私は伝説の槌を作り上げる。大族長にふさわしい槌を！\n\nそれが私の生涯の仕事だ、{name}。私の情熱だ。お前には我らの一員に――武器鍛冶になる素質があると見た。その素質を引き出す手助けができるのは私だ。\n\nお前が果たすべきは簡単な務めだけだ。お前ほどの優れた腕を持つ者にとってはな。", "Hordeの栄光のために!", "武器職人としての新たな経歴を踏み出す前の最終段階だ、{name}。取りやめたいのなら、これが最後のチャンスだ。そうでないなら、知識で満たされる支度をしな!", 0x7b932606, 0xf37e0ec1, 0x7ccbe88d, 0xedc97f2e, 0x106d2037, "....." },
  [5305] = { "素敵なSerenity", "Stratholmeへ行き、Crimson Hammersmithを殺して下さい。Crimson Hammersmith's Apronを入手し、Lilithに返して下さい。", "Scarlet Bastionの内部に、甘美なるSerenityが眠っている。Crimson Hammersmithが命をかけてそのレシピを守っている。奴を倒し、エプロンを持ってこい。そうすれば、お前を槌鍛冶として鍛えてやろう。\n\n心得ておけ。一度槌鍛冶の道を選べば、剣鍛冶と斧鍛冶の道はもう選べなくなる。", "あいつの前掛けは! どこにある?", "{name}、あなたが頭をたくさん叩き潰しますように!", 0xbb043493, 0x4bc1109d, 0x17c0f069, 0xd7f14b8a, 0x5d742ffe, "....." },
  [5306] = { "影の女狩人のSnakestone", "Blackrock Spireへ行き、Shadow Hunter Vosh'gajinを討ち取って下さい。Vosh'gajin's Snakestoneを取り戻し、Kilramに返して下さい。", "彼女の美しさに騙されるな、{class}。影の女狩人、Vosh'gajinは危険で狂っている。\n\n<Kilramが顔の傷跡を指差す。>\n\nああ、あいつにやられたんだ――愛のひと撫でだとさ。\n\nついに復讐の時が来た。\n\nVosh'gajinはBlackrock Spireにいる。あいつを倒し、snakestoneを持って戻ってこい。そうすれば斧鍛冶の技を教えてやる。", "伝説によれば、Vosh'gajin's snakestoneを1回使えば、斧は1000年もの間、剃刀のような切れ味を保つそうだ!", "知は力なり!", 0xc974996f, 0x50e0f33e, 0xc050115a, 0x64eab699, 0x048a33e4, "....." },
  [5307] = { "堕落", "StratholmeのBlack Guard Swordsmithを見つけて殺して下さい。Insignia of the Black Guardを取り戻し、Seril Scourgebaneに返して下さい。", "素っ気ない態度を取るのには理由がある。偉大な剣、Corruptionの製法が、Black Guard――Baron Rivendareの精鋭の骸骨部隊に盗まれたのだ。\n\nそうだ、StratholmeのBaron Rivendareだ。\n\n今はBlack Guardの剣鍛冶が、その……不死の身をもってその製法を守っている。\n\n奴を倒してその証を持ち帰れば、剣鍛冶の技を教えてやろう。", "自分に課された任務が何だったか、忘れたのか、{name}?", "剣が常に最善の選択だってことは明らかなはずだよ。", 0x99ec2eb2, 0x7570bf3f, 0x12378b72, 0xfe7aba2d, 0xa91d13af, "....." },
  [5321] = { "眠れる者は目覚めた", "Kerlonian Evershadeを護衛して道を南へ進み、DarkshoreでLiladris Moonriverのところまで連れて行き、彼の鞄を見つける。", "Liladris Moonriverに会いにMaestra's Postへ向かう途中だったのですが、ここで立ち止まって少し昼寝をすることにしたのです。エメラルドの夢から目覚めて以来、ずっと眠くて……\n\n<あくび>\n\nそれに、持ち物がどこにも見当たらないのです！ 探すのを手伝っていただけませんか？\n\nMaestra's Postはここから南、Ashenvaleの道沿いにあると聞いています。私はそちらから来たのです……\n\n最後に、私は眠ってしまうかもしれませんので、起こす必要がある時は私の角笛を使ってください。ここの箱の中にあります。", "Kerlonianはもう着きましたか?", "ああ、Kerlonianが無事にたどり着いて本当に嬉しい！ きっとこのあたりのどこかで寝ているのを見つけることになるんでしょうね？\n\n彼に道を案内してくれてありがとう、{name}。", 0xaa562d09, 0x0598ad83, 0xf9beb9c8, 0x5a42fe8b, 0x57f32af8, "....." },
  [5341] = { "Barov家の財産", "Scholomanceへ赴き、Barov家の財産を取り戻す。この財産は四つの権利書から成る。The Deed to Caer Darrow、The Deed to Brill、The Deed to Tarren Mill、そしてThe Deed to Southshoreだ。任務を終えたらAlexi Barovのところへ戻って下さい。", "Scholomanceの中には、Barov家の財産が眠っている。私、Alexi Barovは、Barov家に残された最後の二人の後継者の一人だ。もう一人は私の弟、Weldonだ。\n\nWeldonという惨めな臆病者は、戦争の間に逃げ出し、そのおかげで人間として無価値な生を保ったのだ。\n\n奴は今、財産を自分のものにしようと権利証を探している。弟より先に権利証を取り戻せ。そうすれば、お前を夢にも思わぬほどの金持ちにしてやろう！", "私の前では頭を垂れよ、{race}。何しろ私は貴族で、お前は一文無しの農民なのだからな。", "見事な働きだ、{race}。さて、我が遺産を確保するとしよう……", 0x3f8c2d6a, 0x778324c3, 0x2ae2fc6c, 0x1af3f7b7, 0xaf1c7186, "....." },
  [5342] = { "最後のBarov", "Allianceの領土であるChillwind Campへ行き、Weldon Barovを暗殺する。彼の首を取り、Alexi Barovのところへ戻って下さい。\n\n注意すること。WeldonはおそらくAllianceのクズどもに厳重に守られている。", "当然、弟がまだ生きている以上、一族の財産の第一受取人が誰なのかについて争いが起きるかもしれん。そんなことがあってはならん。\n\nお前のような卑しいドブネズミなら、ちょっとした冷酷な殺しくらいはためらわないだろうな。\n\n簡単な仕事だ。お前ならやり遂げると期待している。つまり、報酬を受け取りたいのならな。\n\nWeldonは東のChillwind CampでAllianceの保護を受けている。奴を殺し、首を持ってこい。\n\n<Alexiはあくびをする。>\n\nさあ、さっさと行け。", "我が財産を守れ。さすれば分け前にあずかれよう。", "素晴らしい！ これでBarov家の力と財産を持つのは私だけだ！\n\n<Alexiは大きな袋をあなたに投げつける。>\n\n釣りはとっておけ、この汚らわしい獣め。", 0xd587dffb, 0x1d98604b, 0x40697ac8, 0xd7805028, 0xaf7ed43d, "....." },
  [5343] = { "Barov家の財産", "Scholomanceへ赴き、Barov家の財産を取り戻す。この財産は四つの権利書から成る。The Deed to Caer Darrow、The Deed to Brill、The Deed to Tarren Mill、そしてThe Deed to Southshoreだ。任務を終えたらWeldon Barovのところへ戻って下さい。", "我が親愛なる兄、Alexi。奴の命を助けたとは、私はなんと愚かだったことか。私は敵の顔を、アンデッドの一人の顔を見つめながら、奴を生かしておいたのだ。\n\n<Weldonは唾を吐く。>\n\n奴は今、私の遺産を探している。こんなことがあってはならないのだ。\n\nあの下劣な下郎がその骨ばった手でつかむ前に、我が一族の権利証を見つけてくれ。そうすれば莫大な富で報いてやろう。権利証はScholomanceの廃墟の中にある。急げ！", "私の未来を確かなものにせよ。そうすれば、私もお前の未来を約束しよう。", "お前に頼まねばならない務めが、あと1つだけある、{name}。", 0x3f8c2d6a, 0x62fcd15e, 0xa8d67690, 0xfce3d6b8, 0x4579e737, "....." },
  [5344] = { "最後のBarov", "Hordeの領土であるBulwarkへ行き、Alexi Barovを暗殺する。彼の首を取り、Weldon Barovのところへ戻って下さい。\n\n注意すること。AlexiはおそらくHordeのクズどもに厳重に守られている。", "権利証を取り戻した今、やるべきことはあと一つしかない。Alexiを殺さねばならん。奴が死ねば、悪辣な傭兵の一団に首を狙われる心配をする必要は二度となくなる。\n\n簡単な仕事だ。AlexiはHordeの保護の下、Bulwarkに隠れている。\n\nいや、ただ歩み寄って奴を殺せと言っているのではない。奴の首が欲しいのだ！どうやって手に入れるか……まあ、そこはお前次第だ。そういう振る舞いは、私のような高貴な生まれの者のすることではないのでな。", "報酬は欲しいのだろう?", "栄光ある日だ！ ついにBarov家の汚点は消え去り、私の財産は安泰だ！\n\nこれを受け取って、私の前から消えろ、下民め。", 0xd587dffb, 0xc4780c72, 0x91978771, 0xcd631cdc, 0xf688396f, "....." },
  [5361] = { "家系", "DesolaceのGhost Walker PostにいるNataka LonghornにCliffwatcher Longhorn Reportを届けて下さい。", "DesolaceのGhost Walker Postに、私の兄Natakaが駐留している。君に頼みたいことがある……この報告書を彼に届けてくれるかい? 最後に手紙を書いてから一年が過ぎてしまった。それからcentaurたちに変わった活動があったから、彼に知らせておくべきなんだ。\n\nCrossroadsの北、Stonetalon Mountainへ行って、西のCharred Valeへ向かうんだ。そこから、南へ向かってDesolaceに入ってくれ。Ghost Walker Postへ向かって南に続く道を見つけられると思う。", "何か知らせはあるか、{class}! ああ、兄弟からの伝言だと? ならば、その報告書を渡してくれ!", "弟とどんな関係があるか知らないが、君を信頼しているようだな、{class}。\n\n私はNataka Longhorn。Ghost Walker Postへ君を歓迎したい。我々は{class}の助けを多く必要としている! 他の者とも話してくれ。ここには君を必要とする者がいよう。", 0x75bbe09a, 0x851bfa05, 0x91bf7cbe, 0xde674e8b, 0xffb232f7, "....." },
  [5381] = { "Hand of Iruxos", "Thunder Axe FortressからDemon Boxを取り戻し、Demon Pickと一緒にShadowprey VillageのTaiga Wisemaneのところへ持って行って下さい。", "Burning BladeはDemon Boxを所持している。その中には強力なHand of Iruxosが収められている。Burning BladeはそれでMannoroc Covenに悪魔の門を開いているのだ。この世界に流れ込む悪魔の波を止めねばならん、{name}！\n\nこのdemon pickをThunder Axe Fortressの赤い水晶に使い、Demon Boxへの道を開け。", "{name}、Demon Boxは持っているか?", "ああ、Demon Boxか。それを我に渡すがよい、{class}。我が開けてやろう……そして、Hand of Iruxosをそなたに明かそう。", 0xd85b8727, 0xbcfb110b, 0x04495abb, 0x3e8e7805, 0x7e8cdab2, "....." },
  [5382] = { "Doctor Theolen Krastinov, the Butcher", "Scholomanceの中でDoctor Theolen Krastinovを見つけ出して倒し、Remains of Eva SarkhoffとRemains of Lucien Sarkhoffを燃やす。任務を終えたらEva Sarkhoffのところへ戻って下さい。", "Krastinovは何千もの者の死に責任がある。奴は罰せられねばならない。正義が下されねばならないのだ。\n\n奴を見つけ出し、数え切れぬ罪なき者たちに奴が与えた苦しみを、奴自身に味わわせてやれ。奴を滅ぼしたら、私たちの亡骸を焼いてくれ。灰にしてくれ、{name}。", "Butcherを止めなければならない!", "魂が癒えていくのを感じるわ、{name}。あなたは夫と私のために大きな働きをしてくれた。でも、まだやるべきことがあるはずよ。", 0xd336bb57, 0x9d7ac22d, 0x56eccba7, 0x2431a358, 0x810a97d6, "....." },
  [5383] = { "Krastinov's Bag of Horrors", "Bag of HorrorsをCaer DarrowのEva Sarkhoffのところへ持って行って下さい。", "袋を開けると、さまざまな拷問器具が出てきた。その道具類の中で、奇妙な物があなたの目を引く。血の入った小瓶だ――触れるとまだ温かい。\n\nSarkhoff家の者たちなら、この発見に興味を持つかもしれない。", nil, nil, 0xc11cac70, 0xdaf3716e, 0x4c9e8ccd, nil, nil, "...mm" },
  [5384] = { "Kirtonos the Herald", "Blood of Innocentsを持ってScholomanceへ戻る。ポーチを見つけ、火鉢にBlood of Innocentsを置く。Kirtonosがあなたの魂をむさぼりにやって来る。\n\n勇敢に戦い、一歩も引かないこと！Kirtonosを倒し、Eva Sarkhoffのところへ戻って下さい。", "これよ、{name}。\n\n<Evaは袋の中の小瓶を指さす。>\n\nblood of innocents。最も清らかな血で、Krastinovの主をなだめるために使われていたの。\n\nこの血でこそ、Kirtonosを呼び出すことができる。ならばこそ、この血でKirtonosを滅ぼさなければならないのよ。\n\n血をポーチへ持って行って。火鉢の上に置くの。Kirtonosは来るわ――抗うことはできないのよ。奴が現れたら、千の罪なき死の怒りと憤りを奴に解き放って。\n\nもし成功したら、私たちの感謝以上のものを得られるわ。", "気をつけろ、Kirtonosは歴戦の闘士だ。", "Kirtonosの死によって、Scholomanceの恐ろしい物語の一つの章が幕を閉じます。けれど、まだやるべきことがあります。ここにいる他の者たちも、今やあなたの勇敢な行いを知っています。これを受け取ってください、{name}。これは私たち自身の本質の欠片です。これがあれば、Caer Darrowの他の迷える魂たちと話すことができるでしょう。", 0x85ddd998, 0xf02984ed, 0x63de25cc, 0xfb2dedfa, 0x1e8a60da, "....." },
  [5385] = { "Remains of Trey Lightforge", "Remains of Trey LightforgeをFelwoodのJessir Moonbowのところへ返して下さい。", "あなたは袋を慎重に拾い上げ、FelwoodとAshenvaleの境にいるJessir Moonbowのもとへ戻る準備をする。遺骸を彼の友人たちに渡せば、あのパラディンもしかるべき敬意をもって弔われることだろう。", "Jaedenarではどうだった、{name}?", "やりましたね！ Eluneと、あなたが崇めるいかなる力にも讃えあれ、{name}。あなたは今日、名誉ある気高いことを成し遂げました。Arko'narinはきっと喜ぶでしょう。あなたが時間をかけて彼女を救ってくれただけでなく、彼女の親友の1人を苦しめた怪物まで倒してくれたのですから。\n\nもっと何かしてあげられたらいいのですが、どうか、これを受け取ってください。", 0x90368ba7, 0x6d8aa087, 0x124f7288, 0xce9d5820, 0x62e2ed22, "....." },
  [5386] = { "本日の獲物", "Shadowprey VillageのJinar'Zillenと話し、Nataka LonghornにBloodbelly fishを$N1匹持って行って下さい。", "ここGhost Walker Postでは、焼き魚の匂いがずっとご無沙汰だ。Shadowprey Villageのトロールたちは魚を獲るのが一番うまい……だが残念なことに、centaurの動きが活発なせいで、トロールのところまで旅をする暇がほとんどないのだ。ふむ……\n\n頼みを聞いて、Shadowprey Villageまで行ってくれ。地元の釣り人Jinar'Zillenと話して、私の好物のBloodbelly fishを持ち帰ってほしい。ここから南への道を行けば、西のトロールの村に着く。", "揚げたBloodbelly fishのことを考えると、蹄がうずいて、よだれが出てくるよ……持ってないかい?", "君は救い主だ、{name}！ このBloodbellyの魚は、生で食べてもいいくらい美味そうだ。\n\n<Natakaはよだれを垂らし始める。>\n\nさあ、この魚の代金として、これらの品から1つ選んでくれ。", 0x08798148, 0xbb9d538f, 0x7d13a9e3, 0x565d4e36, 0xf4003637, "....." },
  [5401] = { "Argent Dawn Commission", nil, nil, nil, "Argent Dawnのために悪と戦う者は皆、我らの任命の証を身につけねばならない。それを身につけていれば、我らの補給係が提供する報酬を受け取る権利が得られる。\n\n任命を受けている間は、倒したScourgeからScourgestoneを手に入れられるようになる。これは奴らが時折持っている徽章だ。この徽章を集めて私のもとへ持ってくるのだ。一揃い納めるごとに、我らの英雄の証、Argent Dawn Valor Tokenを受け取れる。\n\n運命を掴め、{class}。今日こそ戦いに加わるのだ！", 0x1122fda4, nil, nil, nil, 0x33c0d9c1, ".mmm." },
  [5405] = { "Argent Dawn Commission", nil, nil, nil, "Argent Dawnのために悪と戦う者は皆、我らの任命の証を身につけねばならない。それを身につけていれば、我らの補給係が提供する報酬を受け取る権利が得られる。\n\n任命を受けている間は、倒したScourgeからScourgestoneを手に入れられるようになる。これは奴らが時折持っている徽章だ。この徽章を集めて私のもとへ持ってくるのだ。一揃い納めるごとに、我らの英雄の証、Argent Dawn Valor Tokenを受け取れる。\n\n運命を掴め、{class}。今日こそ戦いに加わるのだ！", 0x1122fda4, nil, nil, nil, 0x33c0d9c1, ".mmm." },
  [5441] = { "サボりは許さん", "居眠りしているLazy PeonをForeman's Blackjackでたたき起こしてください。Peonを５人起こしたら、Valley of TrialsにいるForeman Thazz'rilにForeman's Blackjackを返してください。", "くそったれ！Peonたちはこの谷の木から木材を採るためにせっせと働いている。しかし奴らは目を離すとすぐ昼寝をしやがる！誰かにしりを突っついてもらわなければならん。\n\nあんたは適任の{race}のようだな。 さてこのBlackjackを持って、仕事をサボって寝ているPeonを見つけたらぶったたいてくれ。一発食らえばまた働き出すだろう。すんだらBlackjackを返してくれ。\n\n怠け者どもめ・・。", "役立たずの怠け者どもめ……\n\nん? 俺のblackjackは持ってきたか? 仕事中に寝てるpeonは捕まえたか?!", "よし、よし。奴らにはいい薬になっただろう。ありがとよ。", 0x066b4dc8, 0x0e9a3950, 0x5204e085, 0x7ba6faf0, 0x403f028b, "....." },
  [5461] = { "人間Ras Frostwhisper", "Arathi Highlandsに向かい、Stromgardeの廃墟へ行って下さい。StromgardeでKeepsake of Remembranceを探して下さい。アイテムを見つけたら、Magistrate Mardukeのところへ持ち帰って下さい。", "アンデッドは、生者が死を恐れるのと同じように生を恐れる。知性あるアンデッドが、変わり果てた後に生前の名残をすべて破壊してしまうのは珍しいことではない。\n\n困ったことに、Ras Frostwhisperを定命の者に戻せる遺物を作るには、彼が生者の間で過ごした年月の形見が必要だ。\n\n廃墟となったStromgardeの街――Frostwhisperの故郷へ赴き、そのような品を探さねばならない。幸運を祈る、{name}。", "keepsake of remembranceは珍しい掘り出し物だ、{name}。", "そのような品が本当に存在しうるのか、私は疑っていた。これは間違いなく途方もない好機を開くものだ。無駄にするわけにはいかん。\n\n心して備えよ、{name}。これから頼もうとしていることは、お前を地獄の底へと連れて行くものだからだ。", 0x725cb6ce, 0xa0f64578, 0xf5fbe9d1, 0xf96f05b9, 0x2a862c05, "....." },
  [5462] = { "死の直前のRas Frostwhisper", "Eastern PlaguelandsのLight's Hopeへ向かい、Leonid Barthalomew the Reveredを探して下さい。彼にKeepsake of Remembranceを見せ、突き止めたことをすべて伝えて下さい。", "穢れた土の上で、形見を同調させねばならない。\n\nStratholmeこそFrostwhisperがLich Kingに屈した場所だと噂されている。その血塗られた地で、彼は自らの命を――自ら進んで、目的をもって――差し出し、不死なる者の一人となった。\n\n見つけねばならないのはその地だ。\n\nある者がいる。Scourgeを離反したアンデッドで、Banshee Queenによって解放されたが、Argent Dawnの大義に忠実な者だ。彼を探せ。Leonid Barthalomew the Revered。彼なら詳しく知っているかもしれない。Light's Hopeを探すのだ、{name}。", "答えを知りたくない問いは、口にしないことだ。", "<Leonidが形見をじっくりと検める。>\n\nお前の抱える難題は、二度と浮かび上がってほしくないと願っていた記憶を呼び起こす。", 0x1d8e2a3d, 0x9ac8a12d, 0xd52673b1, 0xfc4fa87f, 0x68a55fa4, "....." },
  [5463] = { "Menethil's Gift", "Stratholmeへ向かいMenethil's Giftを見つけて下さい。不浄な地面にKeepsake of Remembranceを置いて下さい。", "私は見ていた。人間、Ras FrostwhisperがLich Kingに不死の魂を誓うのを。彼は短剣を自らの喉に当て、笑みを浮かべて耳から耳まで切り裂いた。その体は五芒星の内側に崩れ落ちた。Lich Kingは倒れたメイジの上に立ち、ただ一つの動作で、リッチ、Ras Frostwhisperが生まれたのだ。\n\n<Leonidは地面を見つめ、それからあなたを見上げる。>\n\nそうだ、{race}、覚えている。あなたが求めるものには名がある――Menethil's Gift。Lich Kingに祝福された地――Scourgeにとっての聖地だ。", "Menethil's Giftの周りは、ひときわ寒い。", "穢された土の上に形見を置いた。", 0x07faaca7, 0x12bcf3f2, 0x04b9599d, 0xddaadd82, 0x8a0ae085, "....." },
  [5464] = { "Menethil's Gift", "Soulbound KeepsakeをEastern PlaguelandsのLeonid Barthalomewのところへ持って行って下さい。", "死者の魂は生前の人生を象徴するものに纏わり付き、魂と結びついた形見へと変えた。あなたはそれを拾い上げ、鞄にしまった。", "<Leonidは身震いする。>", "魂が形見に纏わり付いたように、魂はRas Frostwhisperの肉体にも纏わり付くだろう。", 0x07faaca7, 0x495cca65, 0x05eeb523, 0xbb86ab9a, 0xca81a204, "....." },
  [5465] = { "Soulbound Keepsake", "Caer DarrowのMagistrate Mardukeのところへ戻り、Soulbound Keepsakeを見せて下さい。", "形見をもってMardukeのところへ戻れ、{name}。使い方を教えてくれるだろう。", "不可能を成し遂げたのか?", "お前も、また一人の不運な霊として私に加わるものと確信していたのだがな。", 0x602959cb, 0x94d112db, 0x42e159c7, 0x98d8ddc5, 0x7b4d9f54, "....." },
  [5466] = { "リッチRas Frostwhisper", "ScholomanceにいるRas Frostwhisperを見つけ、Soulbound Keepsakeを彼の前で使って下さい。彼を人間へ戻すことに成功したら、彼を倒してHuman Head of Ras Frostwhisperを手に入れて下さい。その首はMagistrate Mardukeのところへ持ち帰って下さい。", "残る務めはただ一つだ、{name}。リッチ、Ras Frostwhisperとその隠れ家で対決せよ。\n\n形見の力を奴に向けて使え――手を緩めるな！ もがく獣が必ずや浴びせてくる攻撃に耐え抜け。痛みに屈するな！\n\n儀式が終われば、Rasは再び定命の者となる。その時こそ奴を討たねばならない。奴を打ち倒し、その人間の頭を持ち帰れ。", "お前は10000もの彷徨える魂の重荷を背負っている、{name}。", "一万の魂が一斉に叫んでいるぞ、{name}! 君はScourgeとその支配者たちに決定的な一撃を見舞ったんだ。", 0xe16ff4fd, 0xf3ab1755, 0x8037676e, 0xf7db9910, 0x202c3397, "....." },
  [5481] = { "Gordoの任務", "Gloom Weedを３つ集めてBrill graveyardにいるJunior Apothecary Hollandに届けてください。", "わが主人は草を求めている。我らの大きな手は採集にはむいていない。手伝ってくれれば危害は与えない。我らはgloom weedを求めている。多くの草が道のそばやあたり一帯に生えている。\n\ngloom weedを手に入れたなら、Brill graveyardにいるMaster Hollandに渡してくれ。", "あの役立たずのabominationはどこだ? 必要なものを持ってきたか、さもなくばさっさと外へ出て探してこい。", "何だこれは？Gloom weedだと？！gloom weedなど要らん！あの頭の空っぽな肉の塊は、外でヒナギクなんぞ摘みながら、お前のようなカモを奥方のみぞ知るほど大勢たぶらかして同じことをさせているのだ。悪く思うなよ。\n\nまあいい、お前はもうここにいる。それが肝心だ。あの化け物に説明してやる気などさらさらないから、お前が私の本当に必要なものを集めてくるというのはどうだ……doom weedをな！", 0x96395a4e, 0xb936c9b6, 0x6ed41602, 0x7b54f2f7, 0x6ac66def, "....." },
  [5482] = { "Doom Weed", "Doom Weedを10個集めてJunior Apothecary Hollandのもとへ運んでください。", "困ったことだよ、{name}。違うものばかり集めてくる！私のほしいものを集めてくれればそれに値するものができるんだが。十分なDoom Weedをとって来てくれたら、それなりの礼はするよ。\n\nBrill graveyardの北にある大きな墓の近くに生えているということはわかっている。急げ、辺りにいるgnollどもにも気をつけろ。", "いい知らせなんだろうな。必要なdoom weedは全部持ってきたんだろうな?", "ああ、私のDoom Weed。すばらしい！\n\n<Junior Apothecary Hollandは欲深そうに手をこすり合わせた。>\n\nこれはとても役立つぞ。お前は私に、あー、Ladyに、立派な奉仕をしてくれたな、{name}。約束したとおり、これはお礼だ。", 0xba531ee7, 0x953d45bb, 0xba6bedd2, 0xee8731ae, 0xb65d1bca, "....." },
  [5501] = { "骨収集家", "Kodo Graveyard から Kodo Bone を10個、Kormek's Hut にいる Bibbly F'utzbuckle に持ってくる。", "いいか、ここは金のなる木だ――金脈なんだよ！Kodo Boneは世界を永遠に変える……家具や楽器、果ては爆薬まで、そいつで作ってる客がいるんだ。\n\n隊商がやって来て私のKodo Boneを引き取り、Shadowprey Villageで売ってくれるんだ。ここから南のkodoの墓場まで行ってKodo Boneを10本持ってきてくれたら、お返しに何かやるよ。どうだ、乗るか？", "骨は持ってきたか? キャラバンがもうすぐ来ちまう。自己最高記録まで、あとたった10本のkodo bonesなんだ。自己最高記録だぞ、いいか!", "おー、やったあ! 骨だ!うちの連中が「Goblin'preneur」の表紙を飾るオレの顔を目にするのが待ち遠しいぜ。オレは世界一金持ちになるんだ……体育の先公には大物になれないって言われたけどな。", 0xa1177fd1, 0x6c4f8089, 0x73788e03, 0xf2c18490, 0xf47c7c14, "....." },
  [5502] = { "Horde の守り人", "Valley of HonorにいるOrphan Matron BattlewailにOrcish Orphan Whistleを渡し、預かっている子をOrgrimmarの孤児院へ帰して下さい。", "本当に優しくしてくれたね、{name}。Children's Weekにこんなに楽しく過ごせるなんて、夢にも思わなかったよ。ありがとう。自分に起きたことで悲しんだりしない――両親はいつも、どんな嫌なことが起きても乗り越えろって言ってた。英雄になるんだ……あなたみたいな。\n\nこんなこと言うのは悲しいけど、もう家に帰る時間なんだ。戻ろう。寮母さんに、あなたがどんなにすごい人か話してあげるね！", "また会えて嬉しいですよ、{name}。Children's Weekの間、引き受けてくださったお務めは果たしましたか？", "精霊があなたを祝福しますように、{name}。あなたはGrunthのために、大抵の人が考えもしないほどのことをしてくれました。ありがとう。あなたこそ、Hordeの英雄というものの鑑です。\n\nどうか、時間が取れたら、また私たちに会いに来てください。Grunthもきっと喜びますし、私もうれしいです。\n\nGrunthはあなたと本当に楽しく過ごしたんですよ、{name}。あの子は自分のことを覚えていてもらうために、お気に入りのペットを一匹あなたに贈りたいそうです。", 0xfc045e42, 0x994306c0, 0xe237b3e0, 0xfd180aa5, 0x56ea92c2, "....." },
  [5503] = { "Argent Dawn Commission", nil, nil, nil, "Argent Dawnのために悪と戦う者は皆、我らの任命の証を身に着けねばならない。それを身に着けることで、我らの補給係が提供する報酬を受け取る権利が得られる。\n\n任命を受けている間は、倒したScourgeからScourgestonesを手に入れることができる。これは奴らが時折持っている記章だ。この記章を集めて私のもとへ持ってきてくれ。一揃い納めるごとに、我らの英雄の証、Argent Dawn Valor Tokenを受け取れる。\n\n運命を掴め、{class}。今日こそ戦いに加わるのだ!", 0x1122fda4, nil, nil, nil, 0x754f7807, ".mmm." },
  [5504] = { "Mantles of the Dawn", "Argent Dawn Valor Tokensを$N1個、Western PlaguelandsのBulwarkにいるQuartermaster Hasanaのところへ持って行って下さい。", "あなたのArgent Dawnへの奉仕は称賛に値します、{name}。あなたは私たちの間で真に崇敬されています。Dawnで最も価値ある品の一つ――魔法耐性のマント――をあなたが購入できるようにする許可を、私は得ています。\n\n今お使いの肩防具にマントを施せば、五つの可能な方法のいずれかで、魔法の力に対する耐性が高まります。私たちの大義への変わらぬ献身の証として、これらのマントを利用するには、私たちのvalor tokenを少なくとも十個いただきます。", "ああ、高貴なる{class}よ! 頼んでおいたvalor tokensは持ってきてくれたか? 渡してくれれば、我々のさまざまなマントを購入できるようにしよう。", "見事だ。Dawnへの君の貢献は確かに記録したぞ、{name}。これを成し遂げた以上、喜んで我らの肩当てを購入できるようにしよう。我々との現在の立場を保っている限り、これらの肩当てはArgent Dawnの公認補給係の誰からでも購入できる。\n\nDawnのために、我が兄弟よ!", 0xb4b72c15, 0x9f3bcc9c, 0x2745a134, 0xaa8f1881, 0x152a39f1, "....." },
  [5505] = { "Scholomanceの鍵", nil, nil, nil, "さて、これだ、{name}。完成したSkeleton Keyだ。この鍵があればScholomanceの内部に入れるはずだと、私は確信している。とはいえ、本当に使えるか確かめる方法は1つしかない。すぐにでも試してみることだ。\n\n幸運を祈る、偉大なる英雄よ。これからも闇に光をもたらし続けてくれ!", 0x5fcf7b72, nil, nil, nil, 0x779e067f, ".mmm." },
  [5507] = { "Mantles of the Dawn", "Argent Dawn Valor Tokensを$N1個、Western PlaguelandsのChillwind CampにいるQuartermaster Lightsparkのところへ持って行って下さい。", "あなたのArgent Dawnへの奉仕は称賛に値します、{name}。あなたは私たちの間で真に崇敬されています。Dawnで最も価値ある品の一つ――魔法耐性のマント――をあなたが購入できるようにする許可を、私は得ています。\n\n今お使いの肩防具にマントを施せば、五つの可能な方法のいずれかで、魔法の力に対する耐性が高まります。私たちの大義への変わらぬ献身の証として、これらのマントを利用するには、私たちのvalor tokenを少なくとも十個いただきます。", "ああ、高貴なる{class}よ! 頼んでおいたvalor tokensは持ってきてくれたか? 渡してくれれば、我々のさまざまなマントを購入できるようにしよう。", "見事だ。Dawnへの君の貢献は確かに記録したぞ、{name}。これを成し遂げた以上、喜んで我らの肩当てを購入できるようにしよう。我々との現在の立場を保っている限り、これらの肩当てはArgent Dawnの公認補給係の誰からでも購入できる。\n\nDawnのために、我が兄弟よ!", 0xb4b72c15, 0xe33d0227, 0x2745a134, 0xaa8f1881, 0x152a39f1, "....." },
  [5511] = { "Scholomanceの鍵", nil, nil, nil, "さて、これだ、{name}。完成したSkeleton Keyだ。この鍵があればScholomanceの内部に入れるはずだと、私は確信している。とはいえ、本当に使えるか確かめる方法は1つしかない。すぐにでも試してみることだ。\n\n幸運を祈る、偉大なる英雄よ。Scholomanceを蹂躙する中で、その勝利がこれからも君に名声と力をもたらさんことを!", 0x5fcf7b72, nil, nil, nil, 0x1e97a381, ".mmm." },
  [5513] = { "Mantles of the Dawn", "Argent Dawn Valor Tokensを$N1個、Eastern PlaguelandsのLight's Hope ChapelにいるQuartermaster Breechlockのところへ持って行って下さい。", "あなたのArgent Dawnへの奉仕は称賛に値します、{name}。あなたは私たちの間で真に崇敬されています。Dawnで最も価値ある品の一つ――魔法耐性のマント――をあなたが購入できるようにする許可を、私は得ています。\n\n今お使いの肩防具にマントを施せば、五つの可能な方法のいずれかで、魔法の力に対する耐性が高まります。私たちの大義への変わらぬ献身の証として、これらのマントを利用するには、私たちのvalor tokenを少なくとも十個いただきます。", "ああ、高貴なる{class}よ! 頼んでおいたvalor tokensは持ってきてくれたか? 渡してくれれば、我々のさまざまなマントを購入できるようにしよう。", "見事だ。Dawnへの君の貢献は確かに記録したぞ、{name}。これを成し遂げた以上、喜んで我らの肩当てを購入できるようにしよう。我々との現在の立場を保っている限り、これらの肩当てはArgent Dawnの公認補給係の誰からでも購入できる。\n\nDawnのために、我が兄弟よ!", 0xb4b72c15, 0x9e8f7768, 0x2745a134, 0xaa8f1881, 0x152a39f1, "....." },
  [5514] = { "鋳型(Mold)と韻を踏むのは……", "GadgetzanのKrinkle GoodsteelにImbued Skeletal Fragmentsと金貨15枚を渡して下さい。", "話をつけなきゃならないゴブリンはKrinkle Goodsteelだ。Tanarisの砂漠にあるGadgetzanで、一番高い値をつけた相手に腕を売っている。我々に必要な鋳型を作れるのはたぶん彼だけだろうが、彼の仕事は安くはない。そこで今回は、彼が請求する料金がいくらであろうと、君に懐を痛めて払ってもらいたい。\n\n私は薬剤師であって、銀行家ではない。金がそこらに転がっていたら、そもそもこんなところにはいないさ。\n\nまた言わなくていいことを口に出してしまったようだ。おっと。\n\nGadgetzanが君を待っているぞ! 幸運を!", "ああ、あんたが誰かも、なぜここに来たかも分かってる。あんたが着く前に、Dithersから知らせがあったんでね。さっそく本題の取引といこうじゃないか。\n\nskeleton keyに使える鋳型がある。だがタダじゃない。金貨15枚、前払い、値切りはなしだ。skeletal fragmentsは俺が鋳型に詰めてやるし、鍛冶の知識がなくても鍵の軸を鍛えられるよう、やり方も教えてやる……しかも全部無料でな。\n\n傭兵がお得な取引をしないなんて、誰が言った!", "Dithersが、お前なら品を届けると言っていたが、本当に届けたな! 取引は取引だ。そのfragmentsを鋳型に詰めてやろう。\n\nDithersはもう魔力を込めたのか? 上出来だ……そうでなければ、Bulwarkまで長い道のりを戻ることになっていたぞ。", 0x64e41d76, 0x98c261fc, 0xca78de6e, 0xaa1c6644, 0x191c6e4a, "....." },
  [5515] = { "Krastinov's Bag of Horrors", "ScholomanceでJandice Barovを見つけて倒す。その死体からKrastinov's Bag of Horrorsを回収する。その袋をEva Sarkhoffのところへ返して下さい。", "私たちの心から大きな重荷が取り除かれました、{name}。ですが、あなたの務めはまだ終わっていません。Krastinovの主、Kirtonosがまだ生きているのです。\n\nですが、Kirtonosと対峙する前に、まず彼を呼び出す方法を確保しなければなりません。\n\nJandice Barovが、Krastinovの手からKirtonosのもとへblood of innocentsを管理しているといわれています。\n\nScholomanceの沈んだ地下墓地で彼女を見つけ、打ち倒してください。見つけた手がかりは何でも持ち帰ってください。", "<Evaの姿が、ぼやけたりはっきりしたりを繰り返す。>", "bag of horrorsだ!", 0xc11cac70, 0x0fb10777, 0x0ffd8fa0, 0xe847782c, 0xe4f2af76, "....." },
  [5517] = { "Chromatic Mantle of the Dawn", "Argent Dawn Valor Tokensを$N1個、Eastern PlaguelandsのLight's Hope ChapelにいるQuartermaster Breechlockのところへ持って行って下さい。", "同志{name}よ――Argent Dawnのためのあなたの功績は、とても容易には数えきれないほど多い。ふさわしい賛辞として、我々の特別なChromatic Mantles of the Dawnの一つを譲ろう――着用者を、抵抗しうるあらゆる形の魔法から同時に守る品だ。Chromatic Mantles of the Dawnは、Dawnの英雄の中でも最も強き者だけのために取っておかれているのだ！\n\n賛辞の証としてvalor tokenを二十五個持ってきてくれれば、我々のマントの中でも最高の品を渡そう。", "ごきげんよう、偉大なるプリーストよ! 頼んでおいたvalor tokensは持ってきてくれたか? 渡してくれれば、君専用のChromatic Mantle of the Dawnを授けよう。", "実に見事だ、{name}。Chromatic Mantle of the Dawnは今や君のものだ!\n\nArgent DawnとのExaltedの評価を保っている限り、追加のChromatic Mantlesを購入できる。Dawnのどの補給係からでも、すぐに手に入れられるようになる。", 0x89e9f7f2, 0x9e8f7768, 0xedd992a2, 0x9947aee6, 0xbeb472bb, ".....", nil, nil, 0x4e45f79f, nil, nil },
  [5518] = { "Gordok Ogre Suit", "Bolt of Runecloth 4本・Rugged Leather 8枚・Rune Thread 2つ・Ogre TanninをKnot Thimblejackに渡して下さい。彼は今、Dire MaulのGordok wingの中に繋がれています。", "このゴミ溜めの王と戦うつもりなら――まあそうするに決まってると思うけど――Captain Kromcrushを突破しなきゃならない。もちろん、殺して突破することもできる。でも実は生かしておいたほうがいいかもしれないよ。\n\nどうやってかって？ ここに来てから、こいつら間抜けどもを騙せる程度には持つogreスーツの作り方が分かった気がするんだ。問題は持続時間だけ――せいぜい10分だ。必要なものを持ってきてくれたら、1着作ってあげるよ。どこにも行かないからさ……", "服を作るのに必要なものの中で、Ogre Tanninがたぶん一番見つけにくいね。上の階にいくらかあると思うんだけど? はっきりとは言えないよ、この鉄球付きの鎖のせいで、思うように動けないからね……\n\nとにかく、必要なものを持ってきてよ。そうしたらogre suitをさっと作ってあげる。Captain Kromcrushも、君を自分の部下だと思い込むはずさ。", "ああ、これなら上手くいく。ここをちょっと滑らせて、ここに押し込んで……へへ、こいつはばっちりうまくいくぞ! <鎖につながれたゴブリンの顔に、満面の笑みが浮かぶ。>\n\nほらよ、これで準備万端だ。覚えておけ、こいつは世界一しっかりした作りの品じゃない。バラバラになるまでに使えるのは十分間だけで、それを過ぎたら誰もだませやしないぞ! あいつに近づく直前に使ってみな。それから覚えておけよ……あいつにお前「だけ」が味方だと思わせるだけで、お前の仲間たちはそうはいかないからな!", 0x7c7bbee3, 0xb8de906e, 0xf4901290, 0xb459423a, 0xb1e0632f, "....." },
  [5521] = { "Chromatic Mantle of the Dawn", "Argent Dawn Valor Tokensを$N1個、Western PlaguelandsのChillwind CampにいるQuartermaster Lightsparkのところへ持って行って下さい。", "同志{name}よ――Argent Dawnのためのあなたの功績は、とても容易には数えきれないほど多い。ふさわしい賛辞として、我々の特別なChromatic Mantles of the Dawnの一つを譲ろう――着用者を、抵抗しうるあらゆる形の魔法から同時に守る品だ。Chromatic Mantles of the Dawnは、Dawnの英雄の中でも最も強き者だけのために取っておかれているのだ！\n\n賛辞の証としてvalor tokenを二十五個持ってきてくれれば、我々のマントの中でも最高の品を渡そう。", "ごきげんよう、偉大なる{class}よ! 頼んでおいたvalor tokensは持ってきてくれたか? 渡してくれれば、君専用のChromatic Mantle of the Dawnを授けよう。", "実に見事だ、{name}。Chromatic Mantle of the Dawnは今や君のものだ!\n\nArgent DawnとのExaltedの評価を保っている限り、追加のChromatic Mantlesを購入できる。Dawnのどの補給係からでも、すぐに手に入れられるようになる。", 0x89e9f7f2, 0xe33d0227, 0xedd992a2, 0xe017510a, 0xbeb472bb, ".....", nil, nil, 0x4e45f79f, nil, nil },
  [5522] = { "Leonid Barthalomew", "Frozen EggsをEastern PlaguelandsのLeonid Barthalomewのところへ持って行って下さい。", "師匠のVectusから伝言を受け取ったんだ。いや、本当はVectusからの伝言じゃなかった……Leonid Barthalomewという者からだった。Leonidのことは知らないけど、彼は師匠を知っていた。師匠が許さない限り、誰も師匠のことを知ることはないのに。\n\nLeonidが言うには、Vectusがドラゴンの卵を欲しがっているそうだ。Eastern PlaguelandsのLight's Hope Chapelにいる彼のところへ、君に届けてほしいんだって。\n\n傷つくなあ！なんで君なんだ？Vectusは僕を信用してないのか？まあ、いいや……卵を持って行って、僕は師匠の命令通りにしたってLeonidに伝えてくれ。", "Blackrock Spireで悪さをしているのはお前だな? 頼んだものは持ってきたか?", "ああ、よくやってくれました。あなたは自分がどんな邪悪な力のために働いていたのかを知りません。しかし今こそ真実を知ることになるでしょう。そして恐れることはありません。私はあの主人の僕ではないのです。私はLeonid Barthalomew、Argent Dawnの同胞からは「the Revered」と呼ばれている者です。\n\n私はTinkeeを騙して、あなたとdragon eggsを私のもとへ送らせたのです。そしてその策略が成功したのは幸いでした。もしこのeggsが本来の届け先に届いていたら、強大な力が敵の手に落ちていたでしょうから。", 0x14b273d7, 0x88c9c397, 0xffad81a7, 0x18b4c1b5, 0x080f2e56, "....." },
  [5524] = { "Chromatic Mantle of the Dawn", "Argent Dawn Valor Tokensを$N1個、Western PlaguelandsのBulwarkにいるQuartermaster Hasanaのところへ持って行って下さい。", "同志{name}よ――Argent Dawnのためのあなたの功績は、とても容易には数えきれないほど多い。ふさわしい賛辞として、我々の特別なChromatic Mantles of the Dawnの一つを譲ろう――着用者を、抵抗しうるあらゆる形の魔法から同時に守る品だ。Chromatic Mantles of the Dawnは、Dawnの英雄の中でも最も強き者だけのために取っておかれているのだ！\n\n賛辞の証としてvalor tokenを二十五個持ってきてくれれば、我々のマントの中でも最高の品を渡そう。", "ごきげんよう、偉大なる{class}よ! 頼んでおいたvalor tokensは持ってきてくれたか? 渡してくれれば、君専用のChromatic Mantle of the Dawnを授けよう。", "実に見事だ、{name}。Chromatic Mantle of the Dawnは今や君のものだ!\n\nArgent DawnとのExaltedの評価を保っている限り、追加のChromatic Mantlesを購入できる。Dawnのどの補給係からでも、すぐに手に入れられるようになる。", 0x89e9f7f2, 0x9f3bcc9c, 0xedd992a2, 0xe017510a, 0xbeb472bb, ".....", nil, nil, 0x4e45f79f, nil, nil },
  [5525] = { "Knotを解放せよ!", nil, nil, "Gordok Shackle Keyって呼ばれてるんだ。まあ、この「おデブさんたち」がそう呼び続けてるだけなんだけどね。ogresなら誰が持っててもおかしくないけど、特定の奴が持ってるかどうかは分からないな。衛兵のほうが持ってる見込みは高いかも……\n\n何言ってるんだ僕は。もう持ってるんだろ?! そこにあるのがそうなの??!", "あんたは1位だ。ほかの連中はみんな2位以下だな。ああ、助け出してくれてありがとう!\n\n俺の人生が、どこかのogreの前菜で終わるだけのはずがないと思っていたんだ!", 0x64c5142b, nil, nil, 0x1e7a9da3, 0xd66be950, ".mm.." },
  [5526] = { "Felvineのかけら", "Dire MaulでFelvineを見つけ、そのかけらを手に入れて下さい。手に入れる機会は、Alzzin the Wildshaperが消滅するとき一度きりです。Reliquary of Purityを使い、かけらを中に入れて厳重に封をして、MoongladeのNighthavenにいるRabine Saturnaのところへ持ち帰って下さい。", "Eldre'Thalas、もとい、FeralasのDire Maulに関する知識が役に立つだろう、{name}。廃墟と化した都市の東部が、Alzzin the Wildshaperが不正な支配を及ぼした場所だ。出来るだけ早く行って、己を待つどんな挑戦にも勇敢に立ち向かうのだ。\n\n今やFelvineへとなり果てたFruit of Fertilityは、Alzzinの近くにあるはず。彼が倒れたら、手に入るFelvineのものは何でも確保するように。それを聖遺物箱にしまい、私のところへ持ってきてほしい。\n\n幸運を、そしてCenarionの速さのあらんことを。", "Sealed Reliquary of Purityが我々の手にあれば、堕落をもたらす脅威をこの世界から取り除くだけでなく、我々の慎重な監視の下でそれを研究することもできるでしょう。常にAzerothを脅かす堕落の穢れに立ち向かう、新たな手段を考え出せるかもしれません。\n\nMilliもきっと、それ以外は望まなかったはずです……", "終わったな、勇敢な{class}よ。これでまたCenarion Circleは借りができたのだな。我々に破滅をもたらす者に対する大きな戦いに勝利したが、戦争は終わったわけではない。\n\n尽きぬ感謝の印として、これを受け取ってはくれないか。偉業によってあなたはCenarion Circleの英雄として歓迎されているのだ、{name}よ。ありがとう。", 0xc529120d, 0xbcbf4d83, 0x558aeb85, 0x10072c8b, 0x41482f0f, "....." },
  [5527] = { "Reliquary of Purity", "Silithusへ行き、ruins of Southwind VillageにあるReliquary of Purityを探して下さい。見つけることができたら、MoongladeのNighthavenにいるRabine Saturnaのところへ持ち帰って下さい。", "まず第一歩は、持ち運ぶ者に悪影響を及ぼすことのない、とてももろい物質でも保存しておける箱を探すことだ。Felvineのような不浄の物でもしまっておける、ただひとつの道具を知っている。Reliquary of Purityだ。\n\nSilithusの荒野の奥深くには、Southwindとして知られるナイトエルフの村の名残がある。確かにその箱はそこにあったのだ、遠い遠い昔に。我々が成功するには、まず箱を取り戻すために廃墟を調べて欲しい。", "Reliquary of Purityは、それ自体が一つの秘宝です。作られた数はごくわずかで、そのほとんどは長い年月の間に失われたと考えられていました。\n\n正直に言うと、Southwindにあるものについては、少し前から知っていました。実のところ、Silithusで混乱が高まる中、我々の秘密はそのまま秘密にしておこうと考えていたのです。あれこれ探れば、敵の疑いを強めるだけですから。\n\nですが、もう安穏としていられる時は終わりました。とりわけEldre'Thalasの状況を考えれば。", "確かに、あなたは多くの者が言う通り、機転の利く方ですね。Cenarion Circleは、あなたが私たちに代わって働いてくれることを幸運に思っています。\n\nReliquaryが再び私たちの手に戻り、心が安らぎました。これで、邪悪な悪魔に立ち向かうだけでなく、その過程で危険な品を持ち帰ることも、安心してあなたにお願いできます……", 0x981c408b, 0x70105b2e, 0x93f71390, 0x39eb133a, 0xe4f96df3, "....." },
  [5528] = { "Gordokの利き酒", nil, nil, nil, "もうあんたはおらのボスだ。だから、良いビールをタダでもらえる! この酒は力をつけて、その上、ばっちり酔わせてくれるだど! これはええもんだで、ボス……飲んでみて、おらに感想を教えてくんろ!", 0xd6c83438, nil, nil, nil, 0xab0267f0, ".mmm." },
  [5529] = { "Plagued Hatchlings", "Plagued Hatchlingsを$N1体倒し、Light's Hope ChapelのBetina Bigglezinkのところへ戻って下さい。", "Argent Dawnは最近、Scourgeが自分たちの疫病に侵されたドラゴンの眷属を作り出していることを知った！奴らを止めねばならない――Scourgeがドラゴンの軍勢を手にすれば、奴らは誰にも止められずにAzerothを蹂躙するだろう！\n\n奴らの死霊術師どもは、Darrowmere Lakeの真ん中にあるScholomanceで、疫病に侵されたドラゴンを繁殖させている。\n\nScholomanceへ行き、幼竜をできる限り多く倒してくれ……奴らがこれ以上大きくなる前に！", "Scholomanceへ向かえ、{name}。疫病に冒された雛どもが育つ前に始末するのだ!", "よくやった、{name}! 奴らがまたドラゴンの一群を育てられるようになるまでには、長い時間がかかるだろう。\n\n……少なくとも、そうだといいんだが!", 0x3fc48153, 0xdee3cc58, 0x8920582f, 0xf2479aae, 0xe2d0cdfb, "....." },
  [5531] = { "Betina Bigglezink", "Frozen EggsをBetina Bigglezinkのところへ持って行って下さい。", "あなたが持ってきた卵は、疫病に侵されたドラゴンの眷属を作り出すScourgeの実験に使われるはずのものでした。この凍ったブラックドラゴンの卵は、彼らの研究にとってかけがえのないものとなり、間違いなく計画を早めていたことでしょう。\n\nさあ、彼らの研究を終わらせる時です。\n\n外にいるBetina Bigglezinkのところへfrozen eggsを持って行ってください。彼女は科学と錬金術に精通していて、Scourgeに対して使える武器を作り出しました。あなたの助けがあれば、奴らに大きな打撃を与えられるでしょう。", "やあ、{name}! dragonの卵を持ってきたって聞いたけど? さあ、見せてよ!", "あった! しかもこんなに素敵な入れ物に入って。ぴったりの大きさだ!\n\nこのeggsは後で研究できるよう安全な場所に保管しておくけど、今はあなたがそれを運んできた入れ物が必要なんだ。\n\nとても特殊な用途の装置を作ったんだ。Scholomanceのアンデッドの学者たちを滅ぼすためのものさ。奴らは疫病に侵されたドラゴンの軍団を作ろうとしてドラゴンを研究していて、私たちはそれを止めなきゃならない。\n\nこの装置をDawn's Gambitと呼んでいるんだ。だって……うまく動くかどうか分からないからね!\n\n私たちのために確かめてくれる?", 0x30d1cbfe, 0x6bca54e4, 0xdc0387b4, 0x77631291, 0xa2c1f1e1, "....." },
  [5533] = { "Scholomance", "Western PlaguelandsのChillwind PointにいるAlchemist Arbingtonと話して下さい。", "Caer Darrowの島には、Scholomanceがある――Scourgeの死霊術と悪の忌まわしい本拠地だ。我々の敵はその中に棲み、何も知らぬ犠牲者たちに口にするのもおぞましい堕落した行いをしている……少なくとも、我々はそう推測している。扉が行く手を阻み、どれほど試みても、正しい鍵がなければ入ることはできないのだ。\n\nAlchemist ArbingtonはScholomanceに詳しく、鍵を手に入れる方法について考えがある。君は私に自らの価値を証明した。今こそこの仕事を君に託そう。この件について彼と話してくれ。", nil, "よく来た、{class}。私は最近の研究のかなりの部分をScholomanceに費やしてきた。鍵を手に入れる方法を知っていると思う……正面の扉を通り抜けられる鍵をな。\n\n中でどれほど恐ろしい光景が見られるのか、想像するしかない、{name}。君たち英雄というものは、時々どうやってそれをやってのけるのか分からないよ……", 0xae1cd677, 0x8ba34863, 0xf80116ef, nil, 0xc04c0f0c, "...m." },
  [5534] = { "Kim'jaelの「なくした」装備", "Ruins of Eldarathでnagaが持っているSome Runeを見つけ、AzsharaのKim'jaelのところへ持って帰って下さい。", "なんだと？！なんだと？！\n\nあれじゃ足りないってのか？あの爆薬がどれだけ高いか分かってるのか？あれは売れば……ああ、もういい。分かったよ、本物の金を稼ぎたいってのか？商売ってのはそういうもんだ。自分が価値ある従業員だと証明して、しばらく辛抱した後でそれなりの見返りをもらうのさ。\n\nお前が「価値ある」従業員なら、Ruins of Eldarathへ乗り込んで、あのBlood elvesどもが探してたルーンとやらを見つけてこい。どうやらnagaがそれを持ってるらしい。", "で、{name}? ルーンはどこだ? お前はいい社員だよな? 手伝いに来たんだよな?\n\n約束した額を払うかどうか、考え直させないでくれよ。何? 何も約束してない? そりゃ結構……じゃあ、ゆっくりやってくれ。ただし、時間がかかればかかるほど、額はずっと少なくなるってことは覚えときな。", "ははっ! 最高だ!\n\nこいつが何のためのものか、そしてなぜMagus Rimtori(俺を雇ったあの牝牛だ)がこれを欲しがったのか、必ず突き止めてやる。はっ! 捕まえたぞ、臭いBlood elvesども! Kim'jael! はっ! どっちがネズミか思い知らせてやる!\n\nよくやってくれたな、{name}。本当にありがとよ。ほら、この金を持ってとっとと行きな。俺には考えなきゃならんことがあるんでね。", 0xf766ac57, 0xfefdfba8, 0x3651b51e, 0xfc701bc7, 0xfd93df7c, "....." },
  [5535] = { "霊の不穏", "Highborne Apparitionsを$N1体とHighborne Lichlingsを$N2体倒してから、AzsharaのLoh'atuのところへ戻って下さい。", "遠い昔、Highborneはナイトエルフが生み出した中でも最も強力な秘術の探究者たちでした。そうした探究に伴う腐敗は、ナイトエルフの社会に大きな害をもたらし、Azeroth全体にも大きな影響を及ぼしました……きっとよくご存じでしょうが。\n\n私はSentinelsに、霊を見つけたらその定命の枷から解き放つと約束しました。あなたも同じことをしてくださるなら、きっといくらかのお礼ができるでしょう。\n\n霊たちはここから北東にあるShadowsong Shrineに出没しています。", "Highborneの霊の捜索は進んでいるか、{class}?\n\n多くの出来事がAzerothのあらゆる種族に大きな苦しみをもたらしてきたが、なぜかこの霊たちは、すべての人々にとって災いとなっているようだ。おそらく、あらゆる秘術魔法への尽きることのない渇望のせいだろう。そのような渇望はBurning Legionの前触れであり、それが何を招くかは我々も知っている。", "よくやってくれました、{class}。助けてくれてありがとう。霊たちは安らぎを得、彼らの秘術への渇望が引き寄せていた脅威も弱まりました。\n\nAzerothを荒廃させている争いの両陣営も、あなたがそうしたものを超越した存在だと認めることでしょう。", 0xe4e4cb2a, 0x91c9558c, 0x049d9101, 0x263ff8de, 0x8d913bdf, "....." },
  [5536] = { "憎しみに満ちた地", "Haldarr Satyrを$N1体、Haldarr Trickstersを$N2体、Haldarr Felswornを$N3体倒し、Ashenvaleの境にいるLoh'atuのところへ戻って下さい。", "satyr――ナイトエルフの醜く歪んだ邪悪な姿――が、かつてCenariusが歩いた聖なる地を今や蝕んでいます。あの悪魔のような生き物たちが犯してきたあらゆる残虐行為について、私はナイトエルフの代弁をすることはできませんが、この地からあのような厄介者を追い払うためにエルフたちを手助けすると、Earthmotherに誓いを立てたのです。\n\n彼らの一掃を手伝ってくだされば、あなたはきっと自らの力を証明できるでしょう。\n\nここから北東で、Haldarr氏族を見つけられます。彼らの力に挑んで自分を試したら、私のもとへ戻ってきてください。", "satyrとの戦いはどうだ、{class}?\n\n奴らは思っていたとおりの強さか? それ以上か? それとも、お前の力の前では取るに足らぬ相手だったか。", "よくやってくれました、{class}。あなたは腕が立つだけでなく、賢くもあるのですね。あのような生き物を倒したことは、たとえEarthmotherをあなた自身の神と認めていなくとも、Earthmotherの教えへのあなたの忠誠の証です。彼女はこの星とその彼方のあらゆるものの中にいます。彼女の目は、片方は闇、もう片方は光で、空を渡りながら常に私たちを見下ろしているのです。\n\nどうか、あなたの行いへの感謝として、このわずかな金を受け取ってください。", 0xa3964943, 0xed594c4b, 0x2bfad3c5, 0xe837c9b8, 0xc130540a, "....." },
  [5537] = { "Skeletal Fragments", "Skeletal Fragmentsを$N1個、Western PlaguelandsのChillwind PointにいるAlchemist Arbingtonのところへ持って行って下さい。", "Scholomanceの鍵はSkeleton Keyと呼ばれている。骸骨の遺骸から――実のところ、いくつもの骸骨からだが――鍛え上げ、ふさわしい型の中で、最も強い金属だけを使って硬化させねばならない。そして、生まれつきScholomanceへの門を開くことのできる存在の力の印章があれば、鍵はついにその働きを果たすのだ。\n\nだがまずは第一歩からだ、{name}。鍵を鍛えるにはskeletal fragmentsが必要だ。Andorhalの中の骸骨から必要なものが手に入るはずだが、壁の外にいる骸骨でも役に立つかもしれん。", "気味の悪い話だが、鍵の外側を作るには、それなりの量の適したskeletal fragmentsが必要になる。Skeleton Keyと呼ばれているのは伊達じゃないのさ。", "これで使えるぞ、{name}! 今度は私の番だ。これにふさわしい焼き入れを施して、いずれ通ることになる激しい鍛造の工程に耐えられるようにしよう。\n\n次の段階は、鍵に合った鋳型を手に入れることだ。Tanarisに、以前にも同じように不気味な品の鋳型を作ったことのあるゴブリンの鍛冶屋を知っている。彼はゴブリンがたいてい仕える相手のために働いている。つまり、一番高い値をつけた者のためにな。", 0x9baabfac, 0x1854fe7d, 0x83a68ed3, 0x6cb2156e, 0x9f83db8b, "....." },
  [5538] = { "モールドと韻を踏むのは……", "Imbued Skeletal Fragmentsと金貨$N1枚をGadgetzanのKrinkle Goodsteelのところへ持って行って下さい。", "話をしてもらう必要のあるゴブリンは、Krinkle Goodsteelだ。奴はTanaris砂漠のGadgetzanで、一番高値をつけた者に腕を売っている。我々に必要な鋳型を作れるのは、おそらく奴だけだろう。そして奴の仕事は安くはない。そこで、奴が請求する料金がいくらであれ、君に自腹を切って支払ってもらいたいのだ。\n\n私は錬金術師であって、銀行家ではない。そこらに金が転がっていたら、とっくにここにはいないさ。\n\nおっと、また言わなくていいことを口に出してしまったようだ。しまった。\n\nGadgetzanが君を待っている！幸運を祈る！", "ああ、あんたが誰かも、なぜここに来たかも分かってる。あんたが着く前に、Arbingtonから知らせがあったんでね。さっそく本題の取引といこうじゃないか。\n\nskeleton keyに使える鋳型がある。だがタダじゃない。金貨15枚、前払い、値切りはなしだ。skeletal fragmentsは俺が鋳型に詰めてやるし、鍛冶の知識がなくても鍵の軸を鍛えられるよう、やり方も教えてやる……しかも全部無料でな。\n\n傭兵がお得な取引をしないなんて、誰が言った!", "Arbingtonが品物を届けてくれると言ってたが、本当に届けてくれたな! 取引は取引だ。fragmentsを鋳型に詰めてやるよ。\n\nArbingtonはもう焼き入れを済ませたのか? そいつはいい……そうでなきゃ、Chillwind Pointまで長い道のりを戻る羽目になってたぞ。", 0x64e41d76, 0x50531b06, 0x76618973, 0x9deea60d, 0x9299c917, "....." },
  [5541] = { "Rumbleshotの弾薬", "Dun MoroghにいるHegnar RumbleshotにRumbleshot's Ammoを渡せ。", "Hegnar RumbleshotはAnvilmarの郊外で銃を売っている。射撃手と迫撃砲チームは彼の店の外すぐ近くで、多くの時間を練習して過ごす、だから、いつも新しい弾薬が必要なのだ。\n\nだが・・・私が彼に送った最後の弾薬が途中で失われたのだ。配達人が言うには、Grizzled Denの近くで野宿をしていた時、Wendigoに追い払われたらしい・・・・そして愚かにも、Rumbleshotの弾薬を忘れてきてしまった！\n\n{name}, 弾薬を見つけて、Rumbleshotに届けてくれないか？彼は配達を待っているだろうし、きっと弾薬が残り少ないだろう。", "弾薬を買いに来たんじゃなきゃいいがな。もうほとんど残っとらんのだ!", "すばらしい、弾薬だ！Loslor老の配達品がようやく届いたか！弾薬は遅れたが、わしの爺さんが言ってたよ、「来ないより、遅れる方がましだ！」\n\n感謝するよ {name}, もうその品には買い手がついてるんだ！", 0x6bdee02c, 0x4a7a3e42, 0x0214773d, 0x38170153, 0xa9ceafda, "....." },
  [5542] = { "悪魔の犬", "Plaguehound Runtsを$N1体、Plaguehoundsを$N2体、Frenzied Plaguehoundsを$N3体倒す。任務を終えたらTirion Fordringのところへ戻って下さい。", "ここに留まるつもりなら、自分の食い扶持くらいは稼いでもらいたい。「しつけ」が必要な厄介者がたくさんいるのでな。\n\nまずはPlaguehoundsとその子らから始めるといい。\n\n見返りに多くは出せんが、うまくやれば温かい食事と少々の話し相手は保証しよう。", "悪魔の犬どもに情けをかけるな、{race}。奴らは忌まわしき化け物だ!", "よくやった、{name}。さあ、休め。食べながら遠い昔の日々を語り合おうではないか!", 0x74a3977e, 0x9c39d09a, 0xde0718df, 0xa091d5c2, 0x87ef13e0, "....." },
  [5543] = { "血に染まる空", "Plaguebatsを$N1体倒し、Tirion Fordringのところへ戻って下さい。", "愚かにもPlaguelandsに迷い込む者に災いあれ。この森にはありとあらゆる穢れが棲んでいる――Crusadeの印を持たぬ者を皆殺しにする狂信的なScarlet Crusadeから、アンデッドを仲間に加えて数を増やすことしか考えぬ凶悪なScourgeまで。\n\n野生の生き物でさえ、人を喰らう貪欲な獣に変わってしまった。空から襲いかかってくる者どもを滅ぼしてほしい。Plaguebatsだ。", "翼を持つ害獣どもを侮るな、{race}。Plagueが奴らに超自然の力を与えたのだ。", "そなたは品位の輝かしい手本だ、{race}! 英雄の血がこの血管に脈打つのを感じたのは久しぶりだ。そなたの勇敢な行いは心を奮い立たせる!", 0x1e870c8b, 0xf57a91fa, 0xc7740ef1, 0x830618bf, 0xd5aab03d, "....." },
  [5544] = { "Carrion Grubbage", "この地域のCarrion GrubsとDevourersを探し出す。それを倒して肉を集める。Slabs of Carrion Worm Meatを$N1個集めたら、Tirion Fordringのところへ戻って下さい。", "食料が乏しくなってきておる、{race}よ。恥ずかしながら、お前に分けてやれるだけの食料がないかもしれん。\n\nこの老いぼれの簡単な頼みを聞いてくれんか？このあたりで、Plagueの惨禍を受けていない獣はCarrion wormsだけだ。味はかなり淡白だが、その肉は何か月ももつよう簡単に保存できる。来たる冬に備えて蓄えを補うには、数百ポンドは必要なのだ！", "そのうち味にも慣れるさ、{race}。", "光があなたを見守りますように! 祝福を、若き者よ。", 0x6445813c, 0xada0ab83, 0x3dc9e55f, 0xadfc7a15, 0x0ac9cf94, "....." },
  [5545] = { "大量のトラブル", "Eastvale Logging CampにいるRaelenに、Bundles of Woodを８束持っていく。", "あたしさ、本当に大きな問題を抱えているんだ。木材の注文に対応しなければならなくて。期日が迫ってるの。従業員が北で木材を調達している最中に、オオカミやクマに襲われて、逃げ帰ってきて、どうにもならない状態なのよ。\n\nDeputy Rainerには、その動物たちをなんとかしてほしいって既に言ってるんだけど、誰かに木材を調達してきてほしいのよ。もしbundles of woodを８束持ってきてくれたら、期日に間に合うかもしれないの。", "締め切りは遠のいてはくれないぞ、{class}。急いで薪の束を集めてきてくれ。", "すっごおい！ありがとう。これで何とか期日に間に合うわ。感謝と、あたしのトラブルに関わってくれた迷惑料として、お礼するわ。\n\n本当にありがとう。", 0x014730dc, 0xa7c51bc1, 0x3cba4cdf, 0x1f6b6abf, 0x45f9cae3, "....." },
  [5561] = { "Kodo 集め", "Tamed Kodo 5頭と Kodo Kombobulator をSmeed Scrabblescrew に渡す。", "Bibblyは、Desolaceで金の稼ぎ方を知ってるゴブリンは自分だけだと思ってる。だがな、このあたりを旅するほど肝の据わった唯一の隊商は、私を頼りにしてるんだ。私のKodo Kombobulatorで年老いたkodoや死にかけのkodoを若返らせて操る方法を覚えてから、隊商の持ち主のCorkとRigger、それに私とで手を組んだのさ。\n\nKodo Kombobulatorを持っていって、太古の、年老いた、あるいは死にかけのkodoに使ってくれ。獣に衝撃が走って手なずけられたkodoになり、あんたについてくるようになる。kodoを手なずけたら、私のところへ連れてきてくれ。", "キャラバンはもうすぐ着く。頼んでおいた、新しく飼い慣らしたkodo 5頭はそろったか?", "<Smeed Scrabblescrewが数え始める。>\n\n3、4、そして5……上出来だ、飼い慣らしたkodoを5頭頼んで、5頭手に入った……俺は金持ちになるぞ……ああ、大金持ちだ! 俺の成功を聞いたときのBibblyの緑の顔を見てみたいもんだ!", 0x04bb1caf, 0xd279a8c8, 0x6b6406ad, 0x132725c5, 0x6e31573b, "....." },
  [5581] = { "Legionの入り口", "Mannoroc Coven にあるポータル6つを消し、Shadowprey Village にいる Taiga Wisemane のところへ戻る。", "見よ――Hand of Iruxosだ。実におぞましい代物だな。\n\nMannoroc Covenの悪魔の門を封じるには、お前がこれを持っていなければならない……それこそが、今私がお前に頼みたいことだ。悪魔の脅威は増しており、この世界へ押し寄せる悪魔の流れを食い止めるために、これらの門を閉じねばならない。幸運を祈る、{name}……門の守護者たちには気をつけろ。", "Mannoroc Covenの悪魔のポータルは封じたか?", "お前は称賛に値するぞ、{name}。お前の働きは悪魔の脅威との戦いに大いに役立った。そのおかげで、Azeroth全土がより安全になったのだ。", 0x67992a9e, 0x90813dc1, 0x935957b4, 0xe50d445b, 0x43ae0b56, "....." },
  [5601] = { "Sister Pamela", "DarrowshireでPamela Redpathを見つける。", "先の大戦の間に私はLordaeronを逃れ、Scourgeが故郷を席巻して疫病の悪夢に変えてしまう前に、運よく脱出できました！私は運が良かったけれど、家族はそうではありませんでした。皆、Darrowshireの戦いで殺されてしまったのではないかと恐れています。\n\nDarrowshireは、今のEastern Plaguelandsの南の丘陵に抱かれた、Eastern Kingdomsの村です。そこへ行って、私の家族を探してくれませんか？皆にとても会いたいのです。特に、幼い妹のPamelaに。\n\nお願いです、あの子を見つけてください！", nil, "私のお姉ちゃんのJessicaはどこ? ずっと前、私がまだ小さな女の子だったときに行っちゃったの。行くとき、すごく泣いてた。どうして泣いてたのか分からない! 転んでつま先をぶつけたのかも。\n\nJessicaがここにいたときは、一緒に遊んだり踊ったり、家のまわりできれいなお花を摘んだりしてたの。それに、パパが帰ってくるのが見えたら隠れて、飛び出してびっくりさせたりもしたんだ!\n\n帰ってきて、Jessica! お姉ちゃんが帰ってきたら、パパもきっと帰ってきて、またみんなで一緒に遊べるかもしれないのに……", 0xffb691bd, 0xa62eeff1, 0x24f8b115, nil, 0x81dbba27, "...m." },
  [5621] = { "月の法衣", "Sentinel Shayaを見つけ、Lesser Heal (Rank 2)を使って彼女の傷を治療して下さい。その後、Power Word: Fortitudeをかけ、DolanaarにいるLaurna Morninglightのところへ戻って下さい。", "あなたの助けが必要です、{name}。私は他の生徒たちを教えるためにここにいなければなりませんが、あなたなら、Dolanaarのすぐ南にいる負傷したSentinelsの一人を助けられます。彼女は町を巡回中に傷を負い、我々の助けを必要としています。名前はShayaです。\n\n彼女を見つけたら傷を癒し、それから呪文で彼女の体を強化してください。そうすれば、もし危険に遭っても、少なくともより長く害から守られるでしょう。Eluneへの務めを果たしたら、ここへ戻ってきてください。", "我々のFortifyの呪文は非常に強力です、Delor。仲間があらゆる種類の攻撃からさらに多くの傷を受けても耐えられるようにし、本来なら倒れてしまう状況でも生き延びさせてくれます。ですが、我々の癒しの力と比べれば、これは何でもありません。プリーストに勝る癒し手はいない――それをよく覚えておきなさい。あなたの力だけで、戦いの流れを容易に変えることができるのです。", "あなたはよく務め、Eluneに仕えました。そのことに感謝します。\n\nどうか、感謝の印としてこのローブを受け取ってください。これは、あなたが我々の教団の中に居場所を得たことを示すものです。望むなら、誇りを持って身に着けなさい。けれどどちらであっても、私たちは常にあなたを我らの一人として認めます。\n\nEluneとともに行きなさい、{name}。そして、ありがとう。", 0x73f2ce3b, 0x26c8717b, 0xf5680a7c, 0xdd03baf4, 0xb864207f, "....." },
  [5622] = { "Eluneの賛同者", "TeldrassilにいるLaurna Morninglightに話しかけて下さい。", "{name}、ここShadowglenでの用事が済んだら、Dolanaarへ行かなければなりません。そこでLaurna Morninglightに会えるでしょう。彼女がEluneの道についてさらに導いてくれます。そして、Eluneのプリーストとしてのあなたの立場を示す最初の衣を得るのも、彼女のもとでのことです。\n\n気をつけて。あなたの旅が守られますように。", nil, "{name}、Shandaがあなたを送り出してくれて嬉しいですよ。若い司祭にEluneの御技を教えることは、満ち足りた思いを与えてくれますから。", 0x1f581c9a, 0x7edc7e4a, 0xe180ecac, nil, 0xfc0c1954, "...m.", nil, nil, 0xa4f739a2, nil, nil },
  [5623] = { "光に賛成して", "Elwynn Forestにいる Priestess Josetta と話してください.", "またお会いしましたね。 我々の信仰についてもっと学ぶべき時が来たようです。Northshireで請け負える仕事を終えたあとは、GoldshireでPriestess Josettaを探してください。あなたが光の道で強く成長していると知ったなら、彼女があなたに教えることはまだまだあるでしょう。彼女はあなたにより多くのことを教えることを楽しみにしています。", nil, "ここまでたどり着いてくれて嬉しいです、 {name}. 私たちは光の中でのあなたの将来と行く手について話し合うべきことがたくさんあります。", 0xd5e3412d, 0xf024d04d, 0xfb192887, nil, 0x0ffe1fdc, "...m.", nil, nil, 0xc820e603, nil, nil },
  [5624] = { "光の衣装", "Guard Robertsを発見し、Lesser Heal (Rank 2)を使って彼の傷を癒してください。 その後、Power Word: Fortitudeを彼にかけてGoldshireのPriestess Josettaのもとに戻ってください。", "通常、光の信徒のスキルを試す、小さな課題を出します。私はその最初のローブ--教会が認め、手助けする司祭であるという外見上の証--を身につける価値があるか見てみたいのです。\n\nでもこの状況は少しばかり違います。Goldshireの住人の一人がここから東にある湖の近くで負傷した衛兵を見ました。彼の名はRobertsです。彼を見つけて癒し、彼の体を強化してここに戻ってください。それが出来たらテストは終了と見なします。", "すでに学んだかもしれませんが、我々の癒しの魔法は、この過酷な時代に人々が生き延びるために欠かせません。とりわけ、数多くの脅威に立ち向かうために武器と魔法を手に取る冒険者や英雄たちにとっては。\n\nその技がどれほど大切か、常に心に留めておくとよいでしょう。それにFortitudeを合わせれば、仲間はより多くの打撃に耐えられるようになり、戦いではるかに頼もしくなります。\n\nあなたの魔法の力を軽んじる者がいても、耳を貸してはなりません。", "すばらしいですよ、{name}。町を助ける健康な衛兵がもう一人増えて、私たちはそれだけ安全になります。あなたが賢明にその能力を使うことをすでに学んでいることがわかって嬉しいです。もしあなたがもっと多くのトレーニングを受ける準備ができたと思ったときにはいつでも、私の元に来てください。でも今はこのローブをお取りなさい。 それはあなたが教団の一員であることを他の人に知らせるでしょう。もしあなたがこれを身につけたくなくてもかまいません。いずれもっと多くのテストがありますし、このローブはそれには必要ありません。", 0x42e1e67f, 0xd5d19b32, 0x701bafd9, 0xe1f1d1b3, 0xb57951a7, ".....", nil, nil, 0x1e24900e, nil, nil },
  [5625] = { "光の法衣", "Mountaineer Dolfを見つけ、Lesser Heal (Rank 2)を使って彼の傷を治療して下さい。その後、Power Word: Fortitudeを彼にかけ、KharanosにいるMaxan Anvolのところへ戻って下さい。", "普通なら、お前さんほどの力の者は、この頃に教会での立場を示すローブを着るに値するかどうか試されるもんだ。だが正直言うと、わしにはもっと急ぎの用があってな。Kharanosの住民がついさっきここに来て、町のすぐ南で山岳兵が怪我をしてると教えてくれたんだ――名前はDolfだ。\n\nDolfを癒してFortitudeをかけてやれ。そうすりゃ、お前さんの証明は済んだことにしよう。どうだ？", "Dolfはもう見つかったかい、{name}?\n\nもう知ってるだろうが、わしらの癒しの力はとても役に立つ。怪我人の手当てができるだけじゃない。名を上げようと外で頑張っとる英雄志望の連中が生き延びるには、わしらが欠かせんのさ。Fortitudeで耐えられる打撃を増やし、癒しの魔法で命をつなぐ。そうすりゃ、乗り越えられんものなど何もない!", "素晴らしいです、{name}。町を助ける元気な衛兵がまた一人増えて、私たちはそれだけ安全になりました。あなたがもう自分の能力を賢く使うことを学び始めているのを見て、嬉しく思います。もっと訓練を受ける準備ができたと感じたら、いつでも私のところへ戻ってきてください。でも今は、このローブを受け取ってください。これを着ていれば、あなたが私たちの教団の一員だと他の人にも分かります。着たくなければ、それでも構いません。この先さらに試練がありますが、それにこのローブは必要ありませんから。", 0x42e1e67f, 0x4324dd9b, 0x0d9a711f, 0x0425d788, 0xb57951a7, "....." },
  [5626] = { "「光」の賛同者", "Dun MoroghのMaxan Anvolに話しかけて下さい。", "おい！ {name}！ ちょっといいか？！\n\nお前さんはもう十分長く光に従ってきた。そろそろKharanosのMaxan Anvolを訪ねる頃だ。お前さんの歩む道についてもっと教えてくれるし、ふさわしいと認められれば、プリーストとしての立場を示す最初のローブをくれるだろう。\n\nさあ行け！ ここでの用が済んだら、トンネルを抜けていけ――彼が待ってるぞ。", nil, "おや、Branstockが送り出したのかな? よしよし! 彼は正しい。「光」へと大きな一歩を踏み出す頃だ。その一歩は人格を鍛え、君をもっと強くするだろう……そして、君が何より必要とするものとは、肉体の力……意思の力だ。", 0xd5e3412d, 0x5cf188e4, 0x84b16634, nil, 0x77d8d926, "...m.", nil, nil, 0xb689446c, nil, nil },
  [5627] = { "Eluneの星", nil, nil, nil, "あなたはEluneの目に留まるにふさわしいことを証明しました、{name}。準備ができたと感じたなら、私たちの民に固有の、彼女の呪文の1つをぜひあなたに教えたいと思います。", 0x8a355ee6, nil, nil, nil, 0x6f78fed8, ".mmm." },
  [5628] = { "帰郷", "DarnassusのPriestess Alatheaと話す。", "ああ、ええ、こんにちは、{name}でしたか？ 少し立ち止まって話してくださって嬉しいです。そんなに若いのに故郷から遠く離れて――その向上心には感心します。私も若い頃に、世界を旅する勇気を奮い起こせていたらよかったのですが。\n\n少し前に、あなたの教団の女司祭がここへあなたを探しに来ていました。DarnassusのTemple of the Moonへ戻って、Priestess Alatheaと話すことがとても急を要すると言っていました――あなたの修行に関わることだそうです。できるなら、あまりぐずぐずしないほうがいいでしょう。", nil, "素晴らしい、故郷に戻ってきたのですね、{name}。私たちが鍛えた者が世界へ旅立ち、無事に戻ってくるのは、Tyrandeと私にとっていつも喜びです。あなたのほうはどうでしたか? Eluneは今もあなたの旅を祝福していますか? 当面の用件について話したあとで、あなたの旅のことをもっと聞かせてもらえるかもしれませんね。", 0xab7568f5, 0x8f9be0c1, 0x8242adf0, nil, 0x8d04e540, "...m." },
  [5629] = { "帰郷", "DarnassusのPriestess Alatheaと話す。", "また会いましたね、{name}。あなたが私たちの民の力になるのに忙しいのは知っていますが、自分のための時間も取らなければいけませんよ。Priestess Alatheaが、あなたを探しにここへ人をよこしました。あなたは長老たちの目に留まり、より大きなことへの準備ができていると思われているようです。DarnassusのTemple of the Moonへ向かい、そこでAlatheaを探してください。彼女が待っています。幸運を。Eluneがあなたと共にありますように。", nil, "素晴らしい、戻ってきたのですね、{name}。私たちが鍛えた者が世界へ旅立ち、無事に戻ってくるのは、Tyrandeと私にとっていつも喜びです。あなたのほうはどうでしたか? Eluneは今もあなたの旅を祝福していますか? 当面の用件について話したあとで、あなたの旅のことをもっと聞かせてもらえるかもしれませんね。", 0xab7568f5, 0x8f9be0c1, 0xa8f3f5b8, nil, 0xcbab1194, "...m." },
  [5630] = { "帰郷", "DarnassusのPriestess Alatheaと話す。", "やあ、若いの。遠い土地まではるばる旅してるようで何よりだ。悪気はないんだが、お前さんの種族はたいてい、こういう寒い土地が苦手なもんでな。お前さんはもっと丈夫にできてるようで嬉しいよ。\n\nちょっと前に、お前さんとこの女司祭がここへお前さんを探しに来てたぞ――Darnassusに戻って、Temple of the MoonのPriestess Alatheaって人に会えとか何とか言ってたな。大事なことだから、すぐ戻ったほうがいいそうだ。", nil, "素晴らしい、故郷に戻ってきたのですね、{name}。私たちが鍛えた者が世界へ旅立ち、無事に戻ってくるのは、Tyrandeと私にとっていつも喜びです。あなたのほうはどうでしたか? Eluneは今もあなたの旅を祝福していますか? 当面の用件について話したあとで、あなたの旅のことをもっと聞かせてもらえるかもしれませんね。", 0xab7568f5, 0x8f9be0c1, 0x3b3bfab4, nil, 0x8d04e540, "...m.", nil, nil, 0x25879782, nil, nil },
  [5631] = { "帰郷", "DarnassusのPriestess Alatheaと話す。", "最近、一人の女司祭があなたを探して我々の広間を訪ねてきたぞ、若き{race}よ。彼女はあなたを見つける使命を帯びていて、あなたにはできるだけ早くDarnassusのTemple of the Moonへ戻ってほしいと言っていた。着いたらPriestess Alatheaを訪ねるといい――詳しいことは彼女が話してくれるだろう。\n\n光があなたと共にあらんことを、{name}。", nil, "素晴らしい、故郷に戻ってきたのですね、{name}。私たちが鍛えた者が世界へ旅立ち、無事に戻ってくるのは、Tyrandeと私にとっていつも喜びです。あなたのほうはどうでしたか? Eluneは今もあなたの旅を祝福していますか? 当面の用件について話したあとで、あなたの旅のことをもっと聞かせてもらえるかもしれませんね。", 0xab7568f5, 0x8f9be0c1, 0xbd0e6a0c, nil, 0x8d04e540, "...m." },
  [5632] = { "帰郷", "DarnassusのPriestess Alatheaと話す。", "ああ、ええ、そうでした。こんにちは、{name}。少し前に、私たちの教団の使者があなたを探してここへ来ていましたよ。Darnassusで何か大事なことが起きていて、できるだけ早くTemple of the Moonへ戻るようにと言っていました。着いたらPriestess Alatheaと話してください。あなたが私たちの道で順調に成長していることと関係があるのだと思います。\n\nもう一度言いますが、都合がつき次第Darnassusへ戻ってくださいね。", nil, "素晴らしい、故郷に戻ってきたのですね、{name}。私たちが鍛えた者が世界へ旅立ち、無事に戻ってくるのは、Tyrandeと私にとっていつも喜びです。あなたのほうはどうでしたか? Eluneは今もあなたの旅を祝福していますか? 当面の用件について話したあとで、あなたの旅のことをもっと聞かせてもらえるかもしれませんね。", 0xab7568f5, 0x8f9be0c1, 0x9052d2b7, nil, 0x8d04e540, "...m." },
  [5633] = { "帰郷", "DarnassusのPriestess Alatheaと話す。", "ようこそ、若いの。我らの偉大な広間で会えて嬉しいぞ。お前さんとお前さんの種族に祝福あれ。\n\nお前さんが我らの地を旅している間に、お前さんの神殿の女司祭がお前さんを探しにここへ来たんだ。できるだけ早くTemple of the Moonへ戻るように、とのことだった。これ以上詳しく話せなくてすまんが、大事なことのようだったぞ。神殿に着いたら、Priestess Alatheaって人と話すといい。", nil, "素晴らしい、故郷に戻ってきたのですね、{name}。私たちが鍛えた者が世界へ旅立ち、無事に戻ってくるのは、Tyrandeと私にとっていつも喜びです。あなたのほうはどうでしたか? Eluneは今もあなたの旅を祝福していますか? 当面の用件について話したあとで、あなたの旅のことをもっと聞かせてもらえるかもしれませんね。", 0xab7568f5, 0x8f9be0c1, 0x23045fad, nil, 0x8d04e540, "...m.", nil, nil, 0xded29ca7, nil, nil },
  [5634] = { "Desperate Prayer", "IronforgeのHigh Priest Rohanと話す。", "最近、一人のプリーストがあなたを探して我々の広間を訪ねてきたぞ、若き{race}よ。彼はあなたを見つける使命を帯びていて、あなたにはできるだけ早くIronforgeのHall of Mysteriesへ戻ってほしいと言っていた。着いたらHigh Priest Rohanを訪ねるといい――詳しいことは彼が話してくれるだろう。\n\n光があなたと共にあらんことを、{name}。", nil, "あなたはこの危険な地やその先を旅する者たちの輝かしい手本となり、光に大いに尽くしてくれました。どうか、これまでのすべての行いへの感謝として、この教えを受け取ってください。", 0x5e463cb3, 0x18755abb, 0x16d5e391, nil, 0x8e6ca817, "...m." },
  [5635] = { "Desperate Prayer", "IronforgeのHigh Priest Rohanと話す。", "上の方々があなたに目を留めましたよ、{name}。できるだけ早くIronforgeのHall of Mysteriesへ来てほしいとのことです。どうやら、あなたはすでに実力を示したので、さらに修行を進める準備ができていると考えているようです。着いたらHigh Priest Rohanを探してください。彼がさらに導いてくれるでしょう。幸運を。光があなたと共にありますように。", nil, "よく来てくれました、{name}。話し合わねばならないことはたくさんありますが、それより大切なのは、光の道におけるあなたの修行です。\n\n光に仕える者が皆学ばねばならない教えがあります。準備ができているなら、今からそのいくつかについて話し始めましょう。", 0x5e463cb3, 0x18755abb, 0x87560e73, nil, 0xddc02048, "...m." },
  [5636] = { "Desperate Prayer", "IronforgeのHigh Priest Rohanと話す。", "Eluneの祝福を、善き{race}よ。今日もあなたの光があなたを見出し、しっかりと守ってくださいますように。\n\n少し前に、あなたの教団のプリーストがあなたを探しにここへ来ていました。High Priest Rohanと話すために、できるだけ早くHall of Mysteriesへ戻るようにと言っていました。それほどの注目を集めるとは、よく頑張ってきたのですね。ここに長居はしないほうがいいでしょう――あなたの同胞があなたを必要としています。", nil, "よく来てくれました、{name}。話し合わねばならないことはたくさんありますが、それより大切なのは、光の道におけるあなたの修行です。\n\n光に仕える者が皆学ばねばならない教えがあります。準備ができているなら、今からそのいくつかについて話し始めましょう。", 0x5e463cb3, 0x18755abb, 0x829d5d51, nil, 0xddc02048, "...m." },
  [5637] = { "Desperate Prayer", "IronforgeのHigh Priest Rohanと話す。", "そろそろStormwindへ向かう時だぞ、{name}。Hall of MysteriesのHigh Priest Rohanが、お前と話したいそうだ。大司祭がじきじきにお前を呼ぶなんて、よっぽどいいことか、よっぽど悪いことに違いねえが、俺の見立てじゃ、お前はうまくやってきただけだから、話したいってのはいいことだろうよ。\n\nだが、この辺でぐずぐずしてるんじゃねえぞ。俺ならできるだけ早く向かうね。", nil, "よく来てくれました、{name}。話し合わねばならないことはたくさんありますが、それより大切なのは、光の道におけるあなたの修行です。\n\n光に仕える者が皆学ばねばならない教えがあります。準備ができているなら、今からそのいくつかについて話し始めましょう。", 0x5e463cb3, 0x18755abb, 0x148eb4c2, nil, 0xddc02048, "...m." },
  [5638] = { "Desperate Prayer", "StormwindのHigh Priestess Laurenaと話して下さい。", "ほんの少し前、あなたの同胞のプリーストがあなたを探してここに来ていましたよ、{race}。もしあなたを見かけたら、Cathedral of Lightへ行くよう伝えてほしいと言っていました。とても大事なことだと言っていましたが、私があなたなら、あまり心配はしませんね。彼の様子は前向きに見えました……まるで良い知らせであるかのように。私があなたなら、あまり時間をかけずにそこへ向かいますよ。\n\nEluneがあなたと共にありますように、善き{race}よ。", nil, "よく来てくれました、{name}。話し合わねばならないことはたくさんありますが、それより大切なのは、光の道におけるあなたの修行です。\n\n光に仕える者が皆学ばねばならない教えがあります。準備ができているなら、今からそのいくつかについて話し始めましょう。", 0x5e463cb3, 0x8de762b6, 0x1cfc2115, nil, 0xddc02048, "...m." },
  [5639] = { "Desperate Prayer", nil, nil, nil, "よく来てくれました、{name}。話し合わねばならないことはたくさんありますが、それより大切なのは、光の道におけるあなたの修行です。\n\n光に仕える者が皆学ばねばならない教えがあります。準備ができているなら、今からそのいくつかについて話し始めましょう。", 0x5e463cb3, nil, nil, nil, 0xddc02048, ".mmm." },
  [5640] = { "Desperate Prayer", "StormwindのHigh Priest Rohanと話す。", "Eluneと、あなたの光に賛美を、{name}。\n\nこの頃になると、私たちの教団の多くの者はEluneへの信仰を映す能力を身につけます。私の知る限り、あなたの教団でも同じはずです。\n\nDarnassusでの用事が済んだら、私ならさらなる訓練のためにあなたの教団のHigh Priestを訪ねるでしょう。", nil, "よく来てくれました、{name}。話し合わねばならないことはたくさんありますが、それより大切なのは、光の道におけるあなたの修行です。\n\n光に仕える者が皆学ばねばならない教えがあります。準備ができているなら、今からそのいくつかについて話し始めましょう。", 0x5e463cb3, 0xa762cb1a, 0x62b6262b, nil, 0xddc02048, "...m." },
  [5641] = { "Chastise", nil, nil, nil, "お前には偉大な{class}になる素質があるぞ、{name}。その調子で頑張れ!\n\nお前はもう戦いの準備ができていることを示した。そろそろもう少し何か教えてやる頃合いかもしれんな。", 0xeabe5139, nil, nil, nil, 0xf71decf8, ".mmm." },
  [5642] = { "Shadowguard", "OrgrimmarのUr'kyoと話して下さい。", "Orgrimmarで何か大事なことが起きているようだ、{name}。\n\nトロールのプリーストを探してここを通る使者たちは、いつもならとてものんびりしている。今回は、ずっと急いでいる様子だった。Thunder Bluffでぐずぐずしないことだ。私ならできるだけ早くValley of Spiritsへ戻るね。", nil, "お前の儀式はすぐにやってくる。今は、敵と戦うときに大いに役立つ呪文を教えてやろう。", 0xcf44b409, 0x18d06dea, 0x1895999d, nil, 0xb615482e, "...m." },
  [5643] = { "Shadowguard", "OrgrimmarのUr'kyoと話して下さい。", "私たちのプリーストの多くと同じように、あなた自身の部族もあなたに通過儀礼を課します。こうした儀礼は、多くの場合、プリーストが生き延びるのに欠かせない特別な能力を教えるものです。今こうして話している間にも、その時があなたに迫っているのを感じます。OrgrimmarのValley of Spiritsへ戻り、Ur'kyoと話さなければなりません。彼が教えることは、あなたの未来にとってとても大切なものになるかもしれません。", nil, "お前の儀式はすぐにやってくる。今は、敵と戦うときに大いに役立つ呪文を教えてやろう。", 0xcf44b409, 0x18d06dea, 0x9bb6868b, nil, 0xb615482e, "...m." },
  [5644] = { "Dark Sacrifice", "UndercityのAelthalysteと話して下さい。", "ああ、あなたにとって素晴らしい日ですね、{name}。あなたが学んできた教えを見れば、Aelthalysteのもとへあなたを送り返す時が来たことが分かります。彼女にしか教えられないことがあるのです。それも、あなたがふさわしいと証明できればの話ですが。\n\n驚きを台無しにするつもりはありませんが、私も若いプリーストだった頃、真の力……神聖な力について学んだ時のことを覚えています。ええ、あの頃は良かった。\n\nUndercityのAelthalysteのもとへ戻りなさい、{name}。彼女はWar Quarterであなたを待っているでしょう。", nil, "準備ができていると思うなら、Devouring Plagueを教えてやろう、{name}。少なからぬ力を持つ呪文で、これからの戦いでお前の助けとなるだろう。練習しておけ。後で試練があるぞ。", 0x122ac7ca, 0x53641243, 0x1085ab93, nil, 0xec1eed23, "...m." },
  [5645] = { "Chastise", "IronforgeのHigh Priest Rohanと話して下さい。", "{name}、あなたの同胞のHigh Priest RohanがIronforgeであなたとの面会を望んでいます。急いでください、我が強き友よ。次の試練がすぐそこに迫っています。あなたの種族独自の儀式に立ち会えればと思いますが、私の居場所はここなのです。ですが、旅路に光があなたと共にありますように。あなたが町に着く頃にも、RohanはまだMystic Wardにいるはずです。彼は待っていますよ。", nil, "よく来たな、{name}。我らの種族は誇り高く強い。そろそろお前自身がそうあるだけでなく、他の者にもそのような感情と自信を呼び起こすことを学ぶ時だ。準備はいいか、若いの?", 0xeabe5139, 0x18755abb, 0x7c851f5d, nil, 0x2f8ef86f, "...m." },
  [5646] = { "闇の生贄", "UndercityのAelthalysteと話す。", "Aelthalysteは、うちらの仲間をもっと修行させるために俺のとこへ送り返してくれて、うちらの民に大きな敬意を示してくれた。だから今度は、俺も彼女の一族に同じことをするんだ。\n\nお前はUndercityへ戻れ、{name}。そこのWar Quarterで、彼女がお前の民とそのやり方についてもっと教える準備をして待ってる。そこへ行け、ぐずぐずするなよ。", nil, "よし、戻ってきたな。ちょうどいい時だ。話すべき大事なことがある、{name}。お前の能力は強くなってきている。準備ができているか確かめねばならん。", 0x122ac7ca, 0x53641243, 0xbaba2cb5, nil, 0x7346e69e, "...m." },
  [5647] = { "Chastise", "IronforgeのHigh Priest Rohanと話して下さい。", "あなたの種族は本当に強いですね、{name}。あなたたちを同盟者と呼べることを誇りに思います。そして日ごとに太陽が沈むたび、あなたとあなたの同胞は、自らの真の起源を見つけることに近づくだけでなく、多くのことにおいて正しい道を歩んでいるという大きな確信を得ていくのです。その思いは、きっとあなたに大きな達成感を与えていることでしょう。\n\nつい先ほど、Ironforgeから知らせが届きました。あなたにそちらへ戻り、Mystic WardのHigh Priest Rohanと話してほしいとのことです。彼を待たせないほうがよいでしょう。Eluneがあなたの旅路を導きますように。", nil, "お前には偉大な{class}になる素質があるぞ、{name}。その調子で頑張れ!\n\n{name}、お前はもう戦いの準備ができていることを示した。そろそろもう少し何か教えてやる頃合いかもしれんな。", 0xeabe5139, 0x18755abb, 0x90bbdd69, nil, 0x3d1896c7, "...m." },
  [5648] = { "霊性の服", "Grunt Kor'jaを見つけて、Lesser Heal (Rank 2)を使って彼女の傷を回復して下さい。その後、彼女にPower Word: Fortitudeを与えて、Razor HillのTai'jinのところへ戻って下さい。", "最初の試練の準備はできてるな、{name}。Razor Hillの南、町を出てすぐのところで、俺たちの兵卒の一人がProudmooreの古い兵どもを追い払おうとして怪我をした。彼女、具合がよくねえ。俺たちの仲間の誰かが助けてやれば、ずいぶん楽になるだろう。彼女を見つけろ――名前はKor'jaだ――傷を癒して、祖先の祝福を与えてやれ。\n\nこれをやれば、お前が俺たちの道で先へ進む準備ができた十分な証になると思うぜ。", "癒しの魔法が強力なのは当然だと、たいていの奴は思ってる。だが、どれほど強力かを分かってる奴は多くない。本来なら先祖に会いに行くはずの者を、たくさん生かしておけるんだ。この癒しの魔法とFortitudeの力を合わせれば、とても強力な呪文の組み合わせになる。これを覚えておけ。あらゆる者の役に立つ。ウォリアーにメイジ、その間の誰にでもな。", "よし、これでKor'jaは生き延び、あの悪意ある人間どもから我らの町を守りに行く。俺はよく戦の日々を思い出したくなる。力が戦いで示され、ただ力に頼る者を打ち倒すのはたいてい賢い者だった、あの日々をな。\n\nお前はよくやってくれた、{name}。さあ、このローブを取れ。役に立つかもしれんし、気にもしないかもしれん。だがお前はこれを勝ち取ったんだ。お前を同胞と呼べることを誇りに思うぞ。", 0x593c5783, 0x24940db1, 0xa91befae, 0xb96c37f7, 0xec880bcf, ".....", nil, nil, nil, nil, 0x54dfafd6 },
  [5649] = { "霊性の味方", "DurotarのTai'jinと話して下さい。", "ああ、そうさ。俺たちの一族がHordeに加わったのは、Hordeが俺たちのためになるからだ。あいつらは忠実だし、名誉みてえなことをたくさん教えてくれる。だが古いやり方はなかなか消えねえ。オークどもは俺たちの伝統を全部は認めねえかもしれねえが、だからって、そのいくつかを密かに続けちゃいけねえってわけじゃない。\n\nお前もそれを分かってる。だからRazor HillのTai'jinのところへお前を行かせるんだ。彼女が俺たちの歴史をもっと教えてくれる。俺たちの部族のやり方を教えてくれる。準備ができたら彼女のところへ行け。", nil, "ああ……ついにTai'jinのところへ来たか。そいつはいい。\n\nお前ももう知っているだろう、俺たちはかつてHordeに加わったあの同じ部族ではない。今の俺たちはずっと強い。適応したから強いんだ。Hordeがそれだけは教えてくれた。俺たちはもう敵を倒してそこから力を得るのではない。今は力を得て、それから敵を倒すのだ。\n\n違いはわずかだが、お前にも分かるようになる。いずれ分かる。部族はお前がそういうことを学ぶのを当てにしているんだ。", 0xced31293, 0x4eafa33b, 0x93255826, nil, 0x1aa9d73f, "...m." },
  [5650] = { "闇の服", "Deathguard Kelを見つけて、Lesser Heal (Rank 2)を使って彼の傷を回復して下さい。その後、彼にPower Word: Fortitudeを与えて、BrillのDark Cleric Berylのところへ戻って下さい。", "我らの力は闇と影から来るものだ、{name}。だが、それがお前の唯一の役割ではない。お前は癒しの術を知ることに価値があると認めた。賢明なことだ。だが闇を知る前に、光も知らねばならない。そのために、お前に試練を与えよう。\n\n墓地の北に、負傷したDeathguard――Deathguard Kelがいる。彼はしばらくの間、gnollsから我らを守ってきたが、治療が必要だ。そして任務に戻る前に、彼の体を強化してやらねばならない。呪文で両方を行い、私のもとへ戻れ。", "我々の力は、実に多くの状況で理想的なものです、{name}。ですが、何があろうと、傷を癒し、仲間が耐えられるダメージを増やす力こそが、我々の持つ才能の中で常に最も求められるものだと分かるでしょう。だからといって、{class}として別の道を追い求めることをためらう必要はありません。あなたはさまざまな形で力を発揮できます。ですが……魔法の力で本当に敵を滅ぼしたいのなら、秘術のほうがあなたの好みに合っているかもしれませんね。", "お前は難なく我が試練を乗り越えた。よろしい。\n\nまもなくお前は、より重い責務を担う備えができるだろう。そしてその道は、より暗い力へと通じている。他の種族のどの{class}も持たぬ力へとな。\n\nこのローブを、お前の地位の証として受け取れ。お前はそれに値する。着たくないのであれば、それならそれでいい。好きなようにするがいい。私も、私と同じ者たちも、お前が我らの中で成し遂げたことを、いつでも認めるだろう。", 0x0c6d0bd3, 0x723fbde5, 0xfaa3d69d, 0x6343c5d5, 0x458cdd4e, "....." },
  [5651] = { "闇の味方", "Tirisfal GladesのDark Cleric Berylに話しかけて下さい。", "Forsakenが経験を通して学んだ教訓は数多い――他の種族には推し量ることすら難しいものだ。我らの道は闇の中にあるが、多くのものが光と闇の両方に拠っていることに気づくだろう。お前の修練は、その両方を――分別をもって――使うことを教えるはずだ。だが我が言葉を心に留めよ。我らが堕落の中で鍛えられ、腐肉のように朽ちるに任せられたことを決して忘れるな。Darknessこそが我らの故郷なのだ。\n\nさらに学ぶ準備ができたら、BrillのDark Cleric Berylを訪ねよ。", nil, "ついに、来たか。信仰だけでは、目の前にある試練を切り抜けることはできぬぞ、若いの。危機感と少しの野望とが助けになろう。", 0xe676d3d4, 0x47392945, 0xb16687db, nil, 0x3481d16c, "...m." },
  [5652] = { "Hex of Weakness", nil, nil, nil, "この教えにはよく耳を傾けるがいい、若いの。Hex of Weaknessは戦いでお前の大きな助けとなるだろう。後で、お前がさらに成長し、部族にその価値を示すための試練を用意してやる。", 0x7764cf64, nil, nil, nil, 0x1c4616e4, ".mmm." },
  [5654] = { "Hex of Weakness", "OrgrimmarのUr'kyoと話す。", "Ur'kyoに会う時が来たぞ、{name}。あいつはオークの都のValley of Spiritsにいる。そこへ行って、あいつと話せ。お前がうちらの種族の古いやり方をもっと学ぶ時が来たんだ。お前が輪の中に迎え入れられ、うちらの部族の真のプリーストになる時が来たんだ。", nil, "この教えにはよく耳を傾けるがいい、若いの。Hex of Weaknessは戦いでお前の大きな助けとなるだろう。後で、お前がさらに成長し、部族にその価値を示すための試練を用意してやる。", 0x7764cf64, 0x18d06dea, 0xd2e2bae7, nil, 0x1c4616e4, "...m." },
  [5655] = { "Hex of Weakness", "OrgrimmarのUr'kyoと話す。", "お前が故郷から遠くへさまよい出すぎないよう、俺はここへ送られた、{name}。うちらのプリーストの中で一番偉いUr'kyoがお前と話したいから、お前を故郷へ帰らせろと言われて来たんだ。お前、そこへ行け。オークの都のValley of Spiritsへ行って、Ur'kyoと話せ。あいつは今お前を待ってる。", nil, "この教えにはよく耳を傾けるがいい、若いの。Hex of Weaknessは戦いでお前の大きな助けとなるだろう。後で、お前がさらに成長し、部族にその価値を示すための試練を用意してやる。", 0x7764cf64, 0x18d06dea, 0x16e5e011, nil, 0x1c4616e4, "...m." },
  [5656] = { "Hex of Weakness", "OrgrimmarのUr'kyoと話して下さい。", "あらゆる文化のプリーストたちが世界を旅するのを見ると、この不死の心がいつも温まる。秘術ではない力が存在し、それが我々の手の届くところにあると知るのはな。だからこそ、お前を故郷へ導くのは私の名誉なのだ、{name}。\n\nOrgrimmarにいるお前たちの偉大なプリースト、Ur'kyoがお前を呼んでいる。彼はValley of Spiritsにいる。", nil, "この教えにはよく耳を傾けるがいい、若いの。Hex of Weaknessは戦いでお前の大きな助けとなるだろう。後で、お前がさらに成長し、部族にその価値を示すための試練を用意してやる。", 0x7764cf64, 0x18d06dea, 0xd7057125, nil, 0x1c4616e4, "...m." },
  [5657] = { "Hex of Weakness", "OrgrimmarのUr'kyoと話す。", "故郷へ。故郷へ帰るのだ、若き{race}よ。\n\nそなたの霊的指導者Ur'kyoが、そなたが歩む道について語るため、戻ってきてほしいと切に願っている。\n\nHordeの大いなる都Orgrimmarにある、Valley of Spiritsへ行くがよい。彼はそこにいる。", nil, "この教えにはよく耳を傾けるがいい、若いの。Hex of Weaknessは戦いでお前の大きな助けとなるだろう。後で、お前がさらに成長し、部族にその価値を示すための試練を用意してやる。", 0x7764cf64, 0x18d06dea, 0x62ef2561, nil, 0x1c4616e4, "...m." },
  [5658] = { "Touch of Weakness", nil, nil, nil, "ああ、若き{class}よ、ここに戻ってきてくれて嬉しいぞ。忘れないほうがいい教えを授けてやろう。準備はいいか?", 0xdccff772, nil, nil, nil, 0xb566d701, ".mmm." },
  [5659] = { "Touch of Weakness", "UndercityのAelthalysteと話して下さい。", "ここはお前のいるべき場所ではない、{name}。できるだけ早くUndercityのWar Quarterへ向かうことだ。Aelthalysteは、準備の整ったプリーストと女性のプリーストたちを皆そこへ呼び集めている。自らの力についてさらに学び、それをどう使いこなすかを知る時が来たのだ。\n\n彼女は遅刻も言い訳も許さない。さっさと向かったほうがいいぞ。", nil, "ああ、よし、また一人来たか。我にとって時は重要でないかもしれぬが、そなたにとっては肝要だ。そなたが学ぶべきことは多く、我が教えたいことも多い。そなたはただ、自らの価値を示せばよい。そうすれば、大いに報われるであろう。", 0xdccff772, 0x53641243, 0x37d54005, nil, 0xb886b0c3, "...m." },
  [5660] = { "Touch of Weakness", "UndercityのAelthalysteと話す。", "お前、故郷から遠く離れてるな、{class}。お前はあっちで必要とされてる、地の下にあるお前の都でな。お前の師匠、お前らがAelthalysteって呼んでるお方が、お前に戻ってきてほしがってる。俺の部族と同じで、あのお方からしか学べないことがあるんだ。ここに長居するなよ。ツェッペリンが運べるかぎりの速さでWar Quarterへ向かうべきだ。", nil, "ああ、よし、また一人来たか。我にとって時は重要でないかもしれぬが、そなたにとっては肝要だ。そなたが学ぶべきことは多く、我が教えたいことも多い。そなたはただ、自らの価値を示せばよい。そうすれば、大いに報われるであろう。", 0xdccff772, 0x53641243, 0xc634bef2, nil, 0xb886b0c3, "...m." },
  [5661] = { "Touch of Weakness", "UndercityのAelthalysteと話す。", "Bloodhoof Villageのこんなところまで来るなんて、お前、故郷から遠く離れてるな、{name}。俺は自分の部族のプリーストを見つけて、指導者たちと話すよう送り返すためにここへ来たんだが、だからってお前を助けられないわけじゃない。\n\n聞いた話じゃ、お前らの女司祭長の霊が、Forsakenを皆自分のもとへ呼び寄せたがってるそうだ――お前には学ぶべきことがあるんだ。\n\nお前らの都のWar QuarterにいるAelthalysteに会いに行け。", nil, "ああ、よし、また一人来たか。我にとって時は重要でないかもしれぬが、そなたにとっては肝要だ。そなたが学ぶべきことは多く、我が教えたいことも多い。そなたはただ、自らの価値を示せばよい。そうすれば、大いに報われるであろう。", 0xdccff772, 0x53641243, 0xa906659b, nil, 0xb886b0c3, "...m." },
  [5662] = { "Touch of Weakness", "UndercityのAelthalysteと話す。", "あなたとあなたの種族に敬意を、{name}。私は普段、自分の部族の者にしか教えません。あなたの教えは、かつてLordaeronと呼ばれた都にいるAelthalysteから受けるものです。\n\n他の信仰とあなたを分かつ力を学ぶのなら、彼女のもとへ戻るべきでしょう。\n\nUndercityのWar Quarterへ行き、そこであなたの師匠を探してください。", nil, "ああ、よし、また一人来たか。我にとって時は重要でないかもしれぬが、そなたにとっては肝要だ。そなたが学ぶべきことは多く、我が教えたいことも多い。そなたはただ、自らの価値を示せばよい。そうすれば、大いに報われるであろう。", 0xdccff772, 0x53641243, 0x5fc0308e, nil, 0xb886b0c3, "...m." },
  [5663] = { "Touch of Weakness", "UndercityのAelthalysteと話す。", "Aelthalysteが自分の配下のプリースト全員に知らせを送った。我々の教団の若い者たちを、さらなる修行のためにUndercityへ向かわせろとのことだ。本当に自分を我らの信徒の一人と数えるのなら、お前もそこへ戻るべきだ。\n\nAelthalysteはUndercityの奥深く、War Quarterにいる。", nil, "ああ、よし、また一人来たか。我にとって時は重要でないかもしれぬが、そなたにとっては肝要だ。そなたが学ぶべきことは多く、我が教えたいことも多い。そなたはただ、自らの価値を示せばよい。そうすれば、大いに報われるであろう。", 0xdccff772, 0x53641243, 0xa2d072d4, nil, 0xb886b0c3, "...m." },
  [5672] = { "Elune's Grace", nil, nil, nil, "Eluneと私たちの民に身を捧げたことで、あなたは誰もが到達できるわけではない境地に至りました。その献身に対して、さらに大きな力を授けるのが習わしです。受け入れますか?", 0x2e456277, nil, nil, nil, 0x8f606a4d, ".mmm." },
  [5673] = { "Elune's Grace", "DarnassusのPriestess Alatheaと話して下さい。", "私たちのトレーナーにはいつでも会えることは知っていますね、{name}。ですが、あなたに伝えられないこともあるのです。その一つが、あなたの女神Eluneの教えです。彼女は忠実な者に特別な能力を授けます。私の思い違いでなければ、あなたが故郷のTemple of the Moonへ戻り、試練を受ける時が来たのです。\n\n戻れる時に戻って、Priestess Alatheaと話してください。", nil, "こんなにも早く戻ってきてくれたことに、Eluneの祝福がありますように。今はあなたの修行において大切な時期であり、私たちの教団の誰もが非常に真剣に受け止める時期です。ここまでの旅の疲れが癒えたら、どうか知らせてください。そのとき、修行の続きと、あなたの道が次にどこへ導くのかについて話し合いましょう。", 0x2e456277, 0x8f9be0c1, 0x8fb26a95, nil, 0xc3518a4a, "...m." },
  [5674] = { "Elune's Grace", "DarnassusのPriestess Alatheaと話して下さい。", "素晴らしい日がやってきましたね、{name}。あなたは、私たちのプリーストがナイトエルフだけが知る力の訓練を受ける年頃になりました。ですが、あなたを訓練するのは私の役目ではありません。ここでの用事が済んだら、すぐにTemple of the Moonへ戻り、Priestess Alatheaと話してください。彼女はあなたに準備ができているかを試し、そのうえで初めてElune's Graceを教えてくれるでしょう。", nil, "Eluneと私たちの民に身を捧げたことで、あなたは誰もが到達できるわけではない境地に至りました。その献身に対して、さらに大きな力を授けるのが習わしです。受け入れますか?", 0x2e456277, 0x8f9be0c1, 0xda81f573, nil, 0x8f606a4d, "...m.", nil, nil, 0x22b130fc, nil, nil },
  [5675] = { "Elune's Grace", "DarnassusのPriestess Alatheaと話して下さい。", "ぐずぐずしてる暇はないぞ、若いの。故郷のDarnassusへ帰る時だ。Priestess Alatheaから、訓練のためにあっちへ戻るようにって知らせが届いてる。どうやら、光に仕える者たちと同じように、お前も試される準備ができてると思われてるらしい。行けるようになったらすぐに出発するといい。Alatheaの知らせによると、Temple of the Moonで待ってるそうだ。幸運を祈るよ。", nil, "こんなにも早く戻ってきてくれたことに、Eluneの祝福がありますように。今はあなたの修行において大切な時期であり、私たちの教団の誰もが非常に真剣に受け止める時期です。ここまでの旅の疲れが癒えたら、どうか知らせてください。そのとき、修行の続きと、あなたの道が次にどこへ導くのかについて話し合いましょう。", 0x2e456277, 0x8f9be0c1, 0x45deec4a, nil, 0xc3518a4a, "...m.", nil, nil, 0x1de89d1d, nil, nil },
  [5676] = { "秘術のフィードバック", nil, nil, nil, "我々は、一般に我々の最大の敵と言われるもの、つまり秘術から身を守るため、ある種の魔法を学ばざるを得なかった。\n\nそのような力を振るう者たちから、あなた自身と仲間を守るための呪文を教えよう。", 0xa7b14275, nil, nil, nil, 0x34be78ad, ".mmm." },
  [5677] = { "秘術のフィードバック", "StormwindのHigh Priestess Laurenaと話して下さい。", "私たちの光の特別な教えをあなたに示したいのは山々ですが、それは私たちの役目ではありません。あなたの居場所は、同じ種族の仲間がいるStormwindです、{name}……今のところは。どうか悪く思わないでください。Cathedral of LightのHigh Priestess Laurenaのもとへ戻れば、私の言っていることが分かるでしょう――あなたの種族があなたに未来への備えをさせる時が来たのです。似た道を歩む他の者たちと、あなた自身を区別するために。", nil, "ああ、ちょうどいい時に来ましたね、{name}。私の使者たちが皆うまく役目を果たせたのか、気になり始めていたところです。果たせたようで何よりです。そうでなければ、あなたは今も世界のどこかで、私たちの民に迫るあらゆる脅威について学んでいたことでしょう。\n\n準備はできていますか? さらなる修行の準備ということです。あなたはますます早く力をつけています。私たちの信仰についてもっと学ぶ準備ができていると感じます。", 0xa7b14275, 0x8de762b6, 0x3d8f5891, nil, 0xa244b6c1, "...m." },
  [5678] = { "秘術のフィードバック", "StormwindのHigh Priestess Laurenaと話して下さい。", "Stormwindへ戻る時が来ました、若き者よ。向こうの上の者たちが、さらなる訓練のためにあなたを呼び戻しています。いささか心穏やかではありませんが、あなたの種族と私の種族は同盟を結んでおり、私はそれを裏切るつもりはありません。\n\nこうしてはぐらかすつもりはないのです――神の啓示によるものであろうとなかろうと、秘術の魔法への私の不信は、今も心の内に強く残っているのです。\n\nあなたのCathedral of Lightに戻れば、私の言っていることが分かるでしょう。着いたらHigh Priestess Laurenaと話してください。", nil, "ああ、ちょうどいい時に来ましたね、{name}。私の使者たちが皆うまく役目を果たせたのか、気になり始めていたところです。果たせたようで何よりです。そうでなければ、あなたは今も世界のどこかで、私たちの民に迫るあらゆる脅威について学んでいたことでしょう。\n\n準備はできていますか? さらなる修行の準備ということです。あなたはますます早く力をつけています。私たちの信仰についてもっと学ぶ準備ができていると感じます。", 0xa7b14275, 0x8de762b6, 0x4fe1c26d, nil, 0xa244b6c1, "...m." },
  [5679] = { "闇の生贄", nil, nil, nil, "準備ができていると思うなら、Devouring Plagueを教えてやろう、{name}。少なからぬ力を持つ呪文で、これからの戦いでお前の助けとなるだろう。練習しておけ。後で試練があるぞ。", 0x122ac7ca, nil, nil, nil, 0xec1eed23, ".mmm." },
  [5680] = { "Shadowguard", nil, nil, nil, "お前の儀式はすぐにやってくる。今は、敵と戦うときに大いに役立つ呪文を教えてやろう。", 0xcf44b409, nil, nil, nil, 0xb615482e, ".mmm." },
  [5713] = { "一撃必殺", "Sentinel Aynasha を保護し、Ashenvale にあるMaestra's Post で Onaeya と話す。", "重要な知らせを携えてAuberdineへ向かっていたところ、furbolgのMaroshとその追跡者たちに襲われました。その際に毒を受け、立っているのもやっとです。解毒剤は作れますが、完成までには時間がかかります。\n\n解毒剤を使えるようになるまで、私を守っていただけないでしょうか。私も弓でできる限り援護します。\n\n生き延びられたら、私はAuberdineへ知らせを届けます。あなたはMaestra's PostのOnaeyaに会って、この件を伝えてください。", "道中でSentinel Aynashaを見かけませんでしたか? 大切な任務に出たのですが、まだ戻っていないのです。", "{class} 、大変良い知らせですね。Aynasha があなたのお陰で無事だと分かって嬉しいですよ。その武勇に対する報酬を受け取って下さるようお願いします。女神 Elune があなたを見守り、道を照らして下さいますように。", 0xd9bcb0ad, 0xfd45a006, 0x550eea3f, 0xd79229bb, 0x5150e92b, "....." },
  [5721] = { "Darrowshireの戦い", "Darrowshireの町の広場にRelic Bundleを置く。\n\nHorgusが死ぬまで、Davil Lightfireを死なせないようにする。\n\nRedpath the Corruptedが現れるまで、Captain Redpathを死なせないようにする。\n\nRedpath the Corruptedを倒す。\n\nJoseph Redpathの霊が町の広場に現れたら話しかけ、その後、家にいるPamelaと話して下さい。", "さて、{name}、君はDarrowshireの戦いに加わり、Joseph Redpathを救うことになる。\n\nこのrelic bundleをDarrowshireの町の広場に置けば、Darrowshireの霊たちが蘇る。彼らの戦いに加わり、次の二つのことが必ず実現するようにしてくれ。DavilはHorgusの死の後も生き延びなければならない。そしてRedpathは生き延びて堕落し、その後で倒されなければならない。\n\n堕落したRedpathを倒せば、彼の魂は救われる。彼と話したら、娘のPamelaのところへ戻ってくれ。", "外で幽霊の声が聞こえた気がする。怖いことをささやいてくるんだよ……", "戦いは終わったよ! パパがささやくのが聞こえたの。パパが幽霊をみんな追い払って、おうちに帰ってくるって! すごく嬉しい!\n\nパパがね、あなたがおうちに来たらおもてなししなさいって言ってたから、お茶をいれたの!\n\nお砂糖たっぷりが好きだといいな!", 0x465f9818, 0xa130650b, 0x531b48de, 0x1af64862, 0x393b8b0b, "....." },
  [5722] = { "無くなった鞄の捜索", "Ragefire ChasmでMaur Grimtotemの死体を探し、何か興味深い物を探って下さい。", "MagathaがRagefire Chasmで関心を持っているのはtroggsだけではない。彼女の配下の一人、Maur Grimtotemが、Chasmの中で妙なものを見つけたという話を聞いたそうだ。だが彼は、それを彼女に見せるために外へ出てくることはなかった。彼女はMaurの遺体を――まだ残っていればだが――見つけてほしいと望んでいる。そしてtroggsと話をしようとしていた時に彼が見つけたものの手がかりもな。\n\n興味深い品があればMagathaに返してくれ。きっと彼女は気前よく報酬をくれるだろう。\n\nもう一度言うが、Orgrimmarの最も暗い場所でChasmを探すのだ。", nil, "遺体は棍棒か拳でひどく殴打されたように見えるが、衣服や装備のほとんどはまだ残っているようだ。troggどもは物質的な富にはさほど関心がないらしい。\n\nあなたはMagathaの助けになりそうなものを探して、遺体を調べ始める。", 0xb20112ea, 0xdde6ef18, 0x2bfed261, nil, 0x30cabc23, "...m." },
  [5723] = { "敵の力の検証", "OrgrimmarでRagefire Chasmを探し、Thunder BluffのRahauroのところへ戻る前に、Ragefire Trogg・Ragefire Shamanを8頭ずつ殺して下さい。", "Orgrimmarの街の下、溶岩に満ちたトンネルの深みから、troggsと呼ばれるずんぐりした生き物たちが地上に姿を現し始めた。常に慈悲深いMagathaは、その生き物たちと和平を結ぼうとしたが、奴らは彼女の使節に襲いかかり、殺してしまった。彼女はトーレンの民へのそのような仕打ちを許さず、今やこの生き物たちをHorde全体への脅威とみなしている。\n\n彼女は、このtroggの脅威が地下からHordeを飲み込む前に終わらせてほしいと願っている。Ragefire Chasmを見つけ出し、奴らを一匹残らず倒すのだ。", "Chasmの捜索はどうだ? それにtroggsは?\n\nこの脅威を放っておくわけにはいかない。このまま続けば、我らがオークの同胞が傷つくだけだ。", "Magathaの頼みを真剣に受け止めてくれたようで嬉しい。ありがとう、{name}。数がこれほど減らされたのだから、troggどもが地表へ出てくるのも難しくなるだろう。\n\nいつか、ああした生き物がどこから来たのか、本当は何を求めているのかを、時間をかけて突き止められるかもしれんな。", 0xabeb706b, 0xe0fdd528, 0xc3e7179e, 0x14a45315, 0xbc9a5ddc, "....." },
  [5724] = { "無くなった鞄の帰還", "Thunder BluffのRahauroのところへGrimtotem Satchelを持って行って下さい。", "トーレンの遺体の下から鞄が見つかる。まるでtroggsに襲われながらも守ろうとしていたかのように、それは今も彼の腕にしっかりと抱えられている。\n\n万力のように固く握られた手から鞄を取り外し、自分の荷物にしまう。そしてトンネルを抜け、Thunder BluffのRahauroのもとへ戻る支度をする。", "何か見つかったか、{name}? 彼女の一族の者がなぜ無駄に死なねばならなかったのか、手がかりがあれば助かる。", "見事だ、{name}。感謝する。\n\nMagathaが言っていた。お前が彼女の同族の者を見つけ出せたなら、これを渡すようにとな。どうか、礼として受け取ってくれ。", 0x78c3b168, 0x25ce5d81, 0xd0331193, 0x28b9b726, 0xbb8bccf5, "....." },
  [5725] = { "破壊する力……", "Spells of ShadowとIncantations from the Netherの二冊の本を、UndercityのVarimathrasのところへ持って行く。", "お前もよく知っているだろうが、Legionの住人の多くは、その信奉者に贈り物を授ける。そうした贈り物の中には、Dark Ladyがお考えになるに、その……先見の明に欠ける者どもの手にあるより、あのお方の手にあったほうがよいものもあるのだ。\n\nOrgrimmarの地下の洞窟に潜むShadow Councilの一派、Searing Bladeと呼ばれる者どもがその格好の例だ。奥方の仰せでは、Searing Bladeの者どもが強力な呪文書を2冊手に入れたという――あのお方はその本を奴らから「お借り」したいとお望みだ。お前がそれを取ってくるのだ。", "私が片付けねばならない仕事は、ほかに100はあるのだ、{class}。本は持ってきたか?", "よし、{class}。Dark Ladyによく仕えたな。お前の変わらぬ忍耐と野心は、奥方の臣民にとって大いに役立つだろう。いずれまた私のもとへ戻ってこい。Dark LadyがLich Kingを打倒しScourgeを完全に解き放とうとする企てを助ける、別の任務があるかもしれん。", 0x78248aca, 0x81a2cc99, 0x7d48c15d, 0x97d5fe7b, 0x24c68998, "....." },
  [5726] = { "隠れた敵", "Lieutenant's InsigniaをOrgrimmarにいるThrallへ持っていってください。", "私が許すつもりが無いものは、我らの中にいる裏切り者だ、{name}よ。しかしそんなに早く手の内を見せるのは愚か者のすることだ。それは我らの土地から十分に腐敗を取り除かない上、感染がより悪くなる原因になるだけだ。\n\nしかしお前のような若き冒険者は、方々へ行くことができたが、私のエージェントはそれができなかった・・・真実を知ることができれば・・・残忍な奴等の本当の首領を見つけられるかもしれん。\n\nもし十分に勇気があるならば、Orgrimmarの東にあるSkull Rockに潜入し、そこでBurning Bladeの1人からLieutenant's Insigniaを見つけてくるのだ。そして、私のもとに戻ってきてくれ。", "記章はもう手に入れたか、{name}?\n\nそれは、Hordeにとって最大の脅威だと私が考える者たちに潜入し、ついに我らの新たな故郷に平和をもたらすための、欠かせない道具となる。\n\n強欲と権力に突き動かされたとき、人間もオークも、どれほど入り組んだ謀略の網を張り巡らせるものか、お前は知ることになるだろう。隠された企み、腐敗、そのすべてが明らかになる。存在すら知らなかった戦争のただ中に、お前は身を置くことになるのだ。", "いいぞ、{name}！精霊達に賞賛あれ、おそらく、最終的に私の最大の恐れを解決する者がお前なのだ！とても若く、そして勇敢な誰かが立ち上がり我々の目的を守ると誰が思っただろうか？ お前は私が若かった頃を思いださせてくれる。我らが両方とも来るべき嵐を生き延びるなら、私はお前の功績に対して正当な報酬を与えることを保証するよ。\n\nしかし後でもっと賞賛する時間がある。お前は自分が直面していることに対してまだ何も解決してはいない・・・しかしこれは好調なスタートだ。", 0x2986cf2d, 0xf540a6c4, 0xe4b83f85, 0x571977d8, 0x78e53150, "....." },
  [5727] = { "隠れた敵", "Lieutenant's InsigniaをNeeru Firebladeに持っていき、彼に話してください。彼があなたがBurning Bladeのメンバーであると思っているかどうか判断してください。その後、OrgrimmarのThrallのところに戻ってください。", "今からお前が見つけたこの記章が努力してみる価値があるかどうか見よう。\n\n私に信頼されていると考えているウォーロックが街にいる。奴は、私が奴の真の忠誠がどこにあるかについて気付いていることを知らない。奴は事実、Burning Bladeのリーダーだ。しかし奴との戦いを急がないでくれ。奴には目的がある。そして我々は敵に対して奴を利用するつもりなのだ。\n\nこの記章を、ここOrgrimmarの中のCleft of Shadowにいる彼に持っていってくれ。奴と話し、お前が奴の一味であると信じているかどうかを調べるのだ。その後ここに戻ってきてくれ。", "どうだ、{class}? あの者は我々の策略を信じたか、それとも事態は私が当初見積もっていたより悪いのか?\n\nNeeruにとって役に立つ存在だと示せば、Shadow Councilへの潜入はずっと容易になる。奴は、Durotarで我々が築き上げたすべてを破壊しようとする者どもを炙り出すのに使える情報を、たっぷり持っているはずだ。", "素晴らしい！本当に素晴らしいぞ、{class}！\n\nお前が今日やったことは、最終的にShadow Councilを壊滅させるという地盤を大きく広げる為の第一歩に過ぎない。\n\n奴が言ったことを全て私に教えてくれ・・・一字一句逃さずに。お前が思ってるより重要なことかもしれないからな。", 0x2986cf2d, 0xe4533834, 0x24cbb4fb, 0xba3db556, 0xb0896349, "....." },
  [5728] = { "隠れた敵", "OrgrimmarのThrallのところへ戻る前にBazzalanとJergosh the Invokerを殺してください。", "ふむ、Searing Bladeの指導者たちか……これが一番気がかりだ。Neeruにとって価値があるのがそいつらなら、真っ先に狙うべきはそいつらだ。このsatyr……Bazzalanと、Neeruが口にしたもう一人――何と言ったか、ウォーロックだったか？――は殺さねばならん。\n\nCleft of Shadowへ戻り、Ragefire Chasmに入れ、{name}。Searing Bladeのその2人の指導者を見つけ出し、殺せ。だが、やったのがお前だとNeeruに知られぬよう気をつけろ。お前は奴の戦友のひとりとして素性を保たねばならん。", "もう見つけたか、{name}? Searing Bladeの指導者どもを。\n\nShadow CouncilがOrgrimmarとHordeのすべてを私から奪おうとしていることは分かっていた。だが、奴らがこれほど早く街に潜り込めるとは思っていなかった。この獣には腕がいくつもある……疲れ果てるまで切り落とし続けても、始めた時から一歩も進んではいないだろう。密偵たちには倍の働きをさせねばなるまい。", "戻ってきてくれて嬉しいぞ、{name}よ。奴らのリーダーが殺された今、すぐに私に忠実な者の数人が、Orgrimmarの下の洞穴が混乱していたという知らせを持ってきたぞ。Neeruがひどく動揺しているという報告さえ受けたぞ。奴の鎧を我々がヘコませてやったわけだな。小さな勝利だが喜ばずにはいられないな。", 0x2986cf2d, 0x26287695, 0x4c1cc792, 0xe00697f8, 0xa356a80b, ".....", nil, nil, 0x052ec95d, nil, nil },
  [5729] = { "隠れた敵", "OrgrimmarにいるNeeru Firebladeに話してください。", "私は次のステップとして、お前がNeeruに近づくべきと考えている。レポートが示しているのと同じように奴が動揺しているならば、我らは2つのことを達成するかもしれん。1つはお前が組織について、いやもっと正確にはBurning Bladeについてのいくつかの大きな知識を得られるかもしれないということ。そして2つめは、奴がお前を十分に信用して、手助けを依頼し始めるかもしれないということだ。指導者のいくらかが混乱にある中、その穴を埋める人物としてお前を良く見ているかもしれんからな。\n\nthe Cleftに戻り、奴ともう一度会話するのだ。しかしあまりあからさまに振舞わないでくれよ。", nil, "これは何だ？！おぉ、お前か、{class}・・・すまない。私の怒りは凶暴なkodoのそれに匹敵する・・・しかしおそらく、それは私自身の欠点だな。旅人をRagefire Chasmに送る際には、それによっていくらかの損害がでる可能性を知るべきだった。BazzalanとJergoshの両方とも、知らないうちにThrallのおせっかい焼き数人によって殺されたようだ。最も都合の悪い時だが、今のところそれについてできることは何もないな。", 0x2986cf2d, 0x5fcb03d8, 0x09dd73b2, nil, 0x73f8739b, "...m." },
  [5730] = { "隠れた敵", "OrgrimmarのThrallに話し、あなたが聞いたことを彼に伝えてください。", "お前は私の副官の1人だ！準備をするんだ{class}、私はすぐにお前を呼ぶぞ。\n\nSearing Bladeで過ごしてきた時間は今、ほとんど無駄になったかもしれんが、それはShadow Councilの計画が不利になるということではないぞ。私はここRagefire Chasmでの損害を最小限にするためにできることをするつもりだ。その一方で、BarrensとAshenvaleにいる私のエージェントが我々の最新の計画を実行に移し始めるだろう。すぐに私のところに戻ってくるんだぞ。", nil, "Ashenvaleだと？うぅむ、AshenvaleにおけるBurning Bladeや組織の存在について何も耳にしたことがなかったな。私のスパイが調査するだろう、{name}。お前は上手くやってくれた。\n\n今は休んでくれ。そして他の仕事にでも専念しておいてくれ。またいずれお前を呼ぶことになるだろう。\n\n力と名誉を！", 0x2986cf2d, 0x8298346a, 0x8a8d0a1a, nil, 0x53caf27f, "...m." },
  [5741] = { "Sceptre of Light", "Sceptre of Lightを手に入れ、Ethel Rethorの塔にいるAzore Aldamortのところへ持って帰って下さい。", "東のThunder Axe FortressにいるBurning Bladeが、NagaからSceptre of Lightを手に入れたという噂がある。伝説によれば、その笏は大海の底に都市をまるごと沈めることができるという。Burning Bladeにそのような力を持たせてはならない。\n\nそのために、君自身がその笏を取り戻さねばならない！笏はBurning Bladeの予見者が持っていて、Thunder Axeの見張り塔の一つの上で笏を研究している。", "Sceptre of Lightは持っているか?", "とらえどころのないSceptre of Lightだ! これを手に入れたことで、世界への重大な脅威が取り除かれた。よくやった、{class}、本当によくやった。", 0x50a7d789, 0x5315a126, 0xfea822cf, 0x818ecd10, 0xbc6ea27a, "....." },
  [5742] = { "贖罪", "Tirion Fordringの語ることを聞いて下さい。", "友よ、君は一生懸命に働いてくれた。一息いれてくれ、私に自己紹介させてほしい。", "どうか、友よ。座って私の話を聞いてくれ。", "Fordring家の贖罪は難しい仕事となろう。準備はできたかな?", 0x6cd36c83, 0x305ddac0, 0xa072e495, 0x0d71b4cb, 0x7a51c30b, "....." },
  [5761] = { "悪魔征伐", "Ragefire Chasmに入ってTaragaman the Hungererを倒し、その心臓をOrgrimmarのNeeru Firebladeに届けて下さい。", "偉大なる大族長から私に課せられた最も重要な任務は、我らが主の偉大なる都に悪魔の影響をはびこらせている者どもを根絶やしにすることだ。Burning Bladeは脅威の一つにすぎず、ほかにもいる。たとえばSearing Bladeだ。奴らはRagefire Chasmを根城とし、Hordeの罪なき者たちをひそかに堕落させようとしている。\n\n奴らを止めるには、その首領を殺さねばならない――Taragaman the Hungererという名のFelguardだ。\n\n奴を殺せ。その心臓はThrallを満足させるであろう。私はそう確信している。", "あの獣は倒したか? 奴こそRagefire ChasmにいるSearing Bladeの指導者に違いない。", "はっ！　成し遂げたのか。Thrallは喜ぶだろう。\n\nこの心臓は責任を持って取り扱おう。\n\n今のところは、お前の勝利を祝うべきだろう。Thrallにお前の成功を知らせよう。\n\nお前の助力に感謝するぞ、{class}。", 0x873710b1, 0xb103966d, 0x36988aea, 0x4914afb3, 0x5847a03e, "....." },
  [5762] = { "Hemet Nesingwary", "StranglethornのHemet NesingwaryのところへKravel's Crateを持って行って下さい。", "昔の客に宛てた荷物があるんだ。Hemet Nesingwaryっていうドワーフさ。荷物が届くまでに何週間もかかって、Hemetはとっくにいなくなっちまった。Stranglethornへ行ってそこの獣を狩るって言ってたけど、届けられるようになったら送ってくれって、金を置いていったんだよ。\n\nHemetは金持ちのドワーフだし、金持ちとは良い関係を保っておくのが得策だろ？ それで……あんた、この荷物を届けてくれないか？\n\nHemetはStranglethornのGrom'golの北に野営地を構えてるって聞いたよ。", "襟についてるのは砂漠の砂ぼこりかい?\n\nふむ……俺の鼻が確かなら、そいつは砂ぼこりじゃない、砂漠の塩だな! Shimmering Flatsに行ってきたんだろ?", "素晴らしい。Koalbeardからの小包だ! ありがとう{name}。この木箱の中には、特殊口径の銃弾が入っているんだ。ジャングルの中で役立つよ!\n\nこれは代金だよ。それと、教えてくれ。気難しいKravel老人は最近どうしてる? どうせ悪巧みばっかりしてるんだろうけど……", 0xe0d7815a, 0x404d2976, 0x2bdcc27d, 0xc54cf9e3, 0x5e499535, "....." },
  [5763] = { "Stranglethornでの狩り", "Roon's Kodo HornをStranglethornのHemet Nesingwaryのところへ持って行って下さい。", "遠い昔、一人のドワーフがこの地にやって来た。名をHemetといい、大きな獣を狩ることを望んでいた。彼のライフルの腕前は並外れていて、我々は幾日も共に狩りをした。我らの種族の間にある敵意さえ忘れられていた。\n\n彼がDesolaceを去ってStranglethornへ向かった時、私はいつか彼を再び迎え入れ、また共に狩りをしようと誓った。今こそその時だ。\n\nこのkodo hornをHemetのもとへ持って行ってくれ。私からのものだと彼には分かるはずだ。彼はStranglethornの、Grom'gol Baseの野営地の北にいる。", "座れ、{class}。じきにまたジャングルへ打って出ることになる。", "ああ、このhornはトーレンのRoon Wildmaneのものだな。彼とはDesolaceの獣を狩って楽しい時を過ごしたもんだ。それで、Roonが俺をまた呼んでいるってわけか?\n\n今は密林にどっぷり浸かっているところだが、ありがとう、{name}。次の遠征ではDesolace、centaursの地に戻るかもしれんな。", 0x4f9db5c4, 0x56715844, 0x7dbb31ff, 0x951011b7, 0x254429ff, "....." },
  [5781] = { "忘れられた思い出について", "Undercroft(Eastern Plaguelandsの最南端)へ向かい、Taelan's Hammerを取り戻して下さい。目的を達成したらTirion Fordringのところへ戻って下さい。", "Taelanが失ったものを取り戻す手助けをするには、彼の過去にまつわる品を集めねばならない。\n\nその最初の品は、私が彼の7歳の誕生日に贈ったおもちゃだ。それは彼の最も大切な宝物だった。小さなウォーハンマー。私自身のものを正確に模したものだ。\n\n私が反逆罪で追放された後、彼の母は私が死んだと彼に告げた。彼はUndercroftにある私の偽りの墓へ連れて行かれ、そこで私の記憶とともにハンマーを埋めたのだ――永遠に。\n\nUndercroftへ赴き、Taelan's hammerを取り戻してくれ。", "彼は救われねばならぬ。", "<Tirionが涙をこらえて瞬きをする。>\n\n我らが出会ったのは運命だったのだ、{name}。そなたの優しさが私を祝福してくれた。", 0x1d992727, 0xbd7cdebd, 0x537bd35c, 0x15f5081b, 0x9741ab3c, "....." },
  [5801] = { "Fire Plumeで鍛えしもの", "Skeleton Key MoldとThorium Barsを$N1個、Un'Goro CraterのFire Plume Ridgeの頂上へ持って行く。溶岩の湖のそばでSkeleton Key Moldを使い、Unfinished Skeleton Keyを鍛え上げる。\n\nUnfinished Skeleton KeyをWestern PlaguelandsのChillwind PointにいるAlchemist Arbingtonのところへ持って行って下さい。", "鍵の軸を鍛えるには、thoriumの延べ棒が二本と、ものすごく熱い熱源が必要だ。thoriumは自分でなんとかしてもらうしかないが、熱のほうは手を貸せる。\n\nここから西のUn'Goro CraterにFire Plume Ridgeがある――ぐつぐつ煮えたぎる火山だ。頂上の溶岩湖は、thoriumと骨を溶かし合わせるのに十分な熱さだ。君の金で手に入れたこの鋳型は、頂上の湖に浸すだけでいい。あとは溶岩がやってくれる。\n\nこっちでできるのはここまでだ。鍵を仕上げるには、もう一度Arbingtonと話す必要がある。", "skeletal keyの軸は仕上がったか? 鋳型を買う費用を君に負わせてしまったのはすまないが、Scourgeに対抗するには、皆がそれぞれの役目を果たさねばならない。未完成の鍵を渡してくれれば、完成に必要な最後の品に取りかかれる。\n\n決して楽ではないだろうが、Andorhal攻撃に備えて君がこれまでしてきた働きが、これから報われ始める。今に分かるさ。", "なかなか高くついたskeleton keyだな、{name}? それでもまだ未完成だ。いよいよ我々の作品に力を注ぐ時が来た。そのためには、Andorhalで我々が立ち向かおうとしてきた究極の敵……廃墟となった街の城壁の内側を牛耳る邪悪な存在と対決してもらわねばならない。\n\nAraj the Summonerのことだ。lichであり、Scourgeが従える最も強力な存在の1つだ。", 0x83cc7eb7, 0xb716db0d, 0xfbf7c301, 0x54794b91, 0xa5094d5a, "....." },
  [5802] = { "火柱での鋳造", "Skeleton Key MoldとThorium Barsを$N1個、Un'Goro CraterのFire Plume Ridgeの頂上へ持って行く。溶岩湖のそばでSkeleton Key Moldを使い、Unfinished Skeleton Keyを鍛える。\n\nUnfinished Skeleton KeyをWestern Plaguelands、BulwarkのApothecary Dithersのところへ持って行って下さい。", "鍵の軸を鍛えるには、thoriumの延べ棒2本と、強烈に熱い熱源が必要だ。thoriumは自分で何とかしてもらうが、熱のほうは手を貸せる。\n\nここから西のUn'Goro CraterにFire Plume Ridgeがある――煮えたぎる火山だ。頂上の溶岩湖はthoriumと骨を溶かし合わせるほど熱い。あんたの金で型を買ったんだ。頂上の湖に浸けるだけでいい。あとは溶岩がやってくれる。\n\n俺の方はこれで終わりだ。鍵を仕上げるには、またDithersと話す必要があるぞ。", "skeletal keyの軸はできたか? moldを買う代金を君に負担させてしまったのは本当に申し訳ない。だが、Scourgeに対抗するためには皆がそれぞれの役目を果たさねばならんのだ。unfinished keyを渡してくれれば、完成に必要な最後の品に取りかかれるぞ。\n\n決して簡単ではないだろう。だが、Andorhalへの攻撃に備えて君がこれまでやってきた仕事が、これから報われ始める。見ていろ。", "ずいぶんと値の張るskeleton keyができたものだな、{name}? とはいえ、まだ未完成だ。そろそろ我々の作品に本腰を入れるときが来た。そのためには、Andorhalで対峙すべく我々が備えを進めてきた究極の敵と向き合わねばならん……あの廃墟の市壁の内側を取り仕切っている存在とだ。\n\n私が言っているのはAraj the Summonerのことだ。lichであり、Scourgeが自らのものと呼ぶ存在の中でも最も強力な者の一人だ。", 0x83cc7eb7, 0x15f08d20, 0x27820a2f, 0x5ca18687, 0xa2278f31, "....." },
  [5803] = { "Araj's Scarab", "Araj the Summonerを倒し、Araj's ScarabをWestern PlaguelandsのChillwind PointにいるAlchemist Arbingtonのところへ持って行って下さい。", "Araj the Summonerは、廃墟と化した街の中心からAndorhalを支配している。奴はこの街を我が物とする前は、Scholomanceのかつての指導者だったことが分かっている。鍵を完成させるには、奴の印章――scarabと呼ばれるもの――を鍵の頭として取り付ける必要がある。\n\nAndorhalの中心部へ向かい、奴が表に引きずり出された今こそ、街への支配を打ち砕くのだ。奴を倒したら、倒れた経箱からscarabを奪い取れ！\n\nKey to Scholomanceがあなたを待っている、{name}！", "ここまで来たのだ、{name}。Araj the Summonerの肉体を滅ぼすことでしか、鍵を完成させる手段は得られない。どんな手を使ってもいいからAraj's scarabを手に入れて、私のところへ持ってきてくれ。それを鍵の頭として融合させる。", "そう、これだ! 私は……またしても、君の英雄的行為の深さには本当に驚かされる。闇の勢力に勝利するために、君がどこまでも身を投じる覚悟には、まったく圧倒されるよ。\n\nでは、私もささやかな役割を果たさせてもらおう。scarabを鍵の頭として固定し、Scholomanceの閉ざされた扉を破る力を注ぎ込むための、特別な溶剤を用意してある。\n\nさて、うまくいくかどうか……", 0x40d2625d, 0xdc731f0e, 0x02a5ce97, 0x7c050df0, 0x94b2e77e, "....." },
  [5804] = { "Araj's Scarab", "Araj the Summonerを討ち滅ぼし、Araj's ScarabをWestern PlaguelandsのBulwarkにいるApothecary Dithersに渡して下さい。", "Araj the Summonerは、廃墟と化した街の中心からAndorhalを支配している。奴はこの街を我が物とする前は、Scholomanceのかつての指導者だったことが分かっている。鍵を完成させるには、奴の印章――scarabと呼ばれるもの――を鍵の頭として取り付ける必要がある。\n\nAndorhalの中心部へ向かい、奴が表に引きずり出された今こそ、街への支配を打ち砕くのだ。奴を倒したら、倒れた経箱からscarabを奪い取れ！\n\nKey to Scholomanceがあなたを待っている、{name}！", "ここまで来たのだ、{name}。Araj the Summonerの肉体を滅ぼすことでしか、鍵を完成させる手段は得られない。手段を選ばずAraj's scarabを手に入れて、私のところへ持ってきてくれ。それを鍵の頭として融合させる。", "そうだ、これだ! 私は……またしても、お前の狡知と勇気の深さに驚かされる。勝利のためにどこまでもやってのけるその姿には、ただただ呆れるばかりだ。\n\nさて、ここからは私が小さな役目を果たさせてもらおう。特別な溶剤を用意してある。これでscarabを鍵の頭部として固定し、Scholomanceの閉ざされた扉を破る力を吹き込めるはずだ。\n\nほんの少しだけ時間がかかる……", 0x40d2625d, 0x65f60fe7, 0x02a5ce97, 0x2a6adaec, 0x23815c28, "....." },
  [5805] = { "ようこそ!", "Northshire Gift VoucherをMerissa Stilwellに持って来てください。", "World of Warcraftへようこそ！\n\nWorld of Warcraft Collector's Editionをご購入いただいた特別なお礼として、このギフト券をNorthshire ValleyのMerissa Stilwellに渡してください。すると贈り物がもらえます。冒険と栄光を求めるあなたのクエストに同行する、小さな仲間です。\n\n改めてありがとうございます。World of Warcraftでの滞在をお楽しみください！", "こんにちは! お会いできて嬉しいです!\n\n特別なvoucherをお持ちですね。それを渡していただければ、代わりに何かを差し上げますよ。", "あなたは本当に特別な英雄です、{name}。Azerothの世界へようこそ。この特別な贈り物の1つを差し上げます!", 0xd6adcb4f, 0x507c2857, 0x1a0e6aca, 0x2524e445, 0x4c44dc2c, "....." },
  [5821] = { "用心棒", "Gizelton Caravan を Kolkar Centaur village の先まで護衛する。報酬を受け取るには Scrabblescrew's Camp にいる Smeed と話す。", "普段なら、Riggerと私でkodoを引いてKolkar Centaurの横を通り抜けるんだ。ときどきCentaurの戦太鼓が聞こえてきて、そうなったら足を止める。死んじまったら商売にならないからな！\n\nいいか、{class}、Kolkarの村を過ぎるまで私たちを守ってくれたら、それに見合う礼はするよ。\n\nほんの短い距離だ。隊商を無事に守り抜いてくれればいい。報酬はSmeed Scrabblescrewから受け取ってくれ――少し先の道沿いにいる。ちょっとした取引仲間なんだ。", "なんでオレはあのいまいましいキャラバンを待ってるんだ?\n\n<Smeedは何かを悟ったような顔をする。>\n\nああ、そうだ、あいつらが金を払ってくれるんだった。あいつらを見かけたかい?", "なあ、あんたみたいな奴に Gizelton Caravan の護衛報酬を払うのってビジネス的に成功だと思えないんだが。{class} 、もうちょっと背が高かったらオレがアルバイトで引き受けて、自分が持てる限界ぎりぎりのでかい銃を持って kodo に横乗りしてやるのにな……でもって、忌々しいcentaurどもにどっちが上か思い知らせてやるんだ。", 0x998f3fc8, 0x0697bce1, 0xa4b4d23d, 0x65827a69, 0xb6a810e3, "....." },
  [5841] = { "ようこそ!", "Coldridge Valley Gift VoucherをYori Crackhelmに渡してください．", "ようこそWorld of Warcraftの世界へ！\n\nWorld of Warcraftコレクターズエディションをご購入いただき、まことにありがとうございます。Coldridge ValleyにいるYori Crackhelmに、このギフトクーポンを渡してください。そうすれば、贈り物を受け取ることでしょう。それは、冒険や栄光のためのクエストをあなたと共にする、小さな仲間です。\n\n重ねてお礼を申し上げます。World of Warcraftをお楽しみください！", "やあ! お会いできて嬉しいです!\n\n特別なvoucherをお持ちですね。それを渡していただければ、代わりに何かを差し上げますよ。", "あなたはまことに特別な英雄ですね、{name}。Azerothはあなたを歓迎し、このすばらしい贈り物の中のひとつを差し上げましょう。", 0xd6adcb4f, 0x76066af0, 0x1ef929e0, 0xaec8f595, 0x4c44dc2c, "....." },
  [5842] = { "ようこそ!", "Orenthil Whisperwind に Shadowglen Gift Voucher を渡して下さい。", "World of Warcraftへようこそ！\n\nWorld of Warcraft Collector's Editionをご購入いただいた特別なお礼として、このgift voucherをShadowglenのOrenthil Whisperwindに渡してください。冒険と栄光を求めるあなたのクエストに同行する、小さな仲間が贈られます。\n\n改めてありがとうございます。World of Warcraftでのひとときをお楽しみください！", "こんにちは! お会いできて嬉しいです!\n\n特別なvoucherをお持ちですね。それを渡していただければ、代わりに何かを差し上げますよ。", "あなたは本当に特別な英雄です、{name}。Azerothの世界へようこそ。この特別な贈り物の1つを差し上げます!", 0xd6adcb4f, 0x30f931f5, 0x98375d78, 0x2524e445, 0x4c44dc2c, "....." },
  [5843] = { "ようこそこの世界へ！", "Valley of Trials Gift VoucherをMaggaに渡してください。", "World of Warcraftへようこそ！\n\nWorld of Warcraft Collector's Editionお買い上げの特別な感謝の印としてこのギフトクーポンをValley of TrialsにいるMaggaにお渡しください。冒険と栄光への旅を共にする小さな仲間を差し上げます。\n\n重ねて感謝申し上げます。それではWorld of Warcraftをお楽しみください！", "やあ! お会いできて嬉しいです!\n\n特別なvoucherをお持ちですね。それを渡していただければ、代わりに何かを差し上げますよ。", "あなたは選ばれし英雄だよ、{name}。Azeroth世界へようこそ。ユニークな贈り物を一つ差し上げましょう！", 0xd6adcb4f, 0x805611c0, 0xbebd6483, 0xaec8f595, 0x4c44dc2c, "....." },
  [5844] = { "ようこそこの世界へ！", "Camp Narache Gift VoucherをVorn Skyseerに渡してください。", "World of Warcraftへようこそ！\n\nWorld of Warcraft Collector's Editionお買い上げの特別な感謝の印としてこのギフトクーポンをCamp NaracheにいるVorn Skyseerにお渡しください。冒険と栄光への旅を共にする小さな仲間を差し上げます。\n\n重ねて感謝申し上げます。それではWorld of Warcraftをお楽しみください！", "こんにちは! お会いできて嬉しいです!\n\n特別なvoucherをお持ちですね。それを渡していただければ、代わりに何かを差し上げますよ。", "あなたは選ばれし英雄だよ、{name}。Azeroth世界へようこそ。ユニークな贈り物を一つ差し上げましょう！", 0xd6adcb4f, 0xbba6f3d6, 0x9ab96af7, 0x2524e445, 0x4c44dc2c, "....." },
  [5845] = { "失われた名誉について", "Northdale(Eastern Plaguelands北東部)へ向かい、Symbol of Lost Honorを取り戻して下さい。目的を達成したらTirion Fordringのところへ戻って下さい。", "Utherが討たれた時、Order of the Silver Handは壊滅した。\n\nあの子はできる限り持ちこたえた。戦火に荒れたNorthdaleの村落まで追い詰められ、そこで最後の抵抗をした。\n\nOrderの誰かがまだ生き残っているのだろうか、と彼は考えた――そして、それに意味はあるのか？\n\nその思いとともに、TaelanはOrderの旗を投げ捨て、それまで知っていたすべてを捨てた。彼の名誉はNorthdaleの血に染まった地に置き去りにされた。\n\nNorthdaleへ赴き、あのsymbol of lost honorを取り戻さねばならない。", "私の信仰があなたを導くでしょう、{name}。光に限りはありません。", "これは今も、ぼろぼろになった姿であってさえ、私がこれを見上げて忠誠の誓いを立てたあの日と同じほどに輝かしい。\n\nあれの救済が訪れる。そしておそらくは、私の救済もまた……", 0xead3f134, 0xa711412a, 0x8dc5f92c, 0x43f6b880, 0x8edec1d7, "....." },
  [5846] = { "Of Love and Family", "Caer Darrow島(Plaguelands南中央部)へ行き、絵画の行方に関する手掛かりを探して下さい。", "Taelanが子供の頃、我々は家族旅行でよくCaer Darrowを訪れた。最後に訪れた時、Renfrayという名の画家が、浜辺に佇む我々の肖像画を描いてくれた。それはTaelanとKarandraの両方にまつわる、私の最も大切な思い出だ。妻と息子をこの腕に抱いたその瞬間、私は二度と知ることのない愛と家族の絆を感じたのだから。\n\nこの絵がまだ残っているなら、見つけてほしい。\n\n廃墟となったCaer Darrowの島へ赴き、絵か画家が残っているか確かめてくれ。", nil, "忘れるものか。この島の霊の多くは、悲惨な最期を迎える前の最後の幸せな記憶を、繰り返し生き直すよう呪われている。\n\n私もまた呪われている。だが彼らとは違う。私はすべてを覚えている数少ない者の一人なのだ……\n\nお前が私に尋ねるこのことこそ、私がこの廃墟にとどまり続けている理由なのかもしれん。私がお前に語るこのことが、私を解き放ってくれるのかもしれん。", 0x2e3d92e4, 0x8e686d8f, 0xb8d96ce4, nil, 0xd13e736b, "...m." },
  [5847] = { "ようこそ！", "DeathknellにいるClaire WillowerにDeathknell Gift Voucherを渡してください。", "ようこそWorld of Warcraftの世界へ！\n\nWorld of Warcraftコレクターズエディションをご購入いただきありがとうございます。DeathknellにいるClaire Willowerにこのギフトクーポンを渡してください。贈り物を差し上げます。あなたと共に旅する小さな仲間です。\n\n重ねて御礼を申し上げます。World of Warcraftをお楽しみください！", "こんにちは! お会いできて嬉しいです!\n\n特別なvoucherをお持ちですね。それを渡していただければ、代わりに何かを差し上げますよ。", "あなたはまことに特別な英雄ですな、{name}。Azerothはあなたを歓迎いたします。ひとつ面白い贈り物がございます。", 0xd6adcb4f, 0x1cf17152, 0x1b055ef2, 0x2524e445, 0x4c44dc2c, "....." },
  [5848] = { "Of Love and Family", "Plaguelandsの北部にあるStratholmeへ行く。Scarlet Bastionの中で、この世界の双子の月を描いた別の絵の裏に隠された絵画「Of Love and Family」が見つかるだろう。\n\nその絵をTirion Fordringのところへ持ち帰って下さい。", "あの絵は……何年もの間、Orderの兵舎の中にある私の工房の壁に掛かっていた。\n\nTirionの裁判が終わった後、もうあの絵を人目に触れるところには置いておけないと分かった。彼らが決して探そうと思わない場所に隠したのだ。\n\nStratholmeへ行き、今はScarlet Bastionとなっている場所の奥深くへ進み、双子の月を描いた絵を探してくれ。絵の具を削り取れば、私の傑作、'Of Love and Family'が現れるだろう。\n\n光があなたの行いを導きますように。", "絵だ、{name}。絵は持っているか?", "<Tirionは絵を目にして崩れ落ちそうになる。>\n\n<彼は半ば狂おしいほどに泣きじゃくり始める。>", 0x2e3d92e4, 0x087c7818, 0x7fecbed3, 0x0606e29d, 0x90e5761d, "....." },
  [5861] = { "Myrandaを探せ", "Plaguelands南部に位置するUther's Tombへ行き、Myranda the HagにTirion's Giftを見せて下さい。", "{name}、君はこれまで私が頼んだことをすべて成し遂げてくれた。君の贖罪のクエストに残された段階はあと1つだけだ。\n\n集めた品をTaelanに届けなければならない。困ったことに、Taelanと彼のScarlet Crusadersは君を見るなり襲いかかってくるだろう。\n\n私の伝言を届ける方法はただ1つ、欺きの姿を借りることだ。\n\n南にUtherの墓がある。私の古くからの信頼できる相談相手、Myrandaが今そこに住んでいる――彼女を探してくれ。品を見せれば、彼女が手を貸してくれるだろう。", "この日が来ることは分かっていた。", "私はTirionがMardenholdeの主の地位にあったとき、彼の最も信頼された助言者だった。私はOrder of the Silver Handが下した評決に公然と異を唱え、その不遜さゆえに追放された。\n\n彼はその生涯で多くの心痛と失望を味わってきた、{race}よ。Fordringsの一族に降りかかった不当を正す覚悟はあるか?", 0x22b4fc0c, 0x4f73da99, 0x664166f9, 0x8e458cc7, 0xf937f539, "....." },
  [5862] = { "緋色の策略", "Myrandaと話してScarlet Illusionをかけてもらう。Scarlet Illusionがかかっている間にHearthglenへ行き、Tirion's GiftをHighlord Taelan Fordringに届けて下さい。\n\nHearthglenは北にある。TaelanはMardenholde Keepの中にいるはずだ。", "私はいわゆる幻術師だ。あなたがHearthglenに入れるように幻を作り出せるかもしれないが、気をつけて。私の力には限界がある。\n\nこの地から遠く離れすぎると、幻の効果は消えてしまう。この呪文自体、私に大きな集中と力を要求するので、効果を保てるのは短い間だけだ。\n\n準備ができたら、また話しかけてくれ。", "あなたはTyr's Handからの援軍か?", "これは何だ、兵士よ?\n\n<Taelanが箱を開け、中身を検め始める。>\n\nこれは……これが真実であるはずがない。だが、そなたが見せてくれたすべてが……\n\n<Taelanは片膝をつき、その鼓動が速まる。幾時代もの怒りが、今まさにこの町に解き放たれようとしている。>", 0x381c7f37, 0xe3897007, 0x987323c5, 0xf0a0fb97, 0x97738e7f, "....." },
  [5863] = { "Dunemaul Compound", "GadgetzanのAndi Lynnは、Dunemaul Brute・Dunemaul Enforcerをそれぞれ10人ずつとGor'marok the Ravagerを殺し、Dunemaul Compoundを壊滅させるよう求めています。", "つい最近、放浪するogreの大集団がTanarisにやって来た。ここから南で、奴らは砂漠の広い一帯を占拠し、根城を築いた。いくつかの小さな群れが今も砂漠をうろついていて、その一部は古いトロールの遺跡に入り込んでいる。\n\nDunemaul Compoundを破壊しなければならない！ このogreどもに戦力を蓄えさせるわけにはいかない。\n\nこの群れの頭はGor'marok the Ravagerという名だ。奴の統率を終わらせることが、ogreどもの終わりの始まりになると私は信じている。", "心配でたまらないわ! どうか気をつけて!", "あなたがやり遂げてくれてすごく嬉しいわ、{name}! 手伝ってくれてありがとう!", 0xd39604a7, 0xc8426bdf, 0xf7ee5218, 0x1d17f52b, 0x0ae27f9d, "....." },
  [5881] = { "予備兵の召集", "Maggranは、あなたがBarrensのGreat LiftにいるGrish Longrunnerに手紙を配達することを望んでいます。", "Hordeは常に兵士の英気を養い・・・the Great War以来、ここKalimdorで繁栄してきた。\n\n手伝って欲しい事があるんだ。Barrens南部のGreat Liftを守っているGrish Longrunnerという名の若者がいる。彼にこの手紙を渡してくれ。手紙は、彼が任務から離れて家族に会いにいけるよう、代わりの戦士を手配することを知らせるものだ。前に彼から要望があった。この知らせを喜ぶだろう。", "Maggran Earthbinderからの知らせか?", "これは朗報だ。この木の塊を見張ってここに座っているのは、もう長すぎるくらいだった。これでやっと家族と一緒に過ごせる……やったー！", 0x43b6d403, 0x9b65dff0, 0x68d44f68, 0xb6afe6ee, 0x6ac36c0d, "....." },
  [5882] = { "Hunting で手に入る軟膏", nil, nil, "Cenarion beaconを持っていれば、大義のために討たれた汚れた獣にcorrupted soul shardが見えるようになる。私はそのshardを砕いて、Cenarion plant salveを作るための使える試薬にしている。その軟膏で、汚染された植物を再び健康な姿に戻すのだ。\n\nこのshardと引き換えに、すでに用意してあるCenarion plant salveをいくつか渡そう。", "結構ですよ。では Cenarion plant salve をどうぞ。Felwood の汚染植物を探すのです、{name}! どこに生えていようとも、あなたに差し上げた軟膏で浄化するのですよ。", 0x531b3091, nil, nil, 0xdedb609b, 0x944389af, ".mm.." },
  [5883] = { "Mining で手に入る軟膏", nil, nil, "Felwoodで採掘するときにCenarion beaconを持っていれば、未加工の金属の鉱脈を蝕むtainted vitriolが見えるようになる。私はそのvitriolを浄化し、Cenarion plant salveを作るための試薬に変える方法を知っている。そうしたら、あなたはその軟膏を、野に生える救いの必要な植物に使うのだ。\n\ntainted vitriolを集めてきたなら、すでに用意してあるCenarion plant salveをいくつか渡そう。", "結構ですよ。では Cenarion plant salve をどうぞ。Felwood で採掘をしていてまたvitriol を見つけたら、取っておくのを忘れないで下さいね! もっと見つければ、また軟膏を作ることができますよ。", 0x7f2307ff, nil, nil, 0x9d7a3c30, 0x6e2eea1b, ".mm.." },
  [5884] = { "Gathering で手に入る軟膏", nil, nil, "Cenarion beaconがあれば、熟練の薬草師は陰湿なfel creepを見つけられる。Felwoodの汚染が生んだ邪悪な産物だ。ここでの研究を通して、私はfel creepを浄化の試薬へと清める知識を得た……今ではCenarion plant salveと呼んでいるものに使われる試薬だ。\n\nbeaconを持っていれば、Felwoodで薬草を集めるときにfel creepに出くわすはずだ。持ってきてくれた分と引き換えに、作り置きのCenarion plant salveを渡そう。", "お見事です、{name} ――これを浄化すれば、すべて Felwood 奪還の役に立つでしょう。さあ、Cenarion plant salve を持って森へ行くのです。汚染地の再生は {race} を待ってはくれませんよ!", 0xc206b641, nil, nil, 0xfeee85f3, 0x45ed0202, ".mm.." },
  [5885] = { "Skinning で手に入る軟膏", nil, nil, "Cenarion beaconがあれば、腕の良い皮剥ぎ職人は、Felwoodで得た獲物からtainted skinの切れ端を見つけられる。私はこの一見役に立たない切れ端を濃いペーストに変える。それがCenarion plant salveの促進剤になるのだ。ここFelwoodで仕留めた獲物の皮を剥ぐときは、必ずbeaconを身につけておくように!\n\ntainted skinの切れ端を集めたら、持ってきてくれ。すでに作ってあるCenarion plant salveをいくつか渡そう。", "まさしく必要なものです。さあどうぞ――汚染された Felwood をこの plant salve で再生させるのです。粘り強く続けねばなりません、{name}!", 0x4791f5d6, nil, nil, 0x7bb6e789, 0x3b679069, ".mm.." },
  [5886] = { "Disenchanting で手に入る軟膏", nil, nil, "魔法の品を分解したときの力は、そこから生まれるessenceで感じ取れる。私は付呪師が使う未加工のessenceを、Cenarion plant salveを作るのに適した試薬に変える方法を考え出した。これにはCenarion beaconは必要ない。lesser nether essenceが得られるよう分解した品なら、どれでも使える。\n\n必要なのはlesser nether essenceをひとつだけだ。引き換えに、Cenarion plant salveを渡そう。essenceは非常に強力で……ほんの少しで本当に長持ちするのだ!", "さあ Cenarion plant salve です――これに必要なのは lesser nether essence ひとつだけですよ、{name} 。エッセンスはそのままの状態であっても、危険なものを有益なものへ変換するのに使用できる最強の物質なのです。もっと軟膏がご入り用でしたら、私に会いに来て下さいね!", 0xdb31ab2a, nil, nil, 0x01b0d33a, 0x84936fd1, ".mm.." },
  [5887] = { "Hunting で手に入る軟膏", nil, nil, "Cenarion beaconを持っていれば、大義のために討たれた汚れた獣にcorrupted soul shardが見えるようになる。私はそのshardを砕いて、Cenarion plant salveを作るための使える試薬にしている。その軟膏で、汚染された植物を再び健康な姿に戻すのだ。\n\nこのshardと引き換えに、すでに用意してあるCenarion plant salveをいくつか渡そう。", "結構ですよ。では Cenarion plant salve をどうぞ。Felwood の汚染植物を探すのです、{name}! どこに生えていようとも、あなたに差し上げた軟膏で浄化するのですよ。", 0x531b3091, nil, nil, 0xdedb609b, 0x944389af, ".mm.." },
  [5888] = { "Mining で手に入る軟膏", nil, nil, "Felwoodで採掘するときにCenarion beaconを持っていれば、未加工の金属の鉱脈を蝕むtainted vitriolが見えるようになる。私はそのvitriolを浄化し、Cenarion plant salveを作るための試薬に変える方法を知っている。そうしたら、あなたはその軟膏を、野に生える救いの必要な植物に使うのだ。\n\ntainted vitriolを集めてきたなら、すでに用意してあるCenarion plant salveをいくつか渡そう。", "結構ですよ。では Cenarion plant salve をどうぞ。Felwood で採掘をしていてまたvitriol を見つけたら、取っておくのを忘れないで下さいね! もっと見つければ、また軟膏を作ることができますよ。", 0x7f2307ff, nil, nil, 0x9d7a3c30, 0x6e2eea1b, ".mm.." },
  [5889] = { "Gathering で手に入る軟膏", nil, nil, "Cenarion beaconがあれば、熟練の薬草師は陰湿なfel creepを見つけられる。Felwoodの汚染が生んだ邪悪な産物だ。ここでの研究を通して、私はfel creepを浄化の試薬へと清める知識を得た……今ではCenarion plant salveと呼んでいるものに使われる試薬だ。\n\nbeaconを持っていれば、Felwoodで薬草を集めるときにfel creepに出くわすはずだ。持ってきてくれた分と引き換えに、作り置きのCenarion plant salveを渡そう。", "お見事です、{name} ――これを浄化すれば、すべて Felwood 奪還の役に立つでしょう。さあ、Cenarion plant salve を持って森へ行くのです。汚染地の再生は {race} を待ってはくれませんよ!", 0xc206b641, nil, nil, 0xfeee85f3, 0x45ed0202, ".mm.." },
  [5890] = { "Skinning で手に入る軟膏", nil, nil, "Cenarion beaconがあれば、腕の良い皮剥ぎ職人は、Felwoodで得た獲物からtainted skinの切れ端を見つけられる。私はこの一見役に立たない切れ端を濃いペーストに変える。それがCenarion plant salveの促進剤になるのだ。ここFelwoodで仕留めた獲物の皮を剥ぐときは、必ずbeaconを身につけておくように!\n\ntainted skinの切れ端を集めたら、持ってきてくれ。すでに作ってあるCenarion plant salveをいくつか渡そう。", "まさしく必要なものです。さあどうぞ――汚染された Felwood をこの plant salve で再生させるのです。粘り強く続けねばなりません、{name}!", 0x4791f5d6, nil, nil, 0x7bb6e789, 0x3b679069, ".mm.." },
  [5891] = { "Disenchanting で手に入る軟膏", nil, nil, "魔法の品を分解したときの力は、そこから生まれるessenceで感じ取れる。私は付呪師が使う未加工のessenceを、Cenarion plant salveを作るのに適した試薬に変える方法を考え出した。これにはCenarion beaconは必要ない。lesser nether essenceが得られるよう分解した品なら、どれでも使える。\n\n必要なのはlesser nether essenceをひとつだけだ。引き換えに、Cenarion plant salveを渡そう。essenceは非常に強力で……ほんの少しで本当に長持ちするのだ!", "さあ Cenarion plant salve です――これに必要なのは lesser nether essence ひとつだけですよ、{name} 。エッセンスはそのままの状態であっても、危険なものを有益なものへ変換するのに使用できる最強の物質なのです。もっと軟膏がご入り用でしたら、私に会いに来て下さいね!", 0xdb31ab2a, nil, nil, 0x01b0d33a, 0x84936fd1, ".mm.." },
  [5901] = { "ふりかかる災厄", "Eastern PlaguelandsのTermite MoundsでEmpty Termite Jarを使ってPlagueland Termiteを100匹捕まえて下さい。集まったら、Tirisfal GladesのBulwarkにいるMickey Levineのもとへ戻ってください。", "Scarlet Crusadeに苦痛と不和を与えんがため、奴らの貴重な製材所をつぶしたい。そうすることで奴らの街の防衛と再建に多大な影響をもたらすだろう。手伝ってくれんかね、{name}？\n\n初めにこのつぼを持ってEastern PlaguelandsのPlaguewoodへ行くのだ。それを森中で見うけられる蟻塚にいるシロアリで満たすのだ。充分集まったなら戻ってこい。", "termitesはもう手に入れたかい、{name}? 君のような賢い{class}なら、分かりきったことだろう。\n\n十分な数が集まれば、もう二度と誰にもあの製材所を使わせないようにしてやれるぞ!", "いい感じだぞ、{name}。ありがとう。\n\n準備ができたら、次の段階へ進むぞ。", 0x4a22873d, 0x115bb474, 0x6cb4acb7, 0x98ba611f, 0x3ff3ec65, "....." },
  [5902] = { "ふりかかる災厄", "Western PlaguelandsのNorthridge Lumber Millの中でBarrel of Plagueland Termitesを置くために適当な場所を探してください。", "多くのシロアリを集めた今、このsteel reinforced barrelをHearthglenの南のNorthridge Lumber Millに持っていくのだ。街へ続く道の西側にあるだろう。\n\nついたらすぐ製材所の中心部の、木箱か何かの上のような高いところにそのbarrelを置くのだ。\n\n開けたら後は勝手にやってくれる。急いで戻ってこい。お礼はするよ。", nil, "木箱の上にたるを置くと、シロアリたちはそわそわしだした。", 0x4a22873d, 0x747b27e9, 0xe797190e, nil, 0xbeaa777d, "...m." },
  [5903] = { "汝に疫病あれ", "Eastern PlaguelandsのTermite MoundsでEmpty Termite Jarを使う。Plagueland Termitesを$N1匹集めたら、Western PlaguelandsのChillwind CampにいるNathaniel Dumahのところへ戻って下さい。", "Scarlet Crusadeを力ずくで追い払おうと何度も試みたが、無駄だった。そこで代わりに、奴らの暮らしをもっと厄介なものにしてやることにした。\n\n手を貸してくれるなら、あの製材所に、これまでに見つかった中で最も恐ろしい種類のシロアリをはびこらせてやりたい。\n\nかつて栄えたStratholmeの近く、Plaguewoodに、疫病とScourgeの両方を生き延びた種がいる。奴らの巣塚を見つけて、この瓶をそいつらでいっぱいにしてくれ。そうすればCrusadeに放つ準備ができる。", "シロアリの塚は見つかったかい、{name}? Plaguewoodのあちこちにあると聞いたんだが。", "これで上出来だ、{name}。ありがとう。見てみろ……こんなにたくさん身を寄せ合って。Crusadeが少し気の毒になるほどだ。だがまあ、そもそもあの製粉所は奴らが奪っていいものではなかったのだろう?", 0x4a22873d, 0x7be1dd9d, 0x0c3da530, 0x23d993f7, 0xa68d8bd1, "....." },
  [5904] = { "汝に疫病あれ", "Western PlaguelandsのNorthridge Lumber Millの中央で、Barrel of Plagueland Termitesを置くのにふさわしい場所を見つける。", "シロアリが手に入ったから、この鋼で補強した樽をHearthglenの南にあるNorthridge Lumber Millへ持って行ってくれ――町へ上っていく道の西側にある。\n\n着いたら、製材所の真ん中に樽を置け。木箱の上のような適当な場所を見つけて、それから樽を開けるんだ。あとはシロアリが仕事をして、製材所をCrusadeにとって役に立たないものにしてくれるはずだ。", nil, "barrelを木箱の上に置くと、termitesは明らかに落ち着きをなくしていく。", 0x4a22873d, 0x747b27e9, 0x6902aded, nil, 0xbeaa777d, "...m." },
  [5921] = { "Moonglade", "'Teleport: Moonglade'を使い、Moongladeへ行って下さい。到着したら、village of NighthavenのDendrite Starblazeと話して下さい。", "Moongladeの神聖な地では、Moongladeの守護者であるKeeper RemulosとArch Druid Staghelmとの間に今ある緊張状態も一切関係なく、すべてのドルイドが歓迎されます。\n\n「爪」の道を習得している今こそ、Moongladeへ移動するための呪文をお教えしましょう。Moongladeの知識や癒しを求める時はいつでも、唱えるのですよ。\n\n最初の修行については、Moongladeへ行って、今あなたが進んでいる道についてNighthavenのDendrite Starblazeと話して下さい。幸運を祈ります、若きドルイドよ。", nil, "「そのようにしてそれは始まる、大いなる父Cenarius。そうして始まる。」\n\nDendriteは素早く、宙に向かって見えない仕草を行った。かすかな力のオーラが彼に降り注いだ。\n\n「あなたがまず受け入れなくてはならない自然の見方は、『熊』のものだ。私はあなたを道へ導こうと思っている。ドルイドの生き方における、『熊』の一面を理解する道へ。だが、それを受け入れ、伝えていくのはあなたなのだ……今も、そしてこれからも!」", 0xaeb97c8b, 0xf8085429, 0x6d17554b, nil, 0xeca326e1, "...m." },
  [5922] = { "Moonglade", "'Teleport: Moonglade'を使い、Moongladeへ行って下さい。到着したら、village of NighthavenのDendrite Starblazeと話して下さい。", "Moongladeの神聖な地においては、ドルイドはすべて歓迎されます。トーレンもナイトエルフも皆一様に。Moongladeの守護者、Keeper Remulosはそこで眠りについたドルイドたちを見守っています。「爪」の法を習得している今こそ、Moongladeへ移動するための呪文をお教えしましょう。Moongladeの知識や癒しを求める時はいつでも、唱えるのですよ。\n\n最初の修行については、Moongladeへ行って、今あなたが進んでいる道についてNighthavenのDendrite Starblazeと話して下さい。幸運を祈ります、若きドルイドよ。", nil, "「そのようにしてそれは始まる、大いなる父Cenarius。そうして始まる。」\n\nDendriteは素早く、宙に向かって見えない仕草を行った。かすかな力のオーラが彼に降り注いだ。\n\n「あなたがまず受け入れなくてはならない自然の見方は、『熊』のものだ。私はあなたを道へ導こうと思っている。ドルイドの生き方における、『熊』の一面を理解する道へ。だが、それを受け入れ、伝えていくのはあなたなのだ……今も、そしてこれからも!」", 0xaeb97c8b, 0xf8085429, 0xbc279cb2, nil, 0xeca326e1, "...m." },
  [5923] = { "呼び声を聞け", "DarnassusのCenarion EnclaveにいるMathrengyl Bearwalkerと話して下さい。", "済みません、友よ……\n\nMathrengyl Bearwalkerがあなたと話したいと仰っていたそうです。ドルイドとしての鍛錬は新しい生活を得られるようですし、彼はあなたを個人的に鍛えたいのでしょう。MathrengylはArch Druidの助手で、Teldrassilの中で最も思慮深く威厳のあるドルイドです。\n\n彼はDarnassusのCenarion Enclave、Fandral Staghelm's treeの二階にいます。", nil, "あなたが今日ここへ来てくれて嬉しいですよ、若き{class}。もっと大きな世界へと、大きな一歩を踏み出す時がきたのです。\n\nCenariusの子供たちは皆、自然に尽くすことが使命だと感じています。動物や植物は私たちの友であり、私たちに託された大切なものなのです。私たち自身と同じように彼らの目的のため、均衡の管理者として人生を捧げることを私たちは選びました。この世界へのあなたの一歩は、熊の道を学び、肉体と精神の力を身につけることでしょう。\n\nさあ、準備して下さい!", 0xfe4e1687, 0x6c0db897, 0x30240ec9, nil, 0x2b8e0102, "...m." },
  [5924] = { "呼び声を聞け", "DarnassusのCenarion EnclaveにいるMathrengyl Bearwalkerと話して下さい。", "済みません、友よ……\n\nMathrengyl Bearwalkerがあなたと話したいと仰っていたそうです。ドルイドとしての鍛錬は新しい生活を得られるようですし、彼はあなたを個人的に鍛えたいのでしょう。MathrengylはArch Druidの助手で、Teldrassilの中で最も思慮深く威厳のあるドルイドです。\n\n彼はDarnassusのCenarion Enclave、Fandral Staghelm's treeの二階にいます。", nil, "あなたが今日ここへ来てくれて嬉しいですよ、若き{class}。もっと大きな世界へと、大きな一歩を踏み出す時がきたのです。\n\nCenariusの子供たちは皆、自然に尽くすことが使命だと感じています。動物や植物は私たちの友であり、私たちに託された大切なものなのです。私たち自身と同じように彼らの目的のため、均衡の管理者として人生を捧げることを私たちは選びました。この世界へのあなたの一歩は、熊の道を学び、肉体と精神の力を身につけることでしょう。\n\nさあ、準備して下さい!", 0xfe4e1687, 0x6c0db897, 0x30240ec9, nil, 0x65aa7f11, "...m." },
  [5925] = { "呼び声を聞け", "DarnassusのCenarion EnclaveにいるMathrengyl Bearwalkerと話して下さい。", "済みません、友よ……\n\nMathrengyl Bearwalkerがあなたと話したいと仰っていたそうです。ドルイドとしての鍛錬は新しい生活を得られるようですし、彼はあなたを個人的に鍛えたいのでしょう。MathrengylはArch Druidの助手で、Teldrassilの中で最も思慮深く威厳のあるドルイドです。\n\n彼はDarnassusのCenarion Enclave、Fandral Staghelm's treeの二階にいます。", nil, "あなたが今日ここへ来てくれて嬉しいですよ、若き{class}。もっと大きな世界へと、大きな一歩を踏み出す時がきたのです。\n\nCenariusの子供たちは皆、自然に尽くすことが使命だと感じています。動物や植物は私たちの友であり、私たちに託された大切なものなのです。私たち自身と同じように彼らの目的のため、均衡の管理者として人生を捧げることを私たちは選びました。この世界へのあなたの一歩は、熊の道を学び、肉体と精神の力を身につけることでしょう。\n\nさあ、準備して下さい!", 0xfe4e1687, 0x6c0db897, 0x30240ec9, nil, 0x2b8e0102, "...m." },
  [5926] = { "呼び声を聞け", "Thunder BluffのElder RiseにいるTurak Runetotemと話して下さい。", "済みません、友よ……\n\nTurak Runetotemがあなたと話したいと仰っていたそうです。ドルイドとしての鍛錬は新しい生活を得られるようですし、彼はあなたを個人的に鍛えたいのでしょう。TurakはArch Druidの助手のひとりで、賢明で我慢強いドルイドであると知られています。彼ならばよく教えて下さいますよ。\n\n彼はThunder BluffのElder RiseにあるCenarion Circleの大天幕の中にいます。", nil, "あなたが今日ここへ来てくれて嬉しいですよ、若き{class}。もっと大きな世界へと、大きな一歩を踏み出す時がきたのです。\n\nCenariusの子供たちは皆、自然に尽くすことが使命だと感じています。動物や植物は私たちの友であり、私たちに託された大切なものなのです。私たち自身と同じように彼らの目的のため、均衡の管理者として人生を捧げることを私たちは選びました。この世界へのあなたの一歩は、熊の道を学び、肉体と精神の力を身につけることでしょう。\n\nさあ、準備して下さい!", 0xfe4e1687, 0xb75320fd, 0x1a176df1, nil, 0x8ef40860, "...m." },
  [5927] = { "呼び声を聞け", "Thunder BluffのElder RiseにいるTurak Runetotemと話して下さい。", "済みません、友よ……\n\nTurak Runetotemがあなたと話したいと仰っていたそうです。ドルイドとしての鍛錬は新しい生活を得られるようですし、彼はあなたを個人的に鍛えたいのでしょう。TurakはArch Druidの助手のひとりで、賢明で我慢強いドルイドであると知られています。彼ならばよく教えて下さいますよ。\n\n彼はThunder BluffのElder RiseにあるCenarion Circleの大天幕の中にいます。", nil, "あなたが今日ここへ来てくれて嬉しいですよ、若き{class}。もっと大きな世界へと、大きな一歩を踏み出す時がきたのです。\n\nCenariusの子供たちは皆、自然に尽くすことが使命だと感じています。動物や植物は私たちの友であり、私たちに託された大切なものなのです。私たち自身と同じように彼らの目的のため、均衡の管理者として人生を捧げることを私たちは選びました。この世界へのあなたの一歩は、熊のやり方を学び、肉体と精神の力を身につけることでしょう。\n\nさあ、準備して下さい!", 0xfe4e1687, 0xb75320fd, 0x1a176df1, nil, 0x65aa7f11, "...m." },
  [5928] = { "呼び声を聞け", "Thunder BluffのElder RiseにいるTurak Runetotemと話して下さい。", "済みません、友よ……\n\nTurak Runetotemがあなたと話したいと仰っていたそうです。ドルイドとしての鍛錬は新しい生活を得られるようですし、彼はあなたを個人的に鍛えたいのでしょう。TurakはArch Druidの助手のひとりで、賢明で我慢強いドルイドであると知られています。彼ならばよく教えて下さいますよ。\n\n彼はThunder BluffのElder RiseにあるCenarion Circleの大天幕の中にいます。", nil, "あなたが今日ここへ来てくれて嬉しいですよ、若き{class}。もっと大きな世界へと、大きな一歩を踏み出す時がきたのです。\n\nCenariusの子供たちは皆、自然に尽くすことが使命だと感じています。動物や植物は私たちの友であり、私たちに託された大切なものなのです。私たち自身と同じように彼らの目的のため、均衡の管理者として人生を捧げることを私たちは選びました。この世界へのあなたの一歩は、熊のやり方を学び、肉体と精神の力を身につけることでしょう。\n\nさあ、準備して下さい!", 0xfe4e1687, 0xb75320fd, 0x1a176df1, nil, 0x65aa7f11, "...m." },
  [5929] = { "Great Bear Spirit", "Moonglade北西でGreat Bear Spiritを見つけ出し、熊の持つ野生の力を習得して下さい。それが終わったら、MoongladeのNighthavenにいるDendrite Starblazeの元へ戻って下さい。", "Moongladeの北西には、我々が「Great Bear Spirit」と呼ぶ賢明で高貴な存在の住まう場所がある。初めて真に自然に熊の力を理解するにあたり、すべてのドルイドのために教師となり良き師となって務めて下さっている。ある時点ですべてのドルイドは精霊の知恵を求める。それはあなたも例外ではないだろう。\n\nGreat Bear Spiritの元へ行き、その教えを習得するのだ。精霊が納得したなら、私のところへ戻ってきなさい。教えを真に考慮しているか、我々が見てあげよう。", "Great Bear Spiritがそなたを我のもとへ解き放ったときにのみ戻るがよい。その祝福なくして、そなたの修行は続けられぬ。", "あなたが近づくと、Dendriteは宙に別の目に見えない仕草をした。別の力のオーラが彼を包み、彼はごくわずかに微笑んだ。\n\n「若者よ、あなたの中に智を感じる。初めに会ったときのあなたはそこにない。力と聡明な意志をもって私を見つめている。まだ意志は定まっていないが。あなたは今、熊の野生の力を身につけ、力に集中することを学ぶだろう。」", 0xf41bfb43, 0xbe60f9ec, 0xfdf1fe79, 0x63fce517, 0x63faa67b, "....." },
  [5930] = { "Great Bear Spirit", "Moonglade北西でGreat Bear Spiritを見つけ出し、熊の持つ野生の力を習得して下さい。それが終わったら、MoongladeのNighthavenにいるDendrite Starblazeの元へ戻って下さい。", "Moongladeの北西には、我々が「Great Bear Spirit」と呼ぶ賢明で高貴な存在の住まう場所がある。初めて真に自然に熊の力を理解するにあたり、すべてのドルイドのために教師となり良き師となって務めて下さっている。ある時点ですべてのドルイドは精霊の知恵を求める。それはあなたも例外ではないだろう。\n\nGreat Bear Spiritの元へ行き、その教えを習得するのだ。精霊が納得したなら、私のところへ戻ってきなさい。教えを真に考慮しているか、我々が見てあげよう。", "Great Bear Spiritがそなたを我のもとへ解き放ったときにのみ戻るがよい。その祝福なくして、そなたの修行は続けられぬ。", "あなたが近づくと、Dendriteは宙に別の目に見えない仕草をした。別の力のオーラが彼を包み、彼はごくわずかに微笑んだ。\n\n「若者よ、あなたの中に智を感じる。初めに会ったときのあなたはそこにない。力と聡明な意志をもって私を見つめている。まだ意志は定まっていないが。あなたは今、熊の野生の力を身につけ、力に集中することを学ぶだろう。」", 0xf41bfb43, 0xbe60f9ec, 0xfdf1fe79, 0x63fce517, 0x63faa67b, "....." },
  [5931] = { "Darnassusへの帰還", "Darnassusへ戻り、Cenarion EnclaveにいるMathrengyl Bearwalkerと話して下さい。", "別の道を行く時がきた、若者よ。修行を活かすためには、私の元へ君を寄越した人のところへ戻らなくてはならない。均衡が崩れた場所のすぐ隣に住まっているにもかかわらず、Mathrengyl Bearwalkerは自然とともに真の均衡の道を歩んでいる。彼の教えを聴けば、均衡の守護者としての役割へ入る最初の修行をすぐに終えることができよう。\n\nさあ行け、若者よ。また会おう。", nil, "よくぞ戻ってきました、{name}。鉤爪の道へと足を踏み入れたすべてのドルイドがそうであるように、あなたも同じだったのでしょう。Great Bear Spiritとの初めての出会いというのは、ちょっと戸惑うものですが、しかし鮮烈なのです。分かりますよ、私もそうでしたから。\n\nAzerothが空に存在していた長い間、Great Bear SpiritもまたAzerothの一部でした。その英知と我々の目標を煽るその力に、私たちは頼るようになったのです。さあ、最初の試しの時がきました。よく聞いてください……", 0xf19243a5, 0x17d4d4c5, 0x96c7c00f, nil, 0x0683c922, "...m." },
  [5932] = { "Thunder Bluffへの帰還", "Thunder Bluffへ戻り、Elder RiseにいるTurak Runetotemと話して下さい。", "別の道を行く時がきた、若者よ。修行を活かすためには、私の元へ君を寄越した人のところへ戻らなくてはならない。トーレンはCenariusの道に入って間もないと思われるが、Turak Runetotemは自然の存在の中で、均衡と共に歩んでいる。彼の教えを聴けば、均衡の守護者としての役割へ入る最初の修行をすぐに終えることができよう。\n\nさあ行け、若者よ。また会おう。", nil, "よくぞ戻ってきました、{name}。鉤爪の道へと足を踏み入れたすべてのドルイドがそうであるように、あなたも同じだったのでしょう。Great Bear Spiritとの初めての出会いというのは、ちょっと戸惑うものですが、しかし鮮烈なのです。分かりますよ、私もそうでしたから。\n\nAzerothが空に存在していた長い間、Great Bear SpiritもまたAzerothの一部でした。我々{race}はそういった精霊たちの声を聴き、その意志に従って繁栄してきたのです。さあ、最初の試しの時がきました。よく聞いてください……", 0x03abdae1, 0x7484d02e, 0x98aa7b3f, nil, 0x93bf0b6f, "...m." },
  [5941] = { "Chromieのもとへ戻る", "Bundle of RelicsをAndorhalのChromieのところへ持って行って下さい。", "あなたはDarrowshireの戦いの遺物をたくさん集めてくれました。あなたがさらに多くを持って戻ってくるたびに、私の心は村を恋しく思いました……村をその運命から守りたいと願ったのです。\n\nそれが叶わないことは分かっています。でも、Andorhalにいるあの不思議なノーム、Chromieは、それができると言うのです。あなたならDarrowshireを救えると！\n\n彼女は私に遺物をまとめて、あなたにそれを彼女のところへ届けてもらうよう頼みました。Andorhalの廃墟になった宿屋であなたを待っているそうです。", "あなたの友人のCarlinと連絡を取っていました。彼は故郷の村の破滅にひどく心を痛めていますが、あなたのことをとても高く評価していて、あなたなら事態を正せると信じています。\n\nああ、話がそれてしまいましたね……{name}、頼んでおいたrelicsはお持ちですか?", "ああ、そうだ、これだ。これらが合わさって強力な呪文を紡ぎ出す。Darrowshireの霊たちを呼び起こす呪文だ。\n\nその呪文と、少しの幸運があれば、Joseph Redpathを救えるぞ!", 0x0c34da70, 0x164a0999, 0x123d1e2c, 0x8ae7ea24, 0x2f189558, "....." },
  [5942] = { "隠された財宝", "Joseph's KeyをJoseph's Chestへ持って行く。", "パパがね、この鍵をあなたに渡してって。家の裏にある箱が開けられるんだって。\n\nそれから、あなたにお礼を言いたいって。パパに何かしてあげたの？私のお人形を見つけたって言ってくれた？\n\nはい、鍵だよ。ありがとう、{name}。ありがとう！あなたってとってもいい人ね！", "この箱は古く、汚れにまみれている。", "keyが錠に合い、箱が開く……", 0x557f556a, 0xcbae56d2, 0x9a480987, 0x30a3f649, 0x0a527a15, ".....", nil, nil, 0xe14cba19, nil, nil },
  [5943] = { "Gizelton キャラバン", "Mannoroc Coven を過ぎるまで Gizelton Caravan を護衛する。報酬を受け取るには Scrabblescrew's Camp にいる Smeed と話す。", "頼りになりそうな{race}だな。ひと稼ぎしたいんじゃないか？Corkと私は大金を稼ぐためにこの隊商を始めたんだが、金儲けにこんな危険があるとは思いもしなかったよ！\n\nこの先にMannoroc Covenがある……いつもなら悪魔どもは私たちに見向きもしないんだが、今回は何かがkodoを怯えさせているんだ。Mannoroc Covenを過ぎるまで隊商を守ってくれたら金を払おう。無事に通り抜けたら、Scrabblescrew's Campにいる取引相手のSmeedから報酬を受け取ってくれ。", "なあ、もしあのキャラバンが消えちまったら、オレは破産だよ! まさか、キャラバンの悪い知らせを持ってきたんじゃないだろうね?\n\n<Smeedは額の汗をぬぐう。>\n\n強欲の女神に感謝だ!", "Gizelton Caravanを守るのにそんな大金を払うのが割のいい話とは思えんね。CorkとRiggerは週に金貨1枚しか稼いでいない。だが、俺のkodoの代金を払い続けてくれる限り、あいつらがどう商売しようが知ったこっちゃないよ。", 0x263585ae, 0x8ba6f882, 0x4d9b60f3, 0xdd8ee6b2, 0xc76ce493, "....." },
  [5944] = { "夢の中で", "Taelan FordringをHearthglenの外へ導いて下さい。", "長い間、私は大十字軍長の操り人形だった。Scarlet Crusadeが成り果てたものに抗う理由などあっただろうか？ 何十年も経ったが、父の記憶が――あの大切な記憶が、私を生かしてきたのだ。\n\n私は夢を見るのだ、見知らぬ人よ。その夢の中で、父は私と共にいる。私がOrderに迎え入れられる時、父は誇らしげに私の傍らに立っている。我々は肩を並べてScourgeの大軍と戦う。Allianceに、Lordaeronに名誉をもたらすのだ。\n\nもう夢は見たくない。\n\n私を父のもとへ連れて行ってくれ。", "<Tirionは落ち着きを取り戻す。>", "この怪物どもの手にかかった息子の死を、ただで済ませるつもりはない。騎士団が再び生まれ変わったと知って、慰めとするがいい。\n\n私は今、新たなOrder of the Silver Handの大君主としての座に就く。\n\nこれらは我が過去の遺品だ。そなたが成し遂げてくれたすべてに対して、私が差し出せるのはこれだけなのだ。どうか、感謝の証としてこれらを受け取ってほしい。どれも長い年月、私によく尽くしてくれた品だ。\n\nまたいつか、もっとよい時代に再び会い、遠い日々を……激しく戦った数々の戦いを……贖われた夢を、語り合えますように。", 0x743d7929, 0x53749095, 0x545379f7, 0x0d0306a9, 0x74ecb267, "....." },
  [5961] = { "Banshee Queenの闘将", "Eastern PlaguelandsのNathanos Blightcallerと話して下さい。彼はMarris Steadに居を定めたと言われています。", "戦い慣れた者が我らの大義に加わるのを見るのは実に喜ばしい。我らの数は日を追うごとに、規模も力も増している。そなたは己の力量を試す準備ができているのではないか、{class}よ？\n\n我が最初の勇者たちの一人がNathanosだ。今はBlightcallerとして知られている。我らの中で、彼ほどの献身と気迫を持つ者はほとんどいない。\n\nEastern Plaguelandsで彼を探すがよい。彼はMarris Steadに住み、時折荒廃した荒れ地を歩き回っては、行く手を横切るScourgeやAllianceの屑どもをことごとく屠っている。", nil, "確実にDark Ladyは、お前が戦士と会うに値すると信じてはおらん。お前は私の犬どもに餌をやりに来たのだろう? この邪魔に他の理由などあるはずがなかろう。", 0x406ba2fa, 0x06d74e67, 0x946f8091, nil, 0xad0a34c1, "...m." },
})
